// Generated by scripts/gen-l10n.mjs (gdetail n4, id) — 不要手改;改翻譯請改 scripts/out/l10n/id/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["id"]=Object.assign(window.GRAMMAR_DETAIL_L10N["id"]||{},{"n4-20":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Dua pola ini mirip banget. Bedanya ada di akhir: <b>なる</b> atau <b>する</b>.<br><b>ようになる</b> = 「<b>jadi</b> ～」, bicara soal <b>hasil</b>: dulu belum bisa, sekarang sudah bisa.<br><b>ようにする</b> = 「aku <b>berusaha</b> ～」, bicara soal dirimu yang <b>sedang berusaha</b>. Masih dijalani dan tidak ada jaminan selalu berhasil.<br>Dalam bahasa Indonesia, 「jadi／menjadi」 dan 「berusaha」 pas banget dengan なる dan する.</div><div class='gd-h'>ようになる：dulu belum bisa, sekarang sudah</div><div class='gd-sec'><span class='gd-tag'>Perubahan kemampuan</span>Ini yang paling sering muncul. Di depannya dipasang <b>bentuk potensial</b> (bentuk yang berarti 「bisa～」, seperti <span class='gd-jp'>話せる</span> dan <span class='gd-jp'>食べられる</span>), atau <span class='gd-jp'>できる</span> dan <span class='gd-jp'>わかる</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>練習して、日本語が少し話せるようになりました。</span>（Setelah latihan, sekarang aku jadi bisa bicara bahasa Jepang sedikit）</div><div class='gd-ex-line'>・<span class='gd-jp'>辛い物が食べられるようになった。</span>（Sekarang aku jadi berani makan makanan pedas）</div><div class='gd-sec'><span class='gd-tag'>Perubahan kebiasaan</span>Di depannya dipasang bentuk kamus biasa. Artinya 「jadi mulai melakukan hal itu」.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来てから、毎朝コーヒーを飲むようになった。</span>（Sejak datang ke Jepang, aku jadi minum kopi setiap pagi）</div><div class='gd-sec'>Perubahannya bisa hasil latihanmu sendiri, bisa juga terjadi tanpa terasa. Intinya sama, yaitu <b>hasil di saat ini</b>.</div><div class='gd-h'>ようにする：aku berusaha melakukannya</div><div class='gd-sec'>Hal yang mau dilakukan: bentuk kamus＋ようにする　<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるようにする</span></span><br>Hal yang tidak mau dilakukan: bentuk ない＋ようにする　<span class='gd-pair'><span class='gd-jp'>飲まない</span> → <span class='gd-jp'>飲まないようにする</span></span></div><div class='gd-sec'><span class='gd-tag'>ようにしている</span>Kebiasaan yang terus kamu jaga belakangan ini. Ini yang paling sering dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日野菜を食べるようにしています。</span>（Aku berusaha makan sayur setiap hari）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜はコーヒーを飲まないようにしている。</span>（Aku berusaha tidak minum kopi di malam hari）</div><div class='gd-sec'><span class='gd-tag'>ようにします</span>Artinya mulai sekarang kamu akan lebih hati-hati. Sering dipakai saat minta maaf atau berjanji.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからは遅れないようにします。</span>（Mulai sekarang aku akan berusaha tidak terlambat）</div><div class='gd-sec'><span class='gd-tag'>ようにしてください</span>Meminta lawan bicara berusaha melakukannya. Dokter dan guru sering memakainya.</div><div class='gd-ex-line'>・<span class='gd-jp'>薬は毎日飲むようにしてください。</span>（Tolong ingat minum obatnya setiap hari）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Untuk bilang 「jadi <b>bisa</b> ～」, di depannya harus pakai bentuk potensial. <span class='gd-jp'>日本語が話せるようになった</span> baru berarti 「jadi bisa bicara bahasa Jepang」. Kalau ditulis <span class='gd-jp'>日本語を話すようになった</span>, artinya jadi 「mulai (sering) bicara bahasa Jepang」. Itu soal kebiasaan, bukan kemampuan.<br>・Kalau pakai bentuk potensial, 「を」 di depannya biasanya berganti menjadi 「が」: <span class='gd-jp'>日本語が話せる</span>.<br>・Untuk 「jadi <b>tidak</b> ～ lagi」, orang Jepang biasanya langsung bilang <b>〜なくなる</b>: <span class='gd-jp'>最近、テレビを見なくなった。</span>（Belakangan ini aku jadi tidak menonton TV lagi）. 「見ないようになった」 lebih jarang dipakai.<br>・Kata sifat dan kata benda tidak bisa disambung ke ようになる. 「Jadi besar」 itu <span class='gd-jp'>大きくなる</span>, 「jadi sepi／tenang」 itu <span class='gd-jp'>静かになる</span>, 「jadi guru」 itu <span class='gd-jp'>先生になる</span>. ようになる hanya dipakai dengan kata kerja.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Soal bangun pagi, coba lihat tiga cara bilangnya:<br><b>ようになった</b> = hasil: <span class='gd-jp'>早く起きられるようになった。</span>（Aku jadi bisa bangun pagi）<br><b>ようにしている</b> = sedang berusaha: <span class='gd-jp'>早く起きるようにしている。</span>（Aku berusaha bangun pagi）<br><b>ことにした</b> = mengambil keputusan: <span class='gd-jp'>明日から早く起きることにした。</span>（Aku memutuskan mulai besok bangun pagi）</div><div class='gd-sec'>Satu lagi: <b>ことになった</b> artinya 「diputuskan／diatur jadi begitu」. Bukan kamu yang berubah dan bukan hasil usahamu sendiri: <span class='gd-jp'>来月から大阪で働くことになった。</span>（Mulai bulan depan aku akan bekerja di Osaka）</div><div class='gd-warn'>Trik menentukan: 「jadi bisa ～」 pakai ようになる, 「berusaha ～」 pakai ようにする, 「memutuskan ～」 pakai ことにする, 「diatur／diputuskan ～」 pakai ことになる.</div><div class='gd-h'>Bisa dipelajari setelah ini</div><div class='gd-sec'>Kalau なる dan する dibuang, 「ように」 yang berdiri sendiri bisa berarti 「supaya ～」: <span class='gd-jp'>忘れないように、メモします。</span>（Supaya tidak lupa, aku mencatatnya）</div>","n4-8":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「のに」 itu sama dengan <b>「padahal ～, kok …」</b> dalam bahasa Indonesia. Bagian depan adalah hal yang pasti, tapi hasil di belakangnya tidak sesuai dugaanmu. Kamu jadi merasa 「kok bisa begini」. Perasaannya bisa kesal, kaget, atau sayang.</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んだのに、熱が下がらない。</span>（Padahal sudah minum obat, demamnya tidak turun juga）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'>Bagian depan berisi <b>fakta yang sudah pasti</b>. Bisa hal yang sudah terjadi, keadaan sekarang, atau hal yang pasti akan terjadi. Bagian belakang berisi hasil yang 「seharusnya tidak begitu」.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したのに、彼は来なかった。</span>（Padahal sudah janji, dia tidak datang）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いのに、おいしい。</span>（Padahal murah, tempat ini enak）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日テストなのに、全然勉強していない。</span>（Padahal besok ada ujian, dia sama sekali tidak belajar）</div><div class='gd-sec'>Contoh kedua di atas itu kejutan yang menyenangkan. Jadi のに tidak selalu untuk mengeluh. Intinya adalah <b>「berlawanan dengan dugaan」</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya pakai bentuk biasa (bentuk tanpa ます).<br><b>Kata kerja</b>: <span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったのに</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないのに</span></span><br><b>Kata sifat-い</b>: <span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いのに</span></span><br><b>Kata sifat-な dan kata benda</b>: harus ditambah 「な」 dulu.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなのに</span></span><span class='gd-pair'><span class='gd-jp'>日曜日</span> → <span class='gd-jp'>日曜日なのに</span></span><br>Kalau membicarakan masa lampau, pakai だった: <span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったのに</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Kalimat tidak diselesaikan</span>Hasil di belakangnya tidak diucapkan, jadi tersisa kesan 「haah…」. Sering dipakai untuk mengeluh atau menyesal.</div><div class='gd-ex-line'>・<span class='gd-jp'>せっかく作ったのに…。</span>（Padahal aku sudah susah-susah membuatnya…）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata sifat-な dan kata benda, harus ada な. Bilangnya <span class='gd-jp'>静かなのに</span>, tidak boleh 「静かのに」 atau 「静かだのに」.<br>・Setelah のに, <b>tidak boleh ada kalimat berisi kemauan sendiri, ajakan, perintah, atau permintaan</b>, seperti 「ayo ～」, 「aku akan ～」, atau 「tolong ～」.<br>　× 高いのに、買おう。<br>　○ <span class='gd-jp'>高いけど、買おう。</span>（Memang mahal, tapi ayo beli）<br>・のに membawa emosi. Kalau langsung bilang 「～のに」 kepada orang yang lebih tua atau tamu, bisa terdengar seperti mengeluh atau menyalahkan mereka. Hati-hati dengan situasinya.<br>・Ada 「のに」 lain yang bentuknya sama, artinya 「untuk melakukan ～ (dipakai／dibutuhkan)」: <span class='gd-jp'>駅へ行くのに30分かかる。</span>（Untuk pergi ke stasiun butuh 30 menit）. Di sini tidak ada arti 「padahal」. Kamu bisa membedakannya dengan melihat apakah di belakangnya ada 「butuh waktu／perlu／dipakai」.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>のに</b> = padahal ～ kok … (ada emosi): <span class='gd-jp'>薬を飲んだのに、熱が下がらない。</span>（Padahal sudah minum obat, demamnya tidak turun. Kok bisa begini?）<br><b>けど</b> = meskipun ～ tapi … (hanya pertentangan biasa, lebih tenang): <span class='gd-jp'>薬を飲んだけど、熱が下がらない。</span>（Sudah minum obat, tapi demamnya belum turun）<br><b>ても</b> = meskipun ～ tetap …, bisa dipakai untuk pengandaian yang belum terjadi: <span class='gd-jp'>明日雨が降っても、行きます。</span>（Meskipun besok hujan, aku tetap pergi）<br>Kalimat ini tidak bisa diganti dengan のに, karena belum pasti besok hujan atau tidak, dan di belakangnya adalah hal yang akan kamu lakukan sendiri.</div><div class='gd-sec'><b>ので</b> artinya justru berlawanan, yaitu 「karena ～ jadi …」, mengikuti alur hasil yang wajar:<br><span class='gd-jp'>雨なので、出かけなかった。</span>（Karena hujan, aku tidak keluar）<br><span class='gd-jp'>雨なのに、彼は出かけた。</span>（Padahal hujan, dia malah keluar）</div><div class='gd-warn'>Trik menentukan: kalau bagian depan adalah fakta pasti (bukan pengandaian) dan kamu merasa 「kok bisa begini」, pakai のに. Kalau hanya pertentangan biasa, pakai けど. Untuk 「meskipun ～ tetap」, pakai ても. Kalau hasilnya wajar dan masuk akal, pakai ので.</div>","n4-18":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜ために」ditaruh setelah sebab, artinya <b>「karena ～」「disebabkan ～」</b>. Nadanya lebih formal dan objektif, seperti pengumuman di stasiun: 「Karena gangguan sinyal, kereta akan terlambat」. Pola ini sering muncul di berita, pengumuman, atau saat menjelaskan situasi kepada tamu dan atasan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Berita・Pengumuman</span>Menyampaikan apa yang terjadi dan akibatnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>大雪のために、新幹線が止まりました。</span>（Karena salju lebat, Shinkansen berhenti beroperasi）</div><div class='gd-sec'><span class='gd-tag'>Penjelasan formal</span>Dipakai untuk menjelaskan kepada guru, atasan, atau tamu kenapa ada masalah. Kedengarannya objektif, tidak seperti mencari alasan.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が遅れたために、授業に間に合いませんでした。</span>（Karena kereta terlambat, saya tidak sempat masuk kelas）</div><div class='gd-sec'>Hasil di bagian belakang biasanya hal yang <b>sudah terjadi dan di luar kendali kita</b>, dan sering berupa hal yang kurang menyenangkan, misalnya berhenti beroperasi, terlambat, atau dibatalkan.</div><div class='gd-h'>Cara menyambungkan</div><div class='gd-sec'>Di depan ために ada \"sebab\", dan berbagai jenis kata bisa dipakai. Yang perlu kamu ingat: kata benda perlu tambahan 「の」, kata sifat-な perlu tambahan 「な」.<br>Bentuk た kata kerja：<span class='gd-pair'><span class='gd-jp'>起きた</span> → <span class='gd-jp'>起きたために</span></span><br>Bentuk ない kata kerja：<span class='gd-pair'><span class='gd-jp'>足りない</span> → <span class='gd-jp'>足りないために</span></span><br>Sedang berlangsung（ている）：<span class='gd-pair'><span class='gd-jp'>工事をしている</span> → <span class='gd-jp'>工事をしているために</span></span><br>Kata kerja yang menyatakan keadaan（ある、いる、できる）：<span class='gd-pair'><span class='gd-jp'>用事がある</span> → <span class='gd-jp'>用事があるために</span></span><br>Kata sifat-い langsung disambung：<span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いために</span></span><br>Kata sifat-な tambah な：<span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便なために</span></span><br>Kata benda tambah の：<span class='gd-pair'><span class='gd-jp'>大雪</span> → <span class='gd-jp'>大雪のために</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>道が狭いために、大きい車は通れません。</span>（Karena jalannya sempit, mobil besar tidak bisa lewat）</div><div class='gd-ex-line'>・<span class='gd-jp'>用事があるために、会議に出られません。</span>（Karena ada urusan, saya tidak bisa menghadiri rapat）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>のため</span>Dalam pengumuman dan siaran, 「に」 sering dihilangkan sehingga menjadi 「〜のため」「〜ため」. Artinya sama, tapi terdengar lebih formal.</div><div class='gd-ex-line'>・<span class='gd-jp'>工事中のため、この道は通れません。</span>（Sedang ada pengerjaan, jalan ini tidak bisa dilewati）</div><div class='gd-ex-line'>・<span class='gd-jp'>台風のため、明日の授業は休みです。</span>（Karena topan, kelas besok libur）</div><div class='gd-h'>Hal yang gampang salah</div><div class='gd-warn'>・Setelah kata benda, 「の」 wajib ditambahkan: harus <span class='gd-jp'>大雪のために</span>, tidak boleh 大雪ために. Kata sifat-な butuh 「な」: <span class='gd-jp'>不便なために</span>.<br>・Di belakangnya tidak boleh ada kalimat yang meminta lawan bicara melakukan sesuatu atau mengajak, seperti 「～てください」「～ましょう」.<br>×<span class='gd-jp'>雨のために、傘を持っていってください。</span><br>○<span class='gd-jp'>雨なので、傘を持っていってください。</span>（Karena hujan, tolong bawa payung）<br>・Nadanya kaku. Kalau ngobrol dengan teman lalu bilang <span class='gd-jp'>雨のために行かない</span>, rasanya seperti membacakan siaran pers. Dengan teman, pakai 「から」 saja.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ために (tujuan) vs ために (sebab)</b>: ini kata yang sama. Kamu menentukannya dari apa yang ada di depannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行くために、お金をためています。</span>（Untuk pergi ke Jepang, saya menabung: tujuan）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪が降ったために、電車が遅れました。</span>（Karena turun salju, kereta terlambat: sebab）</div><div class='gd-sec'>「Kata benda＋のために」bisa berarti keduanya. Lihat apakah kata bendanya itu target yang ingin dicapai, atau peristiwa yang sudah terjadi:</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝走っています。</span>（Demi kesehatan, saya lari setiap pagi）</div><div class='gd-ex-line'>・<span class='gd-jp'>病気のために、学校を休みました。</span>（Karena sakit, saya tidak masuk sekolah）</div><div class='gd-warn'>Tips menentukan: lihat bagian di depan ために. Kalau berupa tindakan yang bisa kamu kendalikan dan ingin kamu capai (misalnya bentuk kamus dari <span class='gd-jp'>合格する</span>, <span class='gd-jp'>買う</span>), artinya \"untuk/demi\". Kalau berupa bentuk た, なかった, ている, kata kerja keadaan seperti <span class='gd-jp'>ある</span>, <span class='gd-jp'>いる</span>, <span class='gd-jp'>できる</span>, kata sifat, atau kata benda yang menyatakan peristiwa atau keadaan seperti <span class='gd-jp'>台風</span>, <span class='gd-jp'>病気</span>, <span class='gd-jp'>事故</span>, artinya \"karena\".<br>Bentuk ない perlu perhatian khusus: kalau menyambung dengan tindakan yang bisa kamu kendalikan, sering berarti \"supaya tidak ～\", misalnya <span class='gd-jp'>遅れないために、早く家を出ます</span>（Supaya tidak terlambat, saya berangkat dari rumah lebih awal）. Baru kalau menyambung dengan keadaan di luar kendali seperti <span class='gd-jp'>足りない</span>, <span class='gd-jp'>わからない</span>, artinya \"karena\".</div><div class='gd-sec'><b>ために vs から／ので</b>: untuk situasi yang sama, \"hujan, jadi pertandingan dibatalkan\", pilih ungkapan sesuai suasananya.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨だから、試合は中止だって。</span>（Katanya karena hujan, pertandingannya dibatalkan: obrolan dengan teman）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨なので、試合は中止です。</span>（Karena hujan, pertandingan dibatalkan: penjelasan sopan）</div><div class='gd-ex-line'>・<span class='gd-jp'>大雨のため、試合は中止になりました。</span>（Akibat hujan deras, pertandingan dibatalkan: pengumuman, berita）</div><div class='gd-warn'>Tips menentukan: dengan teman pakai 「から」, untuk penjelasan yang sopan pakai 「ので」, dan 「ため（に）」 hanya untuk berita, pengumuman, atau dokumen formal. Kalau di belakangnya ada permintaan kepada lawan bicara, pakai ので atau から, jangan ために.</div>","n4-19":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「<span class='gd-jp'>〜ように</span>」kira-kira berarti <b>「supaya bisa ～」「supaya tidak ～」</b>. Intinya, hasil yang kamu inginkan itu <b>tidak sepenuhnya di tanganmu</b>, jadi kamu hanya bisa bersiap lebih dulu. Contohnya \"pasang dua alarm supaya tidak kesiangan\": kamu tidak bisa mengontrol apakah akan kesiangan, tapi alarmnya bisa kamu pasang.</div><div class='gd-h'>Cara menyambungkan</div><div class='gd-sec'>Bagian depan berisi \"keadaan yang diharapkan\", bagian belakang berisi \"hal yang kamu lakukan untuk itu\".<br><b>Berharap \"bisa ～\"</b>: bentuk potensial＋ように. Bentuk potensial adalah bentuk yang berarti \"bisa ～\", misalnya <span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span>（bisa berbicara）.<br><span class='gd-pair'><span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるように</span></span>（supaya bisa berbicara）<br><b>Berharap \"tidak ～\"</b>: bentuk ない＋ように<br><span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないように</span></span>（supaya tidak lupa）<br><b>Kata kerja yang memang bukan hasil keputusan sendiri</b>（<span class='gd-jp'>わかる</span>、<span class='gd-jp'>治る</span>、<span class='gd-jp'>聞こえる</span>、<span class='gd-jp'>〜になる</span>）: langsung pakai bentuk kamus＋ように<br><span class='gd-pair'><span class='gd-jp'>治る</span> → <span class='gd-jp'>治るように</span></span>（supaya sembuh）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Supaya bisa melakukan</span>Ingin mengembangkan kemampuan tertentu.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が話せるように、毎日練習しています。</span>（Supaya bisa berbahasa Jepang, saya berlatih setiap hari）</div><div class='gd-sec'><span class='gd-tag'>Supaya tidak terjadi</span>Bersiap lebih dulu untuk menghindari hal yang tidak diinginkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないように、メモしておきます。</span>（Supaya tidak lupa, saya catat dulu）</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪をひかないように、暖かくして寝てください。</span>（Supaya tidak masuk angin, tidurlah dengan pakaian hangat）</div><div class='gd-sec'><span class='gd-tag'>Supaya orang lain bisa ～</span>Pelaku di depan dan di belakang boleh berbeda: bagian depan membicarakan orang lain, bagian belakang tindakanmu.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供が食べられるように、小さく切ります。</span>（Supaya anak-anak bisa memakannya, saya potong kecil-kecil）</div><div class='gd-ex-line'>・<span class='gd-jp'>後ろの人にも聞こえるように、大きい声で話します。</span>（Supaya orang di belakang juga bisa mendengar, saya bicara dengan suara keras）</div><div class='gd-h'>Hal yang gampang salah</div><div class='gd-warn'>・Untuk mengatakan \"supaya <b>bisa</b> berbicara\", pakai bentuk potensial <span class='gd-jp'>話せる</span>. Kalau memakai <span class='gd-jp'>話す</span> yang asli, makna \"bisa\" hilang.<br>・Di depan ように selalu bentuk kamus atau bentuk ない, bahkan kalau seluruh kalimatnya tentang masa lalu: <span class='gd-jp'>忘れないように、メモしました。</span>（Supaya tidak lupa, saya mencatatnya）Tidak boleh jadi 「忘れなかったように」.<br>・Dalam bahasa Indonesia, \"untuk\" atau \"agar\" dipakai untuk banyak hal, tapi dalam bahasa Jepang tidak semuanya pakai ように. Tindakan yang bisa langsung kamu lakukan sesuka hati, seperti membeli, pergi, atau belajar, memakai <span class='gd-jp'>ために</span>（lihat di bawah）.<br>・ように sendiri tidak mengatur sopan atau tidaknya. Itu tergantung akhir kalimat: <span class='gd-jp'>メモします</span> sopan, <span class='gd-jp'>メモする</span> versi santai dengan teman.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama membicarakan \"tujuan belajar bahasa Jepang\":<br><span class='gd-jp'>日本で働くために、日本語を勉強しています。</span>（Saya belajar bahasa Jepang untuk bekerja di Jepang）<br><span class='gd-jp'>日本人と話せるように、日本語を勉強しています。</span>（Saya belajar bahasa Jepang supaya bisa mengobrol dengan orang Jepang）<br>\"Pergi bekerja ke Jepang\" adalah tindakan yang bisa kamu lakukan begitu kamu memutuskannya, jadi pakai <b>ために</b>. \"Bisa mengobrol dengan orang Jepang\" adalah kemampuan yang muncul perlahan setelah belajar dan tidak bisa kamu dapatkan seketika, jadi pakai <b>ように</b>. Sebaliknya, 「話せるために」 terdengar sangat tidak natural.<br>Satu hal lagi: kalau pelaku di depan dan di belakang berbeda, seperti <span class='gd-jp'>子供が食べられるように、小さく切ります</span>（yang makan anak, yang memotong saya）, ように-lah yang tepat. ために biasanya dipakai kalau pelakunya sama.</div><div class='gd-warn'>Tips menentukan: kalau di depannya \"bisa ～\", \"tidak ～\", atau hal yang di luar kendalimu, pakai ように. Kalau di depannya tindakan yang bisa langsung kamu lakukan sesuka hati, pakai ために.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau ように langsung disambung dengan <span class='gd-jp'>する</span>, artinya menjadi \"berusaha ～\": <span class='gd-jp'>毎日野菜を食べるようにしています。</span>（Saya berusaha makan sayur setiap hari）<br>ように yang berdiri sendiri lalu disambung tindakan lain berarti \"supaya ～\", sedangkan <span class='gd-jp'>ようにする</span> berarti \"berusaha ～\". Jangan sampai tertukar.</div>","n4-30":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Ketiga pola ini setara dengan \"<b>membantu</b>\" atau \"<b>tolong</b>\" dalam bahasa Indonesia. Kalau kamu membantu orang lain, pakai <b>てあげる</b>. Kalau orang lain membantu kamu, pakai <b>てくれる</b>. Kalau kamu menerima bantuan dari orang lain, pakai <b>てもらう</b>. Arahnya sama persis dengan あげる・くれる・もらう untuk memberi barang. Bedanya, yang diberikan bukan hadiah, tapi \"bantuan melakukan sesuatu\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah verba ke bentuk て dulu, lalu sambung dengan あげる／くれる／もらう.<br><span class='gd-pair'><span class='gd-jp'>貸す</span> → <span class='gd-jp'>貸して</span> → <span class='gd-jp'>貸してあげる</span></span><br><span class='gd-pair'><span class='gd-jp'>作る</span> → <span class='gd-jp'>作って</span> → <span class='gd-jp'>作ってくれる</span></span><br><span class='gd-pair'><span class='gd-jp'>撮る</span> → <span class='gd-jp'>撮って</span> → <span class='gd-jp'>撮ってもらう</span></span><br>Kalau mau lebih sopan, pakai あげます、くれます、もらいます.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Aku membantu orang lain</span><b>てあげる</b>. Polanya: 「私は 相手に ～てあげる」.</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を読んであげました。</span>(Aku membacakan buku untuk adikku)</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちに傘を貸してあげた。</span>(Aku meminjamkan payung kepada temanku)</div><div class='gd-sec'><span class='gd-tag'>Orang lain membantuku</span><b>てくれる</b>. Polanya: 「相手が ～てくれる」. Kata \"untukku\" biasanya tidak perlu disebut, karena くれる sendiri sudah berarti \"datang ke arahku\". Keluarga juga dianggap bagian dari \"pihak aku\".</div><div class='gd-ex-line'>・<span class='gd-jp'>母がお弁当を作ってくれた。</span>(Ibu membuatkan bekal untukku)</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちが駅まで送ってくれました。</span>(Temanku mengantarku sampai stasiun)</div><div class='gd-sec'><span class='gd-tag'>Aku menerima bantuan</span><b>てもらう</b>. Polanya: 「私は 相手に ～てもらう」. Di sini 「に」 berarti \"<b>dari siapa</b>\" kamu menerima bantuan.</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちに写真を撮ってもらいました。</span>(Aku minta temanku memotretkan aku)</div><div class='gd-ex-line'>・<span class='gd-jp'>美容院で髪を切ってもらいました。</span>(Aku memotong rambut di salon)</div><div class='gd-sec'>Rambut dipotong oleh penata rambut, bukan oleh dirimu sendiri. Makanya dalam bahasa Jepang, pakai てもらう itu sangat alami.</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Meminta tolong</span>Kalau mau minta tolong, kamu bisa langsung bertanya \"Bisa tolong ～ nggak?\"</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと手伝ってくれない？</span>(Bisa bantu sebentar nggak? — ke teman)</div><div class='gd-ex-line'>・<span class='gd-jp'>このペンを貸してもらえませんか。</span>(Boleh saya pinjam pulpen ini? — sopan)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・くれる hanya bisa mengarah ke \"aku (pihakku)\". Kalau aku yang membantu orang lain, pasti pakai あげる. Kamu tidak bisa bilang 「私が友だちに貸してくれた」.<br>・「に」 di もらう bukan \"kepada\": <span class='gd-jp'>友だちに手伝ってもらった</span> artinya \"temanku membantuku\", bukan \"aku membantu temanku\". Kalau terpaku pada arti \"kepada\", gampang terbalik.<br>・Partikel untuk orang yang dibantu tergantung pada verba aslinya, jadi tidak selalu に. \"Membawakan barang Ibu\" adalah <span class='gd-jp'>母の荷物を持ってあげた</span>. Kalau bilang \"母に持ってあげた\", terdengar tidak alami.<br>・Dalam bahasa Indonesia kita cukup bilang \"temanku mengajariku bahasa Jepang\". Dalam bahasa Jepang, kalau hanya bilang <span class='gd-jp'>友だちが日本語を教えた</span>, kesannya seperti menceritakan urusan orang lain, dan rasa terima kasihnya hilang. Untuk hal yang dilakukan orang lain demi kamu, orang Jepang hampir selalu menambahkan てくれる: <span class='gd-jp'>友だちが日本語を教えてくれた</span>.<br>・てあげる punya nuansa \"aku sengaja membantumu\". Kepada guru atau atasan, mengatakan 「持ってあげましょうか」 itu tidak sopan. Pakai <span class='gd-jp'>お持ちしましょうか</span>. Hati-hati juga saat bilang \"aku sudah membantunya\" kepada orang lain, karena bisa terdengar seperti mencari pujian.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>てくれる dan てもらう sering membicarakan hal yang sama, hanya sudut pandangnya berbeda:<br><span class='gd-jp'>友だちが手伝ってくれた。</span>(Temanku membantuku) Tokohnya teman, fokusnya \"temanku baik sekali\".<br><span class='gd-jp'>友だちに手伝ってもらった。</span>(Aku minta tolong temanku) Tokohnya aku, fokusnya \"aku menerima bantuan\".<br>Di kebanyakan situasi, keduanya bisa dipakai. Tapi kalau itu <b>kebaikan hati yang datang atas inisiatif orang itu</b>, くれる paling alami: <span class='gd-jp'>頼んでいないのに、友だちが手伝ってくれた。</span>(Aku tidak minta, tapi temanku datang membantu)<br>Kalau kamu <b>sendiri yang meminta atau membayar orang untuk melakukannya</b>, もらう lebih sering dipakai: <span class='gd-jp'>店の人に包んでもらいました。</span>(Aku minta pegawai toko membungkuskannya)</div><div class='gd-warn'>Trik cepat: kalau aku yang membantu orang lain, pakai あげる. Kalau subjeknya orang itu dan diikuti が, pakai くれる. Kalau subjeknya aku dan orang itu diikuti に, pakai もらう.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kepada guru atau orang yang lebih tua, ganti ke versi bahasa hormat:<br><span class='gd-jp'>先生が教えてくださいました。</span>(Guru mengajariku)<br><span class='gd-jp'>先生に教えていただきました。</span>(Aku diajari oleh guru)<br>Saat meminta tolong, 「〜てもらえませんか」 versi yang lebih sopan lagi adalah 「〜ていただけませんか」. Pola-pola ini bisa kamu pelajari bersama 尊敬語 dan 謙譲語.</div>","n4-17":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ために」 setara dengan <b>\"untuk ～\" atau \"demi ～\"</b>. Bagian depan berisi tujuan yang ingin kamu capai, dan bagian belakang berisi hal yang <b>sengaja kamu lakukan</b> demi tujuan itu. Misalnya \"Untuk membeli mobil, aku menabung\" dalam bahasa Jepang adalah: <span class='gd-jp'>車を買うために、お金をためています。</span></div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Verba</b>: langsung pakai bentuk kamus (bentuk dasar yang kamu temukan di kamus) + ために.<br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買うために</span></span><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強するために</span></span><br><b>Nomina</b>: di tengah harus ditambah 「の」.<br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族のために</span></span><span class='gd-pair'><span class='gd-jp'>健康</span> → <span class='gd-jp'>健康のために</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Untuk mencapai sesuatu</span>Di depan ada verba, yang menyatakan tujuan yang ingin kamu capai.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を勉強するために、日本へ来ました。</span>(Aku datang ke Jepang untuk belajar bahasa Jepang)</div><div class='gd-ex-line'>・<span class='gd-jp'>資格試験に合格するために、毎日図書館へ通っています。</span>(Untuk lulus ujian sertifikasi, aku pergi ke perpustakaan setiap hari)</div><div class='gd-sec'><span class='gd-tag'>Demi kebaikan seseorang atau sesuatu</span>Di depan ada nomina, artinya \"memikirkan demi hal itu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のために、頑張って働いています。</span>(Aku bekerja keras demi keluarga)</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝走っています。</span>(Demi kesehatan, aku berlari setiap pagi)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah nomina, の wajib ada: <span class='gd-jp'>家族ために</span> itu salah, yang benar <span class='gd-jp'>家族のために</span>.<br>・Di depan ために <b>selalu bentuk kamus</b>, bahkan saat seluruh kalimat membicarakan masa lalu: <span class='gd-jp'>切符を買うために、早く家を出ました。</span>(Untuk membeli tiket, aku berangkat dari rumah lebih awal) Tidak bisa jadi 買ったために.<br>・Bagian depan dan belakang biasanya dilakukan oleh <b>orang yang sama</b>: aku melakukan sesuatu sendiri demi tujuanku. Kalau maksudnya \"supaya anak bisa kuliah\", itu hal yang harus dicapai orang lain, jadi pakai ように: <span class='gd-jp'>子どもが大学に行けるように、働いています。</span>(Aku bekerja supaya anakku bisa kuliah)<br>・Di depannya jangan pakai bentuk \"bisa ～\" (bentuk potensial): <span class='gd-jp'>日本語が話せるために</span> terdengar tidak alami, yang benar <span class='gd-jp'>日本語が話せるように</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>ために vs ように (tujuan)</b><br>Keduanya bisa diterjemahkan jadi \"untuk\" atau \"agar\", bedanya ada pada bentuk kata di depannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞を読むために、漢字を勉強しています。</span>(Untuk membaca koran bahasa Jepang, aku belajar kanji)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞が読めるように、漢字を勉強しています。</span>(Agar bisa membaca koran bahasa Jepang, aku belajar kanji)</div><div class='gd-sec'>Di depan ために adalah \"<b>melakukan</b> sesuatu\" (<span class='gd-jp'>読む</span>). Di depan ように adalah \"<b>bisa ～</b>\" atau \"menjadi suatu keadaan\" (<span class='gd-jp'>読める</span>).</div><div class='gd-sec'><b>ために (tujuan) vs ために (sebab)</b><br>Bentuk penulisannya sama persis, tapi ために juga bisa berarti \"karena\".</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、野菜を食べています。</span>(Aku makan sayur demi kesehatan)</div><div class='gd-ex-line'>・<span class='gd-jp'>雨のために、試合が中止になりました。</span>(Karena hujan, pertandingan dibatalkan)</div><div class='gd-sec'>Kalau bagian belakang adalah hal yang kamu <b>lakukan dengan sengaja</b>, artinya \"untuk\". Kalau bagian belakang adalah hasil yang <b>sudah terjadi dan tidak bisa dipilih</b>, artinya \"karena\". Pemakaian untuk sebab ini agak formal. Dalam percakapan sehari-hari, \"karena\" biasanya pakai <span class='gd-jp'>から</span> atau <span class='gd-jp'>ので</span>.</div><div class='gd-warn'>Trik cepat: kalau di depan \"melakukan ～\", pakai ために. Kalau di depan \"bisa ～\", pakai ように. Kalau di belakang adalah hal yang sengaja kamu lakukan, ために artinya \"untuk\". Kalau di belakang adalah hasil yang terjadi, ために artinya \"karena\".</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Ganti ために dengan 「ための＋nomina」, artinya \"… untuk ～\": <span class='gd-jp'>留学のためのお金をためています。</span>(Aku menabung uang untuk belajar ke luar negeri)</div>","n4-28":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「ところ」awalnya berarti 「tempat」, tapi di sini artinya berubah jadi <b>satu titik dalam waktu</b>. Padanannya dalam bahasa Indonesia pas sekali: <b>「baru mau ~」「sedang ~」「baru saja ~」</b>. Kamu tinggal mengubah bentuk kata kerja di depannya, dan itu sudah menunjukkan sampai tahap mana sebuah kegiatan berlangsung.</div><div class='gd-h'>Satu situasi, tiga jawaban</div><div class='gd-sec'>Temanmu menelepon dan bertanya 「<span class='gd-jp'>今、大丈夫？</span>」(Sekarang bisa ngobrol?). Kamu bisa menjawab begini:</div><div class='gd-ex-line'>・<span class='gd-jp'>ごめん、今から出かけるところ。</span>(Maaf, aku baru mau keluar)</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べているところ。</span>(Aku lagi makan sekarang)</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょうど今、家に着いたところ。</span>(Aku baru saja sampai rumah)</div><div class='gd-sec'>Inilah momen yang paling sering memakai 「ところ」: <b>menjelaskan keadaanmu saat ini kepada lawan bicara</b>. Ke teman cukup bilang 「ところ」 saja. Kalau mau lebih sopan, tambahkan 「です」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Baru mau</span>Bentuk kamus (bentuk dasar yang kamu temukan di kamus) ＋ところ. Kegiatannya <b>belum dimulai</b>, tapi sebentar lagi mulai.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるところです</span></span>(baru mau makan)</div><div class='gd-ex-line'>・<span class='gd-jp'>これから晩ご飯を作るところです。</span>(Aku baru mau mulai masak makan malam)</div><div class='gd-sec'><span class='gd-tag'>Sedang</span>ている＋ところ. Kegiatannya <b>sedang di tengah jalan</b> dan belum selesai.<br><span class='gd-pair'><span class='gd-jp'>食べている</span> → <span class='gd-jp'>食べているところです</span></span>(sedang makan)</div><div class='gd-ex-line'>・<span class='gd-jp'>今、宿題をしているところです。</span>(Sekarang aku lagi mengerjakan PR)</div><div class='gd-sec'><span class='gd-tag'>Baru saja selesai</span>Bentuk た (bentuk lampau) ＋ところ. Kegiatannya <b>baru saja berakhir</b>.<br><span class='gd-pair'><span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたところです</span></span>(baru selesai makan)</div><div class='gd-ex-line'>・<span class='gd-jp'>今、起きたところです。</span>(Aku baru bangun)</div><div class='gd-sec'>Kata yang sering muncul bersamanya: <span class='gd-jp'>これから</span>、<span class='gd-jp'>今から</span> (untuk baru mau), <span class='gd-jp'>今</span> (untuk sedang), <span class='gd-jp'>ちょうど</span>、<span class='gd-jp'>今</span> (untuk baru saja selesai).</div><div class='gd-h'>Bisa juga untuk masa lalu</div><div class='gd-sec'>Ganti 「です」 dengan 「でした」, dan kamu bisa menceritakan kamu sedang ada di tahap mana pada <b>suatu saat di masa lalu</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>電話が来たとき、お風呂に入っているところでした。</span>(Waktu telepon masuk, aku lagi mandi)</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が来たとき、ちょうど出かけるところでした。</span>(Waktu temanku datang, aku kebetulan baru mau keluar)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Ketiganya adalah titik waktu yang berbeda, jadi kalau salah sambung, artinya ikut melenceng: <b>bentuk kamus＝belum mulai、ている＝sedang berlangsung、bentuk た＝baru selesai</b>. 「<span class='gd-jp'>食べるところです</span>」 artinya 「baru mau makan」, bukan 「sedang makan」.<br>・Sebelum ところ harus pakai bentuk biasa, tidak boleh ます: yang benar <span class='gd-jp'>行くところです</span>, bukan 行きますところです.<br>・「ているところ」 membicarakan tindakan yang sedang berlangsung pada <b>satu titik waktu</b> (sekarang, atau satu saat di masa lalu). Kebiasaan sehari-hari hanya bisa pakai ている biasa: <span class='gd-jp'>毎日日本語を勉強しています。</span>(Aku belajar bahasa Jepang setiap hari). Jangan bilang 「毎日勉強しているところです」.<br>・Keadaan yang terus bertahan seperti 「住んでいる」「結婚している」 juga tidak bisa ditambah ところ.<br>・「たところ」 berarti <b>benar-benar baru saja</b>, biasanya hanya beberapa menit atau paling lama beberapa jam yang lalu. Kalau kamu sudah tiga bulan di Jepang, jangan bilang 「来たところです」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>たところ</b> dan <b>たばかり</b> (n4-29) sama-sama diterjemahkan jadi 「baru saja ~」.<br>Di momen kamu baru masuk stasiun, keduanya boleh dipakai: <span class='gd-jp'>今、駅に着いたところです。</span>／<span class='gd-jp'>今、駅に着いたばかりです。</span>(Aku baru sampai di stasiun)<br>Tapi kalau sudah lewat beberapa waktu dan <b>kamu sendiri merasa itu masih baru</b>, hanya たばかり yang bisa dipakai: <span class='gd-jp'>日本に来たばかりです。</span>(Aku baru saja datang ke Jepang, misalnya sudah tiga bulan)<br>Selain itu, たばかり bisa langsung diletakkan di depan kata benda: <span class='gd-jp'>買ったばかりの靴</span>(sepatu yang baru dibeli), sedangkan たところ tidak bisa dipakai begitu.</div><div class='gd-warn'>Trik menentukan: kalau benar-benar baru saja dan waktunya sangat tepat, pakai たところ. Kalau sudah lewat beberapa waktu tapi rasanya masih baru, pakai たばかり.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau di depan 「bentuk kamus＋ところでした」 kamu tambahkan 「<span class='gd-jp'>もう少しで</span>」, artinya jadi 「nyaris ~」: <span class='gd-jp'>もう少しで電車に遅れるところでした。</span>(Nyaris saja ketinggalan kereta)</div>","n4-31":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜そう」 artinya <b>「kelihatannya ~」「sepertinya mau ~」</b>. Dipakai saat kamu melihat sesuatu dengan mata, lalu langsung muncul sebuah kesan. Contohnya, melihat kue lalu bilang 「kelihatannya enak banget」, atau melihat langit gelap lalu bilang 「sepertinya mau hujan」.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kata kerja: hampir terjadi</span>Kamu melihat tanda-tandanya, lalu merasa sesuatu sebentar lagi terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>空が暗いですね。雨が降りそうです。</span>(Langitnya gelap ya. Sepertinya mau hujan)</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ボタンが取れそう。</span>(Ah, kancingnya hampir lepas)</div><div class='gd-sec'><span class='gd-tag'>Kata sifat: kelihatannya ~</span>Kesan yang kamu rasakan dari penampilan luar.</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしそう！</span>(Kue ini kelihatannya enak banget!)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは今日も元気そうですね。</span>(Pak Tanaka hari ini kelihatannya sehat dan semangat juga ya)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: ubah dulu ke bentuk ます, buang ます, lalu tambahkan そう.<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降ります</span> → <span class='gd-jp'>降りそう</span></span><br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣きそう</span></span><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できそう</span></span></div><div class='gd-sec'><b>Kata sifat い</b>: buang 「い」 di akhir, lalu tambahkan そう.<br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしそう</span></span><span class='gd-pair'><span class='gd-jp'>熱い</span> → <span class='gd-jp'>熱そう</span></span></div><div class='gd-sec'><b>Kata sifat な</b>: langsung tambahkan そう, tanpa だ.<br><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気そう</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇そう</span></span></div><div class='gd-sec'><b>Dua pengecualian, hafalkan saja</b>: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさそう</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なさそう</span></span><br>Untuk bilang 「kelihatannya tidak ~」, kata sifat disambung dari bentuk negatifnya: <span class='gd-pair'><span class='gd-jp'>おいしくない</span> → <span class='gd-jp'>おいしくなさそう</span></span><br>Untuk kata kerja yang berarti 「kelihatannya tidak akan ~」, pakai <span class='gd-jp'>降りそうにない</span> atau <span class='gd-jp'>降りそうもない</span> (kelihatannya tidak akan hujan).</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>そう dipakai seperti kata sifat な: sebelum kata benda jadi <b>そうな</b>, sebelum kata kerja jadi <b>そうに</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>おいしそうなパンですね。</span>(Rotinya kelihatan enak ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもたちが楽しそうに遊んでいる。</span>(Anak-anak bermain dengan kelihatan senang)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Bentuk そう dari <span class='gd-jp'>いい</span> adalah <b>よさそう</b>, bukan いさそう. Sedangkan <span class='gd-jp'>いいそう</span> akan jadi 「katanya bagus」.<br>・<span class='gd-jp'>かわいそう</span> artinya 「kasihan」, bukan 「kelihatannya imut」.<br>・Untuk hal yang jelas terlihat langsung, tidak perlu そう. Kalau bunganya cantik, langsung bilang <span class='gd-jp'>きれいですね</span>, bukan きれいそう yang berarti 「kelihatannya cantik」.<br>・そう yang ini tidak bisa langsung ditempel pada kata benda. 「Kelihatannya seperti pelajar」 tidak boleh dibilang 学生そう.<br>・Kata kerja＋そう sering berarti 「<b>hampir</b> ~」, bukan sekadar 「sepertinya」: <span class='gd-jp'>泣きそう</span> artinya 「hampir menangis」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>「〜そうです (kabar dari orang lain)」 di pelajaran berikutnya artinya <b>「katanya ~」</b>. Bentuknya hampir sama persis, bedanya hanya pada bentuk kata yang ada di depannya. Lihat perbandingan dengan kata yang sama:<br><b>Kata kerja</b>: <span class='gd-jp'>雨が降りそうです。</span>(Kelihatannya sebentar lagi hujan)<br>　　　<span class='gd-jp'>雨が降るそうです。</span>(Katanya akan hujan)<br><b>Kata sifat い</b>: <span class='gd-jp'>おいしそうです。</span>(Kelihatannya enak)<br>　　　　<span class='gd-jp'>おいしいそうです。</span>(Katanya enak)<br><b>Kata sifat な</b>: <span class='gd-jp'>元気そうです。</span>(Kelihatannya sehat dan semangat)<br>　　　　<span class='gd-jp'>元気だそうです。</span>(Katanya sehat dan semangat)</div><div class='gd-warn'>Trik menentukan: kalau di depan そう ada bentuk kamus atau bentuk biasa (<span class='gd-jp'>降る</span>、<span class='gd-jp'>おいしい</span>、<span class='gd-jp'>元気だ</span>) ＝ katanya. Kalau kata kerjanya dibuang ます, kata sifat い dibuang い, dan kata sifat な langsung disambung tanpa だ (<span class='gd-jp'>降り</span>、<span class='gd-jp'>おいし</span>、<span class='gd-jp'>元気</span>) ＝ kelihatannya.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Lanjut ke 「〜そうです (kabar dari orang lain)」, lalu latih keduanya bersamaan. Setelah itu belajar 「〜ようです・〜みたいです」, yaitu 「sepertinya ~」 yang berdasarkan petunjuk yang kamu temukan.</div>","n4-22":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ても」sama dengan <b>“meskipun ～ tetap …” “walaupun ～ tetap …”</b>. Bagian depan mundur satu langkah dulu, mengakui ada suatu keadaan; bagian belakang bilang: hasilnya tetap sama, tidak terpengaruh. Misalnya “meskipun hujan, aku tetap pergi”, dalam bahasa Jepang jadi <span class='gd-jp'>雨が降っても、行きます。</span></div><div class='gd-h'>Cara membentuknya</div><div class='gd-sec'><b>Kata kerja</b>: ubah dulu ke bentuk て, lalu tambahkan 「も」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いても</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでも</span></span>（kalau bentuk て-nya berakhiran 「で」, jadinya 「でも」）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べても</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しても</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ても</span>（きても）</span></div><div class='gd-sec'><b>Kata sifat-い</b>: ganti 「い」 di akhir dengan 「く」, lalu tambahkan 「ても」.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くても</span></span><span class='gd-pair'><span class='gd-jp'>悪い</span> → <span class='gd-jp'>悪くても</span></span></div><div class='gd-sec'><b>Kata sifat-な・kata benda</b>: langsung tambahkan 「でも」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かでも</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨でも</span></span></div><div class='gd-sec'><b>Meskipun tidak ～</b>: ganti 「ない」 pada bentuk ない dengan 「なくても」.<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなくても</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Meskipun terjadi</span>Berandai-andai dulu tentang suatu keadaan, lalu bilang bahwa keputusanmu tidak akan berubah.</div><div class='gd-ex-line'>・<span class='gd-jp'>体調が悪くても、試合に出ます。</span>（Meskipun badan kurang sehat, aku tetap ikut bertanding）</div><div class='gd-ex-line'>・<span class='gd-jp'>高くても、買います。</span>（Meskipun mahal, aku tetap beli）</div><div class='gd-sec'><span class='gd-tag'>Sudah dicoba tapi tetap sia-sia</span>Sudah benar-benar dilakukan, tapi hasilnya tetap tidak sesuai harapan.</div><div class='gd-ex-line'>・<span class='gd-jp'>何度読んでも、意味がわかりません。</span>（Sudah dibaca berkali-kali pun tetap tidak mengerti）</div><div class='gd-ex-line'>・<span class='gd-jp'>電話しても、出ません。</span>（Ditelepon pun dia tidak mengangkat）</div><div class='gd-sec'><span class='gd-tag'>Apa pun yang terjadi</span>Kalau di depannya ada kata seperti <span class='gd-jp'>いくら</span>、<span class='gd-jp'>どんなに</span>、<span class='gd-jp'>何を</span>、<span class='gd-jp'>誰が</span>, artinya jadi “seberapa pun ～ tetap …”.</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら食べても、太りません。</span>（Sebanyak apa pun makan, tidak gemuk）</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに忙しくても、朝ごはんは食べます。</span>（Sesibuk apa pun, aku tetap sarapan）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が来ても、ドアを開けないでください。</span>（Siapa pun yang datang, jangan buka pintu）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata kerja seperti <span class='gd-jp'>読む</span>、<span class='gd-jp'>飲む</span>、<span class='gd-jp'>遊ぶ</span> yang bentuk て-nya berakhiran 「で」 harus jadi <span class='gd-jp'>読んでも</span>, bukan 読んても.<br>・Kata benda dan kata sifat-な disambung dengan 「でも」: <span class='gd-jp'>雨でも</span>、<span class='gd-jp'>元気でも</span>. <span class='gd-jp'>いい</span> harus berubah jadi <span class='gd-jp'>よくても</span>, bukan いくても.<br>・Kalimat bagian belakang harus menyatakan “hasilnya tidak berubah / berlawanan dengan dugaan”. Kalau hasilnya memang wajar dan sesuai dugaan, untuk pengandaian pakai たら (atau ば); から dan ので baru dipakai kalau sudah menjadi fakta dan kamu menyebut alasan.<br>　<span class='gd-jp'>雨が降ったら、行きません。</span>（Kalau hujan, aku tidak pergi）<br>　<span class='gd-jp'>雨が降っても、行きます。</span>（Meskipun hujan, aku tetap pergi）<br>・Makna “tetap / pun” sudah terkandung di dalam ても, jadi di kalimat belakang tidak perlu menambah 「も」 lagi. Kalau bilang <span class='gd-jp'>雨が降っても、私も行きます</span>, artinya jadi “aku juga (seperti orang lain) pergi”.<br>・Jangan tertukar dengan 「〜てもいいです」: di belakangnya ada いいです, jadi artinya “boleh ～”. <span class='gd-jp'>食べてもいいです。</span>（Boleh makan）／<span class='gd-jp'>食べても、太りません。</span>（Meskipun makan, tidak akan gemuk）</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>のに</b> juga terasa seperti “padahal”, tapi cara pakainya berbeda. Dalam situasi hujan yang sama:<br><span class='gd-jp'>雨でも、行きます。</span>（Meskipun hujan aku tetap pergi: menyatakan keputusanku, hujan atau tidak sekarang tidak masalah）<br><span class='gd-jp'>雨なのに、彼は行きました。</span>（Padahal hujan, dia tetap pergi: sudah terjadi, dengan nuansa heran atau tidak setuju）<br>Inti dari <b>ても</b> adalah “apa pun yang ada di depan tidak bisa mengubah hal di belakang”; bisa berupa pengandaian, bisa juga hal yang sudah dicoba.<br>Bagian depan <b>のに</b> pasti hal yang sudah benar-benar terjadi, nadanya “padahal ～ kok …”, sering berisi keluhan atau keheranan. Selain itu, setelah のに tidak bisa dipakai ungkapan seperti “aku akan ～” atau “tolong ～”.</div><div class='gd-warn'>Tips menentukan: kalau mau bilang “meskipun ～, aku akan / tolong kamu ～”, pakai ても; kalau mau mengeluh “padahal ～, kok malah ～”, pakai のに.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau ditambah <span class='gd-jp'>たとえ</span> di depan, nuansanya jadi lebih kuat: <span class='gd-jp'>たとえ反対されても、留学します。</span>（Meskipun ditentang, aku tetap akan belajar ke luar negeri）</div>","n4-24":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜てしまう」mirip dengan <b>“～ sampai habis”, “～ tuntas”, “tidak sengaja ～”</b>.<br>Artinya ada dua: pertama <b>dilakukan sampai selesai / habis</b>, misalnya “kuenya dimakan sampai habis”; kedua <b>tidak sengaja melakukan dan menyesal</b>, misalnya “aduh, dompetku ketinggalan”. Kesamaan kedua makna ini: <b>hal itu sudah terjadi dan tidak bisa diulang</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Selesai semuanya</span>Menekankan bahwa seluruh pekerjaan benar-benar tuntas atau habis; sering terasa seperti “sekali jalan langsung ～” atau “cepat diberesin”.</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題はもう全部やってしまいました。</span>（PR-nya sudah kukerjakan semua）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯の前に、宿題をやってしまおう。</span>（Sebelum makan, selesaikan PR dulu yuk）</div><div class='gd-sec'><span class='gd-tag'>Tidak sengaja・menyesal</span>Melakukan hal yang tidak ingin dilakukan, atau terjadi hasil yang tidak diinginkan, dan di hati kamu merasa “aduh” atau “sayang banget”. Makna inilah yang paling sering dipakai sehari-hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>財布を忘れてしまいました。</span>（Aduh, dompetku ketinggalan）</div><div class='gd-ex-line'>・<span class='gd-jp'>大事なお皿を割ってしまった。</span>（Piring yang penting itu terlanjur kupecahkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝、寝坊してしまいました。</span>（Tadi pagi aku kesiangan）</div><div class='gd-sec'>Kadang kedua makna muncul bersamaan, tergantung konteks: <span class='gd-jp'>ケーキを全部食べてしまった。</span> bisa berarti sekadar “kuenya habis dimakan”, bisa juga “tanpa sengaja kumakan semuanya (aduh)”.</div><div class='gd-h'>Cara membentuknya</div><div class='gd-sec'>Ubah dulu kata kerja ke bentuk て, lalu tambahkan <b>しまう</b>.<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れて</span> → <span class='gd-jp'>忘れてしまう</span></span><br><span class='gd-pair'><span class='gd-jp'>割る</span> → <span class='gd-jp'>割って</span> → <span class='gd-jp'>割ってしまう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んでしまう</span></span><br>しまう sendiri berubah seperti kelompok pertama (kata kerja godan): bentuk sopannya <span class='gd-jp'>しまいます</span>, lampaunya <span class='gd-jp'>しまいました</span>, dan antarteman <span class='gd-jp'>しまった</span>. Karena biasanya yang dibicarakan adalah hal yang sudah terjadi, <b>yang paling sering kamu dengar adalah bentuk lampau</b>.</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Singkatan lisan</span>Dalam percakapan, 「てしまう」 sering disingkat jadi <b>ちゃう</b>, dan 「でしまう」 jadi <b>じゃう</b>.<br><span class='gd-pair'><span class='gd-jp'>食べてしまった</span> → <span class='gd-jp'>食べちゃった</span></span><br><span class='gd-pair'><span class='gd-jp'>行ってしまう</span> → <span class='gd-jp'>行っちゃう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲んでしまった</span> → <span class='gd-jp'>飲んじゃった</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ケーキ全部食べちゃった。</span>（Ah, kuenya kumakan habis semua）</div><div class='gd-sec'><span class='gd-tag'>Berdiri sendiri</span><span class='gd-jp'>しまった！</span> yang spontan keluar saat sadar melakukan kesalahan artinya “Gawat!” “Celaka!”.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata kerja yang bentuk て-nya berakhiran 「んで」 (<span class='gd-jp'>飲む</span>、<span class='gd-jp'>読む</span>、<span class='gd-jp'>遊ぶ</span>、<span class='gd-jp'>死ぬ</span>) disambung dengan <b>でしまう</b>, dan singkatannya <b>じゃう</b>: <span class='gd-jp'>飲んじゃった</span>, bukan 飲んちゃった.<br>・ちゃう dan じゃう adalah ragam lisan, wajar dipakai dengan teman; kepada atasan, tamu, atau saat menulis surat, lebih aman pakai <span class='gd-jp'>〜てしまいました</span>.<br>・Kata kerja <span class='gd-jp'>しまう</span> yang berdiri sendiri artinya “menyimpan / membereskan”: <span class='gd-jp'>本をかばんにしまう。</span>（Menyimpan buku ke dalam tas）. Kalau di depannya tidak ada bentuk て, itu bukan tata bahasa ini.<br>・Dalam bahasa Indonesia, cukup bilang “aku lupa”, jadi banyak orang tidak menambahkan しまう. <span class='gd-jp'>忘れた</span> memang tidak salah secara tata bahasa, tapi terdengar hanya menyatakan fakta; baru dengan <span class='gd-jp'>忘れてしまった</span> perasaan “aduh, menyesal” muncul.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk hal yang sama, bentuk lampau biasa 「た」 dan 「てしまった」 terasa berbeda:<br><b>た</b> = sekadar menyatakan apa yang terjadi: <span class='gd-jp'>財布を忘れた。</span>（Aku lupa bawa dompet）<br><b>てしまった</b> = ditambah perasaan “gawat, sayang banget”: <span class='gd-jp'>財布を忘れてしまった。</span>（Duh, aku lupa bawa dompet）<br><br><b>た</b> = makan: <span class='gd-jp'>ケーキを食べた。</span>（Aku makan kue）<br><b>てしまった</b> = dimakan sampai habis, atau tanpa sengaja termakan: <span class='gd-jp'>ケーキを食べてしまった。</span>（Kuenya kumakan sampai habis）</div><div class='gd-warn'>Tips menentukan: kalau dalam bahasa Indonesia kamu ingin menambahkan “～ sampai habis”, “～ tuntas”, atau “aduh, ～”, pakai てしまう; kalau cuma bercerita biasa tentang apa yang terjadi, た saja sudah cukup.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Yang juga berbentuk “bentuk て + satu kata kerja” ada <span class='gd-jp'>〜ておく</span> (menyiapkan sesuatu sebelumnya); bisa kamu bandingkan bersama. Singkatan lisan seperti ちゃう dan じゃう akan dirangkum sekaligus di pelajaran 「縮約表現」.</div>","n4-32":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜そうです」yang ini artinya <b>“katanya ~”</b> atau <b>“konon ~”</b>. Bedanya, bahasa Jepang menaruhnya di <b>akhir</b> kalimat. Kalau kamu mendengar sesuatu dari berita, prakiraan cuaca, atau temanmu lalu mau menyampaikannya ke orang lain, tambahkan「そうです」di belakang kalimat itu. Maknanya: “ini bukan kata-kataku, aku cuma dengar dari orang lain”.</div><div class='gd-ex-line'>・<span class='gd-jp'>新しい社長は厳しいそうです。</span>（Katanya direktur yang baru itu tegas）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったそうです。</span>（Katanya Tanaka sudah pulang）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya taruh <b>bentuk biasa (普通形)</b>, yaitu bentuk “gaya teman” tanpa ます dan です. Gampangnya begini: ucapkan dulu kalimat yang kamu dengar dalam gaya teman sampai lengkap, lalu tempelkan そうです di belakangnya.<br><b>Kata kerja</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るそうです</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないそうです</span></span><span class='gd-pair'><span class='gd-jp'>結婚した</span> → <span class='gd-jp'>結婚したそうです</span></span><br><b>Kata sifat-い</b>：langsung disambung.<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いそうです</span></span><br><b>Kata sifat-な dan kata benda</b>：harus tambahkan <b>だ</b> dulu.<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだそうです</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だそうです</span></span></div><div class='gd-h'>Pola yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Sebut sumbernya dulu</span>Di depannya sering dipasangkan dengan「〜によると」（menurut ~）atau「〜の話では」（menurut cerita ~） untuk menjelaskan dulu dari mana kamu mendengarnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報によると、明日は雨だそうです。</span>（Menurut prakiraan cuaca, besok akan hujan）</div><div class='gd-ex-line'>・<span class='gd-jp'>林さんの話では、あの店はおいしいそうです。</span>（Menurut cerita Pak Lin, toko itu enak）</div><div class='gd-sec'><span class='gd-tag'>Ngobrol dengan teman</span>Ganti です jadi だ, maka jadilah gaya teman：<span class='gd-jp'>明日は休みだそうだ。</span>Tapi saat ngobrol dengan teman, orang lebih sering bilang「〜んだって」atau「〜って」：<span class='gd-jp'>明日、休みなんだって。</span>（Katanya besok libur）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kesalahan paling umum adalah kata benda dan kata sifat-な yang <b>lupa diberi だ</b>：yang benar <span class='gd-jp'>雨だそうです</span>、<span class='gd-jp'>元気だそうです</span>. Tanpa だ, artinya bisa meleset atau kalimatnya malah tidak terbentuk (dijelaskan di bawah).<br>・Di depannya tidak boleh bentuk ます：yang benar <span class='gd-jp'>行くそうです</span>, bukan「行きますそうです」.<br>・Untuk “katanya <b>dulu</b> ~” atau “katanya <b>tidak</b> ~”, bentuk lampau dan negatifnya ditaruh di kalimat sebelum そうです, sedangkan そうです sendiri tidak berubah：<span class='gd-jp'>雨だったそうです</span>（katanya tadinya hujan）, tidak boleh「雨だそうでした」.<br>・Di bahasa Indonesia “katanya” bisa di awal kalimat, tapi そうです dalam bahasa Jepang selalu di akhir kalimat.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>「様態そうです」（kelihatannya ~）di pelajaran sebelumnya bentuknya persis sama. Bedanya ada di <b>apa yang disambung di depannya</b>：<br><span class='gd-jp'>このかばんは高いそうです。</span>（Katanya tas ini mahal: kata orang lain）<br><span class='gd-jp'>このかばんは高そうです。</span>（Tas ini kelihatannya mahal: kamu lihat sendiri）<br><br><span class='gd-jp'>雨が降るそうです。</span>（Katanya akan hujan: setelah melihat prakiraan cuaca）<br><span class='gd-jp'>雨が降りそうです。</span>（Kelihatannya mau hujan: langitnya gelap）<br><br><span class='gd-jp'>先生は元気だそうです。</span>（Katanya guru sehat-sehat saja）<br><span class='gd-jp'>先生は元気そうです。</span>（Guru kelihatan segar）<br><br>「いい」agak khusus: “katanya bagus” adalah <span class='gd-jp'>いいそうです</span>, sedangkan “kelihatannya bagus” adalah <span class='gd-jp'>よさそうです</span>.</div><div class='gd-warn'>Trik membedakan: kalau di depan そうです ada <b>kalimat utuh</b> (高い、降る、元気だ), artinya “katanya”. Kalau bentuknya <b>terpotong di ujung</b> (高、降り、元気), artinya “kelihatannya”.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Ada juga「〜らしいです」yang bisa berarti “katanya, sepertinya”, serta「〜と言っていました」untuk mengutip ucapan orang secara langsung. Dua-duanya enak dipelajari sambil dibandingkan dengan pelajaran ini.</div>","n4-33":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ようです」dan「〜みたいです」artinya <b>“sepertinya ~”</b> atau <b>“kelihatannya ~”</b>. Kamu melihat, mendengar, atau merasakan beberapa petunjuk, lalu menarik kesimpulan sendiri. Artinya sama, tapi <b>ようです lebih formal</b> dan <b>みたいです lebih santai</b>. Untuk ngobrol sehari-hari, みたい paling natural.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menebak berdasarkan petunjuk</span>Ini pemakaian yang paling umum. Kamu tidak 100% yakin, tapi ada buktinya.</div><div class='gd-ex-line'>・<span class='gd-jp'>電気が消えていますね。田中さんはもう帰ったようです。</span>（Lampunya mati ya. Sepertinya Tanaka sudah pulang）</div><div class='gd-ex-line'>・<span class='gd-jp'>外がうるさいですね。何かあったみたいです。</span>（Di luar berisik ya. Sepertinya ada sesuatu yang terjadi）</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪をひいたみたいです。</span>（Sepertinya aku masuk angin）</div><div class='gd-sec'>Kalimat terakhir berdasarkan perasaan di tubuhmu sendiri, misalnya tenggorokan sakit atau menggigil. Itu juga dihitung sebagai petunjuk, jadi sering dipakai.</div><div class='gd-sec'><span class='gd-tag'>Perumpamaan: seperti ~</span>Kamu tahu itu bukan yang sebenarnya, hanya bilang “mirip”. Sering muncul bersama <span class='gd-jp'>まるで</span>（benar-benar, seolah-olah）.</div><div class='gd-ex-line'>・<span class='gd-jp'>まるで夢のようです。</span>（Seperti mimpi saja）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは日本語が上手で、日本人みたいです。</span>（Bahasa Jepang Tanaka bagus sekali, seperti orang Jepang）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja dan kata sifat-い: langsung disambung, sama untuk keduanya.<br><span class='gd-pair'><span class='gd-jp'>帰った</span> → <span class='gd-jp'>帰ったようです</span>／<span class='gd-jp'>帰ったみたいです</span></span><br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいようです</span>／<span class='gd-jp'>忙しいみたいです</span></span></div><div class='gd-sec'><b>Kata sifat-な dan kata benda berbeda</b> (dalam bentuk non-lampau):<br>ようです: kata sifat-な ditambah「な」, kata benda ditambah「の」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなようです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生のようです</span></span><br>みたいです: tidak perlu tambahan apa pun, langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かみたいです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生みたいです</span></span><br>Bentuk lampau keduanya memakai「だった」：<span class='gd-jp'>学生だったようです</span>／<span class='gd-jp'>学生だったみたいです</span>.</div><div class='gd-h'>Pola yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Antar teman</span>Buang です, jadi「〜みたい」atau「〜みたいだね」. <span class='gd-jp'>ようだ</span> lebih bernuansa bahasa tulis dan jarang dipakai dalam obrolan.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店、休みみたい。</span>（Toko itu sepertinya tutup）</div><div class='gd-sec'><span class='gd-tag'>Diikuti kata benda</span>Menjadi「ような／みたいな」+ kata benda, artinya “yang seperti ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんみたいな人になりたいです。</span>（Aku ingin jadi orang seperti Tanaka）</div><div class='gd-sec'><span class='gd-tag'>Diikuti kata kerja</span>Menjadi「ように／みたいに」, artinya “(melakukan) seperti ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもみたいに喜んでいます。</span>（Senang seperti anak kecil）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata benda dan kata sifat-な paling sering salah sambung: yang benar <span class='gd-jp'>学生みたい</span>、<span class='gd-jp'>学生のようです</span>, bukan「学生のみたい」; dan <span class='gd-jp'>静かみたい</span>, bukan「静かなみたい」.<br>・Untuk hal yang sudah kamu lihat sendiri dengan pasti, jangan pakai pola ini: kalau kamu sedang berdiri di tengah hujan, langsung bilang <span class='gd-jp'>雨が降っています</span>. Baru kalau kamu cuma mendengar suara hujan atau melihat orang di luar jendela membuka payung, bilang <span class='gd-jp'>雨が降っているようです</span>.<br>・<span class='gd-jp'>学生みたい</span> bisa berarti “sepertinya dia mahasiswa” (dugaan), bisa juga “seperti mahasiswa” (padahal bukan). Lihat konteksnya.<br>・Untuk laporan atau situasi formal pakai ようです; みたい terlalu santai.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama soal hujan:<br><b>そうです（様態）</b>＝dilihat dari tampak luarnya, <b>hampir</b> begitu: <span class='gd-jp'>雨が降りそうです。</span>（Kelihatannya mau hujan: banyak awan gelap, tapi belum turun）<br><b>ようです／みたいです</b>＝menduga berdasarkan petunjuk bahwa <b>sudah</b> begitu: <span class='gd-jp'>雨が降っているみたいです。</span>（Sepertinya sedang hujan: terdengar suara hujan）<br><b>らしいです</b>＝lebih ke arah <b>kata orang lain</b>: <span class='gd-jp'>東京は雨が降っているらしいです。</span>（Katanya di Tokyo sedang hujan: dari berita atau cerita teman）</div><div class='gd-sec'>Kata sifat juga sama: <span class='gd-jp'>おいしそう</span> artinya “kelihatannya enak”, hanya dari tampilannya; <span class='gd-jp'>おいしいみたい</span> artinya “sepertinya enak”, misalnya karena kamu melihat antrean panjang setiap hari.</div><div class='gd-warn'>Trik membedakan: “hanya dari tampilan, hampir ~” pakai そう; “aku punya petunjuk, menduga sepertinya ~” pakai よう／みたい; “katanya ~ (kata orang)” pakai らしい.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Selanjutnya pelajari <span class='gd-jp'>〜らしいです</span> dan dua jenis <span class='gd-jp'>〜そうです</span>（kelihatannya, katanya）sekaligus sambil dibandingkan. Dengan begitu cara-cara menyatakan dugaan jadi lengkap.</div>","n4-34":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「らしい」punya dua arti. Yang pertama <b>「katanya / sepertinya ～」</b>, seperti saat kamu bilang ke temanmu, “Eh, katanya Nakamura mau pindah kerja.” Kabarnya kamu dengar dari orang lain, jadi kamu sendiri tidak 100% yakin. Yang kedua <b>「benar-benar khas ～」</b>, seperti dalam bahasa Indonesia kita bilang “suasananya musim semi banget” atau “jantan banget”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Katanya・Sepertinya</span>Kabarnya kamu dengar atau lihat dari sumber lain, lalu dari situ kamu menyimpulkan “kayaknya memang begitu”.</div><div class='gd-ex-line'>・<span class='gd-jp'>中村さんは会社をやめるらしいです。</span>（Katanya Nakamura mau berhenti kerja）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店のラーメンはおいしいらしいよ。</span>（Katanya ramen di toko itu enak lho）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは昨日休んだらしいです。</span>（Tanaka kemarin sepertinya izin tidak masuk）</div><div class='gd-sec'><span class='gd-tag'>Benar-benar khas ～</span>Di depannya diletakkan kata benda. Artinya “benar-benar sesuai dengan sosok, peran, atau musim itu”, dan biasanya bernada memuji.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春らしい天気ですね。</span>（Cuaca hari ini terasa musim semi banget ya）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は本当に男らしい人です。</span>（Dia benar-benar orang yang jantan）</div><div class='gd-sec'>「らしい」yang ini dipakai seperti kata sifat berakhiran い (seperti <span class='gd-jp'>高い</span>), jadi bentuk negatifnya <b>らしくない</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はなんだか田中さんらしくないですね。</span>（Hari ini Tanaka entah kenapa kurang seperti biasanya ya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja, kata sifat い</b>: pakai bentuk tanpa ます, lalu sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くらしい</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないらしい</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いらしい</span></span></div><div class='gd-sec'><b>Kata sifat な, kata benda</b>: buang 「だ」 dulu, baru sambung.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → buang だ → <span class='gd-jp'>静からしい</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨らしい</span></span><br>Kalau bentuk lampaunya 「だった」, biarkan saja, jangan dibuang: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったらしい</span></span></div><div class='gd-sec'>Kepada orang yang lebih tua atau di situasi formal, tambahkan 「です」 di belakangnya supaya sopan. Kalau ngobrol dengan teman, cukup 「らしい」.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata sifat な dan kata benda, jangan sisakan 「だ」: yang benar <span class='gd-jp'>静からしい</span>, bukan 静かだらしい.<br>・Bentuk ます tidak bisa langsung disambung らしい: yang benar <span class='gd-jp'>行くらしいです</span>, bukan 行きますらしい.<br>・Kata yang sama bisa punya dua arti: <span class='gd-jp'>あの人は学生らしい。</span> bisa berarti “orang itu sepertinya mahasiswa”. Sedangkan <span class='gd-jp'>本当に学生らしい服ですね。</span> berarti “baju yang benar-benar khas mahasiswa”. Lihat konteksnya. Kalau di depannya ada kata tingkat seperti 「本当に」 atau 「とても」, biasanya itu arti yang kedua.<br>・Arti kedua itu positif, yaitu “sesuai dengan sosoknya”. Kalau bilang anak kecil <span class='gd-jp'>子供らしい</span>, itu memuji kepolosannya. Untuk bilang orang dewasa itu kekanak-kanakan, orang Jepang memakai <span class='gd-jp'>子供っぽい</span>, bukan 子供らしい.<br>・Arti pertama dipakai untuk hal yang kamu dengar dan belum kamu pastikan sendiri. Untuk hal yang kamu lihat langsung dan yakin, katakan saja langsung tanpa らしい.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama membicarakan cuaca besok:<br><b>そうです (kabar)</b>: <span class='gd-jp'>天気予報によると、明日は雨だそうです。</span>（Menurut ramalan cuaca, besok hujan）Sumbernya jelas, dan kamu hanya menyampaikan apa adanya.<br><b>らしいです</b>: <span class='gd-jp'>明日は雨らしいです。</span>（Besok sepertinya hujan）Ini juga kabar yang kamu dengar, tetapi sumbernya lebih samar, seperti “kayaknya semua orang bilang begitu”. Ada sedikit penilaianmu sendiri, jadi nadanya kurang pasti.<br><b>ようです・みたいです</b>: （sambil melihat ke luar jendela）<span class='gd-jp'>雨が降っているみたいです。</span>（Di luar kayaknya sedang hujan）Ini penilaian yang kamu buat setelah melihat atau merasakannya sendiri.</div><div class='gd-sec'>Satu contoh lagi yang sering membingungkan. Ada sepotong kue di meja:<br><span class='gd-jp'>おいしそう！</span>（Kelihatannya enak banget!）Ini kesan dari apa yang dilihat mata, memakai 「そうです (penampilan)」.<br><span class='gd-jp'>このケーキ、おいしいらしいよ。</span>（Katanya kue ini enak lho）Ini kabar dari orang lain.</div><div class='gd-warn'>Trik menilai: kalau kabarnya “kata orang lain”, pakai らしい atau そうです (kabar). Kalau cuma meneruskan kabar apa adanya, pakai そうです. Kalau ada sedikit dugaanmu dan sumbernya samar, pakai らしい. Kalau “kamu lihat atau rasakan sendiri”, pakai ようです, みたいです, atau ～そう (penampilan).</div><div class='gd-h'>Setelah ini, pelajari juga</div><div class='gd-sec'>Ulangi n4-32 「～そうです (kabar)」 dan n4-33 「～ようです・～みたいです」 bersama pelajaran ini. Bedakan dua kelompok: “yang didengar” dan “yang dilihat sendiri”. Dengan begitu kamu tidak gampang salah memakai kalimat dugaan.</div>","n4-35":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜はずです」artinya <b>「seharusnya / mestinya ～」</b> dalam bahasa Indonesia. Kamu punya dasar, misalnya sudah lihat jadwal, pernah dengar langsung darinya, atau tahu dia dokter. Dari dasar itu kamu menarik kesimpulan dan merasa cukup yakin, jadi pakai はず. Seperti “Dia pulang kerja jam enam, jadi sekarang <b>mestinya</b> sudah sampai rumah”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kesimpulan yang ada dasarnya</span>Mulai dari satu alasan “karena ～”, lalu menyimpulkan “jadi mestinya ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは6時に会社を出たから、もう家に着いたはずです。</span>（Pak Tanaka keluar kantor jam enam, jadi sekarang mestinya sudah sampai rumah）</div><div class='gd-ex-line'>・<span class='gd-jp'>木村さんは医者だから、薬に詳しいはずです。</span>（Pak Kimura itu dokter, jadi mestinya paham soal obat）</div><div class='gd-sec'><span class='gd-tag'>Pantas saja</span>Dipakai saat tiba-tiba paham setelah melihat penyebabnya. Sering berbentuk 「〜はずだ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が開いている。寒いはずだ。</span>（Jendelanya terbuka. Pantas saja dingin）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Cara menyambungnya sama seperti saat di belakangnya ada kata benda:<br><b>Kata kerja</b>: bentuk biasa (bentuk tanpa ます), sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くはず</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないはず</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったはず</span></span><br><b>Kata sifat い</b>: sambung langsung. <span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いはず</span></span><br><b>Kata sifat な</b>: tambah 「な」. <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなはず</span></span><br><b>Kata benda</b>: tambah 「の」. <span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みのはず</span></span><br>Untuk bentuk lampau, kata sifat な dan kata benda memakai 「だった」: <span class='gd-jp'>学生だったはず</span>.<br>Ke teman pakai 「はずだ」, ke guru atau tamu pakai 「はずです」.</div><div class='gd-h'>Bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>はずがない</span>Tidak mungkin ～. Penyangkalan yang sangat kuat.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人がうそをつくはずがありません。</span>（Orang itu tidak mungkin berbohong）</div><div class='gd-sec'><span class='gd-tag'>はずだった</span>Seharusnya ～, tetapi ternyata tidak.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車は10時に着くはずだったのに、30分も遅れた。</span>（Kereta seharusnya tiba jam sepuluh, tetapi terlambat sampai tiga puluh menit）</div><div class='gd-sec'><span class='gd-tag'>はずなのに</span>Padahal seharusnya ～, kok bisa begini.</div><div class='gd-ex-line'>・<span class='gd-jp'>鍵はかばんに入れたはずなのに、ない。</span>（Padahal aku yakin sudah memasukkan kunci ke tas, tapi tidak ada）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata “seharusnya” dalam bahasa Indonesia punya dua arti: “Dia seharusnya sudah sampai” itu dugaan, sedangkan “Kamu seharusnya tidur lebih awal” itu saran. <b>はず hanya punya arti dugaan</b>. Untuk memberi saran, pakai <span class='gd-jp'>早く寝たほうがいいですよ</span>. Kalau kamu bilang <span class='gd-jp'>早く寝るはずです</span>, artinya jadi “menurut logika, kamu akan tidur lebih awal”.<br>・Kata benda perlu の, kata sifat な perlu な: yang benar <span class='gd-jp'>休みのはず</span> dan <span class='gd-jp'>静かなはず</span>, bukan 「休みはず」「学生だはず」.<br>・Jangan pakai はず untuk hal yang kamu putuskan sendiri. Dalam bahasa Indonesia sering bilang “Besok kayaknya aku pergi”, tetapi dalam bahasa Jepang katakan <span class='gd-jp'>明日は行くつもりです</span> atau <span class='gd-jp'>行くと思います</span>. Kalau kamu bilang <span class='gd-jp'>行くはずです</span>, kedengarannya seperti “sesuai jadwal yang sudah diatur, aku akan pergi”.<br>・<span class='gd-jp'>来ないはずです</span> artinya “mestinya tidak datang”, yaitu dugaan. <span class='gd-jp'>来るはずがありません</span> artinya “tidak mungkin datang”, nadanya jauh lebih kuat.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama sedang menunggu Pak Tanaka:<br><span class='gd-jp'>田中さんは来るはずです。</span>（Dia sudah bilang akan datang, jadi mestinya datang: ada dasarnya dan kamu yakin）<br><span class='gd-jp'>田中さんは来るでしょう。</span>（Dia mungkin datang ya: tebakan biasa）<br><span class='gd-jp'>田中さんは来るかもしれません。</span>（Dia mungkin datang, mungkin juga tidak: kira-kira fifty-fifty）</div><div class='gd-warn'>Trik menilai: kalau kamu bisa menyebutkan dasarnya “karena ～ jadi ～” dan kamu yakin, pakai はず. Kalau cuma menebak sambil lalu, pakai でしょう. Kalau tidak begitu yakin, pakai かもしれません.</div><div class='gd-h'>Setelah ini, pelajari juga</div><div class='gd-sec'>Di N3 kamu akan belajar 「べき」 (seharusnya melakukan ～), yaitu arti “seharusnya” yang satunya lagi dalam bahasa Indonesia. Ingat はず dan べき secara terpisah, maka kamu tidak akan tertukar lagi.</div>","n4-54":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Bentuk ば kira-kira berarti <b>「asal ～, pasti ～」</b> atau <b>「kalau ～, ya ～」</b>. <span class='gd-jp'>安ければ買います</span>＝Asal murah, aku beli. Fokusnya ada di <b>syarat</b> di bagian depan: kalau syaratnya terpenuhi, hasilnya langsung mengikuti.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Asal ～, pasti ～</span>Kalau satu syarat terpenuhi, hasil tertentu akan muncul.</div><div class='gd-ex-line'>・<span class='gd-jp'>安ければ買います。</span>（Kalau murah, aku beli）</div><div class='gd-ex-line'>・<span class='gd-jp'>急げば間に合いますよ。</span>（Kalau kamu bergegas, masih sempat kok）</div><div class='gd-sec'><span class='gd-tag'>Kebenaran yang tetap</span>Hal-hal alam atau akal sehat yang «selalu begitu setiap kali».</div><div class='gd-ex-line'>・<span class='gd-jp'>春になれば、桜が咲きます。</span>（Kalau sudah musim semi, sakura mekar）</div><div class='gd-sec'><span class='gd-tag'>Kalau tidak ～</span>Versi negatif, sering dipakai untuk mengingatkan «kalau tidak dilakukan, gawat».</div><div class='gd-ex-line'>・<span class='gd-jp'>急がなければ、間に合いません。</span>（Kalau tidak bergegas, tidak akan sempat）</div><div class='gd-h'>Cara membentuknya: lihat dulu jenis kata kerjanya</div><div class='gd-sec'><b>Kelompok 1 (kata kerja godan)</b>: ganti bunyi terakhir dengan bunyi baris「え」pada baris yang sama, lalu tambahkan「ば」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く diganti け → <span class='gd-jp'>行けば</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲めば</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買えば</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待てば</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰れば</span></span></div><div class='gd-sec'><b>Kelompok 2 (kata kerja ichidan)</b>: buang「る」di akhir, lalu tambahkan「れば」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きれば</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見れば</span></span></div><div class='gd-sec'><b>Kelompok 3 (hanya dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すれば</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば</span>（くれば）</span></div><div class='gd-sec'><b>「Kalau tidak ～」</b>: ubah dulu ke bentuk ない, buang 「い」 dari 「ない」, lalu tambahkan 「ければ」.<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなければ</span></span><span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べなければ</span></span></div><div class='gd-sec'><b>Kata sifat-い</b>: buang 「い」 di akhir, lalu tambahkan 「ければ」.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安ければ</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒ければ</span></span><br><b>Kata sifat-な・kata benda</b>: tidak pakai ば, langsung tambahkan 「なら」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなら</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なら</span></span></div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>来れば</span> dibaca <b>くれば</b>, bukan きれば, dan bukan これば.<br>・<span class='gd-jp'>いい</span> harus menjadi <span class='gd-jp'>よければ</span>, tidak ada 「いければ」. Contoh: <span class='gd-jp'>よければ、どうぞ。</span>（Kalau kamu tidak keberatan, silakan）<br>・Kelompok 1 bukan sekadar menambah れば: yang benar <span class='gd-jp'>行けば</span>, bukan 行くれば.<br>・Kalau bagian depan berupa <b>tindakan</b> (pergi, tiba, makan…), dan bagian belakang berisi permintaan 「tolong ～」 atau ajakan 「ayo ～」, memakai ば terdengar janggal. Ganti dengan たら:<br>×駅に着けば、電話してください。<br>○<span class='gd-jp'>駅に着いたら、電話してください。</span>（Kalau sudah sampai di stasiun, telepon aku ya）<br>Kalau bagian depan berupa <b>keadaan</b> (ある、いる、できる, kata sifat), tidak masalah: <span class='gd-jp'>時間があれば、来てください。</span>（Kalau ada waktu, datanglah）</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Bahasa Jepang punya empat jenis 「kalau」. Bandingkan dalam satu situasi yang sama, «pergi ke stasiun»:<br><b>ば</b>＝asal ～, pasti ～: <span class='gd-jp'>駅まで歩けば、10分で着きます。</span>（Kalau jalan kaki ke stasiun, 10 menit sudah sampai）<br><b>たら</b>＝setelah ～; bagian belakang boleh berisi permintaan atau ajakan: <span class='gd-jp'>駅に着いたら、電話してください。</span>（Kalau sudah sampai di stasiun, telepon aku ya）<br><b>と</b>＝begitu ～, pasti terjadi, seperti menunjukkan jalan atau reaksi mesin: <span class='gd-jp'>この道をまっすぐ行くと、駅があります。</span>（Kalau lurus terus di jalan ini, kamu akan menemukan stasiun）<br><b>なら</b>＝menyambung ucapan lawan bicara untuk memberi saran, dan hal itu belum terjadi: <span class='gd-jp'>駅に行くなら、この道が近いですよ。</span>（Kalau kamu mau ke stasiun, lewat jalan ini lebih dekat lho）</div><div class='gd-warn'>Tips menentukan: 「asal ～, pasti」 pakai ば; 「setelah ～」 atau kalau bagian belakang berisi permintaan atau ajakan, pakai たら; 「begitu ～ pasti」 pakai と; 「kalau kamu bilang mau ～」 pakai なら. Kalau ragu, pakai たら dulu, paling kecil kemungkinan salahnya.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Tambahkan 「いい」 di belakangnya jadi 「～ saja sudah bagus」. Sangat sering dipakai untuk menanyakan pendapat orang: <span class='gd-jp'>どうすればいいですか。</span>（Sebaiknya bagaimana ya?）<br>「なければ」 ditambah 「なりません」 berarti 「harus ～」: <span class='gd-jp'>明日は早く起きなければなりません。</span>（Besok aku harus bangun pagi）</div>","n4-55":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜たら」 kira-kira berarti <b>「kalau ～」</b> atau <b>「begitu ～, (baru) ～」</b>. Dipakai untuk kalimat seperti «kalau punya uang, aku mau jalan-jalan» atau «begitu sampai rumah, aku telepon kamu». Ini cara paling umum untuk menyatakan syarat dalam percakapan sehari-hari. Ada juga satu pemakaian khusus: <b>「waktu ～, ternyata ～」</b>.</div><div class='gd-h'>Cara menyambungnya: kalau bisa bentuk た, kamu bisa たら</div><div class='gd-sec'>Buat dulu bentuk た-nya, lalu tambahkan 「ら」. Cara membentuk bentuk た kata kerja sama dengan bentuk て, hanya て diganti た dan で diganti だ.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったら</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span> → <span class='gd-jp'>飲んだら</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたら</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>したら</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来たら</span>（きたら）</span></div><div class='gd-sec'>Kata sifat dan kata benda juga bisa. Caranya sama: ubah dulu ke bentuk lampau, lalu tambahkan ら:<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったら</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇だったら</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったら</span></span><br>Bentuk negatif juga sama: <span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなかったら</span></span>（kalau tidak pergi）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kalau ～</span>Belum tentu terjadi, hanya pengandaian.</div><div class='gd-ex-line'>・<span class='gd-jp'>お金があったら、旅行したい。</span>（Kalau punya uang, aku mau jalan-jalan）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日雨だったら、行きません。</span>（Kalau besok hujan, aku tidak pergi）</div><div class='gd-sec'><span class='gd-tag'>Setelah ～, lalu</span>Hal yang pasti terjadi; dipakai untuk bilang apa yang akan dilakukan «nanti kalau saatnya tiba».</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったら、電話します。</span>（Begitu sampai rumah, aku telepon kamu）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅に着いたら、連絡してください。</span>（Kalau sudah sampai di stasiun, hubungi aku ya）</div><div class='gd-sec'><span class='gd-tag'>Ternyata ～</span>Setelah melakukan sesuatu, kamu menemukan hal yang tak terduga. Bagian belakangnya harus memakai <b>bentuk lampau</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓を開けたら、猫がいた。</span>（Waktu kubuka jendela, ternyata ada kucing）</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったら、母が来ていました。</span>（Waktu pulang ke rumah, ternyata ibuku sudah datang）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・たら selalu berarti <b>bagian depan terjadi lebih dulu, baru bagian belakang</b>. <span class='gd-jp'>日本へ行ったら、ガイドブックを買います。</span> artinya «baru beli setelah sampai di Jepang». Kalau kamu mau bilang «beli sebelum berangkat», pakai なら (dibahas di bawah).<br>・<span class='gd-jp'>来たら</span> dibaca <b>きたら</b>, bukan こたら.<br>・Untuk menceritakan rangkaian hal yang kamu lakukan sendiri di masa lalu, jangan pakai たら. «Setelah pulang, aku makan» adalah <span class='gd-jp'>家に帰って、ご飯を食べました。</span> 「たら＋bentuk lampau」 khusus untuk «lalu bertemu atau menemukan sesuatu», jadi kalau bagian belakangnya tindakan yang sengaja kamu lakukan, terdengar janggal.<br>・Kalau mau menambahkan makna «seandainya», di depan boleh ditaruh <span class='gd-jp'>もし</span>: <span class='gd-jp'>もし雨だったら</span>. Tapi untuk hal yang pasti terjadi seperti «setelah ～», もし tidak boleh dipakai. <span class='gd-jp'>もし家に帰ったら</span> terdengar seperti kamu tidak yakin bisa pulang ke rumah atau tidak.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Di N4 kamu akan belajar empat jenis syarat: たら, ば, と, なら. Lihat semuanya dalam satu situasi yang sama:<br><b>たら</b>＝paling serbaguna; bagian belakang boleh berisi permintaan, harapan, atau rencana: <span class='gd-jp'>春になったら、日本へ行きたい。</span>（Kalau musim semi tiba, aku mau pergi ke Jepang）<br><b>と</b>＝selalu begitu setiap kali, seperti fenomena alam: <span class='gd-jp'>春になると、桜が咲きます。</span>（Begitu musim semi tiba, sakura mekar）<br><b>ば</b>＝menekankan «asal ada syarat ini, pasti ～»: <span class='gd-jp'>春になれば、暖かくなります。</span>（Asal sudah musim semi, cuaca jadi hangat）<br><b>なら</b>＝menyambung ucapan lawan bicara untuk memberi saran, dan <b>boleh menyebut hal di bagian belakang lebih dulu</b>: <span class='gd-jp'>日本へ行くなら、春がいいですよ。</span>（Kalau kamu mau ke Jepang, musim semi paling bagus lho）</div><div class='gd-sec'>Perbedaan paling jelas ada pada «meminta orang lain melakukan sesuatu»: <span class='gd-jp'>駅に着いたら、電話してください。</span> terdengar sangat alami. Kalau diganti jadi 「駅に着くと」 atau 「駅に着けば」 lalu disambung 「電話してください」, orang Jepang akan merasa janggal.</div><div class='gd-warn'>Tips menentukan: kalau bingung, pakai たら dulu, di kebanyakan situasi masih cocok. Pengecualiannya, untuk «selalu begitu setiap kali» lebih sering dipakai と; dan untuk «mendengar lawan bicara mau melakukan sesuatu, lalu memberi saran» pakai なら.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Tambahkan 「いいです」 di belakangnya, maka jadi pemberian saran: <span class='gd-jp'>先生に聞いたらいいですよ。</span>（Tanya saja ke guru, beres kok）</div>","n4-7":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「ので」artinya <b>「karena ~, jadi ~」</b>. Sama seperti「から」, dipakai untuk menyatakan alasan. Bedanya, 「ので」terdengar lebih <b>sopan, seperti sedang menjelaskan keadaan</b>. Kalau dibandingkan dengan bahasa Indonesia, 「から」mirip \"soalnya ~\" atau \"karena ~ sih\", sedangkan「ので」lebih mirip \"berhubung ~\" atau \"mengingat ~\". Kalau menyampaikan alasan kepada guru, atasan, atau tamu, pakai ので dan kamu paling aman.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyampaikan alasan dengan sopan</span>Paling sering dipakai di tempat kerja, di kelas, atau saat bicara dengan orang yang belum akrab.</div><div class='gd-ex-line'>・<span class='gd-jp'>用事があるので、お先に失礼します。</span>（Karena ada urusan, saya permisi duluan）</div><div class='gd-ex-line'>・<span class='gd-jp'>道が混んでいたので、遅れました。</span>（Karena jalanan macet, saya terlambat）</div><div class='gd-sec'><span class='gd-tag'>Meminta tolong</span>Sebutkan alasannya dulu, baru minta tolong. Kedengarannya jadi sangat sopan.</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いので、窓を閉めてください。</span>（Karena dingin, tolong tutup jendelanya）</div><div class='gd-sec'><span class='gd-tag'>Menolak dengan halus</span>Orang Jepang sering hanya menyebut alasan dan tidak menyelesaikan kalimatnya. Lawan bicara sudah mengerti.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日はちょっと用事があるので…。</span>（Besok ada urusan sedikit, jadi…）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja dan kata sifat い</b>: langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くので</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったので</span></span><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いので</span></span></div><div class='gd-sec'><b>Kata sifat な dan kata benda</b>: di tengahnya harus ditambah「な」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなので</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨なので</span></span><br>Untuk hal yang sudah lampau, pakai「だった」: <span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったので</span></span></div><div class='gd-sec'>Kalau mau lebih formal, ので juga bisa disambung setelah ます dan です. Ini sering terdengar di toko dan tempat kerja:<br><span class='gd-jp'>雨が降っていますので、お気をつけください。</span>（Karena sedang hujan, harap berhati-hati）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata benda dan kata sifat な tidak boleh langsung ditambah だ: <span class='gd-jp'>雨だので</span> itu salah, yang benar <span class='gd-jp'>雨なので</span>.<br>・Kata sifat い justru sebaliknya, <b>tidak perlu ditambah な</b>: yang benar <span class='gd-jp'>痛いので</span>, bukan 痛いなので.<br>・Saat menjawab pertanyaan「Kenapa?」, di akhir kalimat boleh bilang <span class='gd-jp'>電車が遅れたからです</span>, tetapi <b>tidak boleh</b> bilang 遅れたのでです.<br>・ので tidak cocok untuk perintah yang kasar. Kalimat seperti「うるさいので、黙れ」terdengar aneh. Untuk kasus begini pakai から.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>から vs ので</b>: sama-sama untuk izin tidak masuk karena demam.<br><span class='gd-jp'>熱があるから、休む。</span>（Aku demam, jadi mau istirahat: ke teman, lebih lugas）<br><span class='gd-jp'>熱があるので、休ませてください。</span>（Karena demam, mohon izinkan saya istirahat: ke atasan, lebih sopan）<br>Untuk memarahi atau memperingatkan, hanya から yang bisa dipakai: <span class='gd-jp'>危ないから、触るな！</span>（Bahaya, jangan disentuh!）</div><div class='gd-sec'><b>ので vs のに</b>: bedanya cuma satu huruf, tetapi artinya jauh berbeda.<br><span class='gd-jp'>薬を飲んだので、治った。</span>（Karena minum obat, jadi sembuh）<br><span class='gd-jp'>薬を飲んだのに、治らない。</span>（Padahal sudah minum obat, tetap tidak sembuh）</div><div class='gd-warn'>Trik cepat: kalau menyebut alasan dan ingin terdengar sopan, pakai ので. Kalau ingin menekankan, nadanya keras, atau sedang memerintah, pakai から. Kalau artinya \"padahal ~, tetapi ~\", itu のに.</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Kalau alasannya lebih dari satu, kamu bisa menyebutkannya satu per satu dengan「し」: <span class='gd-jp'>雨も降っているし、寒いし、今日は出かけない。</span>（Hujan, dingin pula, hari ini tidak keluar）</div>","n4-5":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜やすい」artinya <b>\"mudah ~\"</b> atau <b>\"gampang ~\"</b>, sedangkan「〜にくい」artinya <b>\"sulit ~\"</b> atau <b>\"susah ~\"</b>. Pulpen ini enak dipakai menulis, nama ini susah diingat: dalam bahasa Jepang, semuanya diungkapkan dengan dua pola ini.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ます, buang 「ます」, lalu tambahkan やすい atau にくい.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書きます</span> → buang ます → <span class='gd-jp'>書きやすい</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べにくい</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話しやすい</span></span><span class='gd-pair'><span class='gd-jp'>覚える</span> → <span class='gd-jp'>覚えにくい</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しやすい</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来やすい</span>（きやすい）</span></div><div class='gd-sec'>Setelah tersambung, seluruh kata ini <b>diperlakukan sebagai kata sifat い</b>, dan perubahannya sama seperti「おいしい」:<br><span class='gd-pair'><span class='gd-jp'>書きやすい</span> → <span class='gd-jp'>書きやすかった</span></span>（dulu terasa enak dipakai menulis）<br><span class='gd-pair'><span class='gd-jp'>わかりやすい</span> → <span class='gd-jp'>わかりやすくて</span></span>（mudah dipahami, dan…）<br>Bisa juga langsung ditaruh di depan kata benda: <span class='gd-jp'>使いやすいアプリ</span>（aplikasi yang mudah dipakai）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mudah / susah dilakukan</span>Menyatakan apakah suatu hal terasa lancar atau merepotkan saat orang melakukannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>この靴は軽くて歩きやすいです。</span>（Sepatu ini ringan dan enak dipakai berjalan）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の説明はわかりやすいです。</span>（Penjelasan guru mudah dipahami）</div><div class='gd-ex-line'>・<span class='gd-jp'>この魚は骨が多くて食べにくいです。</span>（Ikan ini banyak durinya, jadi repot memakannya）</div><div class='gd-sec'><span class='gd-tag'>Mudah / tidak mudah terjadi</span>Bukan karena orang sengaja melakukannya, tetapi karena benda atau orangnya <b>memang gampang jadi begitu</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>白い服は汚れやすいです。</span>（Baju putih mudah kotor）</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪をひきやすいです。</span>（Waktu musim dingin mudah masuk angin）</div><div class='gd-ex-line'>・<span class='gd-jp'>このコップは割れにくいです。</span>（Gelas ini tidak mudah pecah）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Yang disambung adalah <b>bentuk ます tanpa ます</b>, bukan bentuk kamus: yang benar <span class='gd-jp'>書きやすい</span>, bukan 書くやすい.<br>・<span class='gd-jp'>食べやすい</span> bukan \"enak\"! Artinya \"mudah dimakan, praktis dimakan\". Kalau mau bilang enak, pakai <span class='gd-jp'>おいしい</span>. Begitu juga <span class='gd-jp'>食べにくい</span> artinya \"susah dimakan, repot dimakan\", bukan \"tidak enak\" (tidak enak itu <span class='gd-jp'>まずい</span>).<br>・Untuk bilang \"susah menulisnya\", orang Jepang biasanya langsung bilang <span class='gd-jp'>書きにくい</span>, lebih natural daripada <span class='gd-jp'>書きやすくない</span>.<br>・<span class='gd-jp'>割れやすい</span> artinya \"mudah pecah\", yaitu menjelaskan sifat bendanya, bukan \"gampang dipecahkan\".</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>「〜そうです」(kelihatannya akan ~) juga disambung dengan bentuk ます tanpa ます, jadi gampang tertukar dengan やすい:<br><b>割れそう</b> = <b>menebak saat itu juga</b> dari penampilannya bahwa benda itu akan pecah: <span class='gd-jp'>このお皿、薄くて割れそう。</span>（Piring ini tipis sekali, kelihatannya bakal pecah）<br><b>割れやすい</b> = kamu memang tahu benda itu <b>mudah pecah</b>, itu sifatnya: <span class='gd-jp'>このお皿は割れやすいから、気をつけて。</span>（Piring ini mudah pecah, hati-hati ya）</div><div class='gd-warn'>Trik cepat: untuk \"kelihatannya akan ~\" pakai そう. Untuk \"memang gampang ~ / enak dilakukan\" pakai やすい.</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Ada juga pola lain yang memakai \"bentuk ます tanpa ます\" lalu ditambah kata lain, misalnya <span class='gd-jp'>食べすぎる</span> (makan berlebihan) dan <span class='gd-jp'>書き方</span> (cara menulis). Kalau cara menyambungnya sudah kamu kuasai, semua ini ikut gampang.</div>","n4-60":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Bentuk kausatif (使役形) itu padanan dari <b>\"menyuruh ~ melakukan\" dan \"membiarkan ~ melakukan\"</b> dalam bahasa Indonesia. Misalnya \"Ibu menyuruh anaknya makan sayur\" atau \"Manajer toko membiarkan pekerja paruh waktu pulang duluan\". Dalam bahasa Jepang, kata kerjanya diubah jadi 「〜せる／〜させる」. Artinya bisa <b>memaksa orang lain melakukan sesuatu (paksaan)</b>, atau <b>orang itu memang ingin melakukannya dan kamu mengizinkan (izin)</b>. Kamu harus menebaknya dari konteks.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Paksaan</span>Menyuruh orang melakukan sesuatu, mau atau tidak mau.</div><div class='gd-ex-line'>・<span class='gd-jp'>母は子供に野菜を食べさせます。</span>(Ibu menyuruh anaknya makan sayur)</div><div class='gd-sec'><span class='gd-tag'>Izin</span>Orang itu ingin melakukannya, lalu kamu membiarkannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供が遊びたがっていたので、公園で遊ばせました。</span>(Anakku ingin sekali bermain, jadi kubiarkan dia bermain di taman)</div><div class='gd-sec'><span class='gd-tag'>Membuat orang merasakan sesuatu</span>Membuat orang lain khawatir atau senang juga memakai bentuk kausatif.</div><div class='gd-ex-line'>・<span class='gd-jp'>親を心配させたくない。</span>(Aku tidak mau membuat orang tuaku khawatir)</div><div class='gd-h'>Cara membentuknya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: ganti bunyi terakhir dengan bunyi baris「あ」yang sebaris, lalu tambahkan「せる」。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti か → <span class='gd-jp'>書かせる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たせる</span></span><br>Yang berakhiran「う」diganti jadi <b>わ</b>:<span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わせる</span></span><br>Trik kecil: bunyinya sama dengan yang dipakai di bentuk ない. Dari <span class='gd-jp'>書かない</span>, buang ない, tambahkan せる, jadilah <span class='gd-jp'>書かせる</span>.</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang「る」di akhir, lalu tambahkan「させる」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させる</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きさせる</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>:<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させる</span>(こさせる)</span><br>Yang seperti <span class='gd-jp'>勉強する</span> dan <span class='gd-jp'>残業する</span> juga sama:<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強させる</span></span></div><div class='gd-sec'>Setelah terbentuk, kata ini jadi kata kerja golongan 2 biasa, jadi bisa diubah seperti biasa: <span class='gd-jp'>書かせます</span>、<span class='gd-jp'>書かせた</span>、<span class='gd-jp'>書かせない</span>.</div><div class='gd-h'>Orang yang disuruh: pakai に atau を?</div><div class='gd-sec'>Pola kalimatnya begini: <b>orang yang menyuruh</b>は　<b>orang yang melakukan</b>に／を　〜させる<br>Cara menentukannya: lihat dulu apakah di kalimat itu <b>ada「を」lain</b> (makan apa, menulis apa).</div><div class='gd-sec'><span class='gd-tag'>Ada を lain</span>Orang yang melakukan hanya boleh pakai <b>に</b>. Bahasa Jepang tidak suka ada dua「を」dalam satu kalimat.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は生徒に作文を書かせます。</span>(Guru menyuruh murid menulis karangan)</div><div class='gd-ex-line'>・<span class='gd-jp'>子供に日本語を勉強させています。</span>(Aku menyuruh anakku belajar bahasa Jepang)</div><div class='gd-sec'><span class='gd-tag'>Tidak ada を lain</span>Boleh pakai <b>を</b> atau <b>に</b>. Kalau pakai を, kesan paksaannya lebih terasa.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生を立たせました。</span>(Guru menyuruh murid berdiri)</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は毎日私を残業させます。</span>(Kepala bagian menyuruhku lembur setiap hari)</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は毎日私に残業させます。</span>(Kepala bagian menyuruhku lembur setiap hari)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>させてください</span>\"Tolong izinkan aku ~\": kamu sendiri yang ingin melakukannya, dan kamu minta persetujuan lawan bicara.</div><div class='gd-ex-line'>・<span class='gd-jp'>少し休ませてください。</span>(Tolong izinkan aku istirahat sebentar)</div><div class='gd-ex-line'>・<span class='gd-jp'>私にやらせてください。</span>(Biar aku saja yang mengerjakannya)</div><div class='gd-sec'><span class='gd-tag'>待たせる</span>\"Membuat orang menunggu\", sangat sering dipakai saat minta maaf.</div><div class='gd-ex-line'>・<span class='gd-jp'>お待たせしました。</span>(Maaf sudah membuat Anda menunggu)</div><div class='gd-ex-line'>・<span class='gd-jp'>待たせてごめんね。</span>(Maaf ya, sudah membuatmu menunggu)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Yang berakhiran「う」berubah jadi <b>わ</b>: yang benar <span class='gd-jp'>買わせる</span>、<span class='gd-jp'>言わせる</span>, bukan「買あせる」.<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>termasuk golongan 1: yang benar <span class='gd-jp'>帰らせる</span>, bukan「帰させる」.<br>・<span class='gd-jp'>来させる</span>dibaca <b>こさせる</b>, bukan きさせる.<br>・Bentuk kausatif itu cara bicara dari atas ke bawah, jadi <b>tidak boleh dipakai untuk orang yang lebih tua atau atasan</b>. Kalau kamu bilang <span class='gd-jp'>先生に説明させる</span> untuk \"Saya minta guru menjelaskan\", kedengarannya sangat tidak sopan. Yang benar: <span class='gd-jp'>先生に説明してもらう</span> (lebih sopan lagi: <span class='gd-jp'>説明していただく</span>).</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>させる vs てもらう</b>: dalam bahasa Indonesia, \"minta teman memotret\" bisa terdengar netral, tapi dalam bahasa Jepang bedanya jauh.<br><span class='gd-jp'>友達に写真を撮らせた。</span>(Aku menyuruh teman memotret: terdengar seperti memerintah orang)<br><span class='gd-jp'>友達に写真を撮ってもらった。</span>(Aku minta teman memotretkan aku: teman membantu, dan ada rasa terima kasih)</div><div class='gd-sec'><b>させる vs される (pasif)</b>: beda satu huruf, arahnya berlawanan total.<br><span class='gd-jp'>友達を1時間待たせた。</span>(Aku membuat temanku menunggu satu jam: itu salahku)<br><span class='gd-jp'>友達に1時間待たされた。</span>(Aku dibuat menunggu temanku satu jam: aku yang dirugikan)</div><div class='gd-warn'>Trik menebak: kalau kamu lihat「<b>せ</b>」, berarti aku menyuruh orang lain; kalau lihat「<b>れ</b>」, berarti aku yang diperlakukan orang lain; kalau mau minta tolong, pakai「てもらう」.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kausatif + pasif = dipaksa melakukan sesuatu (使役受身形): <span class='gd-jp'>母に野菜を食べさせられた。</span>(Aku dipaksa ibu makan sayur)<br>Ada juga <span class='gd-jp'>〜させていただきます</span> yang sering kamu dengar di dunia pelayanan, dan itu juga berasal dari bentuk kausatif.</div>","n4-61":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Bentuk kausatif-pasif (使役受身形) itu padanan dari <b>\"dipaksa ~\" dan \"disuruh ~\"</b> dalam bahasa Indonesia. Intinya: <b>kamu sendiri yang melakukan tindakannya, tapi sebenarnya kamu tidak mau</b>, karena orang lain memaksamu. Misalnya \"Waktu kecil, aku dipaksa ibu makan paprika\": yang makan kamu, yang memaksa ibu, dan nadanya agak mengeluh.</div><div class='gd-h'>Dari mana bentuk ini berasal</div><div class='gd-sec'>Namanya panjang, tapi sebenarnya ini dua hal yang ditumpuk: <b>kausatif</b> (menyuruh orang lain melakukan sesuatu) + <b>pasif</b> (di-~).<br>Lihat dulu dari sudut pandang ibu:</div><div class='gd-ex-line'>・<span class='gd-jp'>母は私にピーマンを食べさせた。</span>(Ibu menyuruhku makan paprika)</div><div class='gd-sec'>Kalau diceritakan dari sudut pandang \"aku\", jadilah kausatif-pasif:</div><div class='gd-ex-line'>・<span class='gd-jp'>私は母にピーマンを食べさせられた。</span>(Aku dipaksa ibu makan paprika)</div><div class='gd-sec'>Orang yang dipaksa (aku) pakai <span class='gd-jp'>は</span> atau <span class='gd-jp'>が</span>, dan orang yang memaksa pakai <b><span class='gd-jp'>に</span></b>.</div><div class='gd-h'>Cara membentuknya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang「る」, lalu tambahkan「させられる」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させられる</span></span></div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: ganti bunyi terakhir dengan bunyi baris「あ」yang sebaris, lalu tambahkan「される」. Ini versi yang paling sering diucapkan orang Jepang.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く diganti か → <span class='gd-jp'>行かされる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まされる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たされる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → う diganti わ → <span class='gd-jp'>買わされる</span></span><br>Menambahkan「せられる」juga benar (<span class='gd-jp'>行かせられる</span>), hanya saja lebih panjang dan lebih jarang terdengar.</div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>:<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させられる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させられる</span>(こさせられる)</span></div><div class='gd-sec'>Untuk bentuk sopan, ganti る di akhir dengan ます:<span class='gd-pair'><span class='gd-jp'>待たされる</span> → <span class='gd-jp'>待たされます</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で30分も待たされた。</span>(Aku terpaksa menunggu 30 menit di stasiun)</div><div class='gd-ex-line'>・<span class='gd-jp'>部長にお酒を飲まされました。</span>(Aku dipaksa kepala bagian minum alkohol)</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃、毎日ピアノを練習させられた。</span>(Waktu kecil, aku dipaksa latihan piano setiap hari)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata kerja golongan 1 yang berakhiran「す」<b>tidak boleh</b> pakai される: <span class='gd-jp'>話す</span> harus jadi <span class='gd-jp'>話させられる</span>, bukan 話さされる.<br>・Yang berakhiran「う」diganti「わ」, bukan「あ」: <span class='gd-jp'>買わされる</span>, bukan 買あされる.<br>・Kausatif-pasif dari <span class='gd-jp'>来る</span> dibaca <b>こさせられる</b>, bukan きさせられる.<br>・<span class='gd-jp'>食べさせる</span> artinya \"menyuruh orang lain makan\", sedangkan <span class='gd-jp'>食べさせられる</span> artinya \"aku dipaksa makan\". Tanpa「られる」, artinya jadi terbalik total.<br>・Bentuk ini membawa rasa \"tidak rela\", jadi jangan dipakai untuk hal yang menyenangkan. Kalau senior mentraktirmu makan, katakan <span class='gd-jp'>先輩におごってもらった</span>. Kalau kamu bilang <span class='gd-jp'>先輩におごらされた</span>, artinya jadi \"aku dipaksa senior mentraktir\".</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>Bentuk pasif (受身形)</b> = tindakan itu dilakukan <b>orang lain</b>, dan kamu yang dikenai: <span class='gd-jp'>先生に叱られた。</span>(Aku dimarahi guru: yang memarahi adalah guru)<br><b>Bentuk kausatif-pasif (使役受身形)</b> = tindakan itu dilakukan <b>kamu sendiri</b>, hanya saja karena dipaksa: <span class='gd-jp'>先生に立たされた。</span>(Aku dihukum guru disuruh berdiri: yang berdiri adalah aku)<br><b>てもらう</b> = orang lain membantumu, dan kamu berterima kasih: <span class='gd-jp'>先生に作文を直してもらった。</span>(Guru membantu mengoreksi karanganku)</div><div class='gd-warn'>Trik menebak: tanya dirimu, \"Siapa yang melakukan tindakan ini?\" Kalau orang lain melakukannya padamu, itu pasif. Kalau kamu sendiri melakukannya dengan terpaksa, itu kausatif-pasif. Kalau orang lain membantumu dan kamu berterima kasih, pakai てもらう.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau mau bilang \"izinkan saya ~\" dengan sopan, pakai bentuk て dari kausatif + <span class='gd-jp'>いただきます</span> (<span class='gd-jp'>〜させていただきます</span>): <span class='gd-jp'>発表する</span> → <span class='gd-jp'>発表させる</span> → <span class='gd-jp'>発表させていただきます。</span>(Izinkan saya mempresentasikannya)</div>","n4-62":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Sonkeigo (bahasa hormat) dipakai saat membicarakan <b>hal yang dilakukan lawan bicara, orang yang lebih tua, atau atasan</b>. Kata kerjanya diganti dengan ungkapan yang lebih hormat. Mirip dengan bahasa Indonesia: “Apakah kamu sudah makan?” menjadi “Apakah Bapak sudah bersantap?”, dan “Guru datang” menjadi “Guru berkenan hadir”. Tindakannya sama, hanya pilihan katanya yang lebih hormat.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'>Dipakai kalau pelakunya adalah orang yang harus kamu hormati, seperti guru, atasan, tamu, atau orang yang lebih tua. Boleh dipakai saat bicara langsung dengannya, atau saat menyebutnya di depan orang lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生はもうお帰りになりました。</span>(Guru sudah pulang.)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は何をなさいますか。</span>(Akhir pekan nanti Anda akan melakukan apa?)</div><div class='gd-h'>Cara membentuknya: pikirkan dua langkah</div><div class='gd-sec'><b>Langkah 1: cek dulu, apakah kata kerjanya punya bentuk hormat khusus</b><br>Kata kerja yang sering dipakai punya bentuk hormatnya sendiri. Kalau ada, biasanya pakai yang itu dulu:<br><span class='gd-pair'><span class='gd-jp'>いる・行く・来る</span> → <span class='gd-jp'>いらっしゃる</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>おっしゃる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる・飲む</span> → <span class='gd-jp'>召し上がる</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>ご覧になる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>なさる</span></span><br><span class='gd-pair'><span class='gd-jp'>くれる</span> → <span class='gd-jp'>くださる</span></span><br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>ご存じだ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>社長は明日大阪へいらっしゃいます。</span>(Besok direktur utama akan pergi ke Osaka.)</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、もうご覧になりましたか。</span>(Buku ini, apakah Anda sudah melihatnya?)</div><div class='gd-sec'><b>Langkah 2: kalau tidak ada bentuk khusus, pakai pola「お＋bentuk ます＋になる」</b><br>Ubah dulu ke bentuk ます, buang ます, lalu tambahkan お di depan dan になる di belakang.<br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待ちます</span> → buang ます → <span class='gd-jp'>お待ちになる</span></span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>お帰りになる</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>お書きになる</span></span><br>Untuk kata kerja berpola 「kata kanji＋する」, biasanya dipakai ご: <span class='gd-pair'><span class='gd-jp'>利用する</span> → <span class='gd-jp'>ご利用になる</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>部長は何時にお戻りになりますか。</span>(Jam berapa Kepala Bagian akan kembali?)</div><div class='gd-sec'>Kata kerja seperti <b>見る・言う・する・いる・来る</b> wajib memakai bentuk khususnya, jangan dipaksa pakai rumus. Untuk sebagian kecil kata kerja seperti <span class='gd-jp'>飲む</span>, dua-duanya benar: <span class='gd-jp'>何を召し上がりますか。</span> dan <span class='gd-jp'>何をお飲みになりますか。</span> (Anda mau minum apa?) sama-sama terdengar natural.</div><div class='gd-sec'>Ada juga bentuk hormat yang lebih ringan, yaitu「れる・られる」(contoh: <span class='gd-jp'>社長が帰られました</span>). Ini dibahas terpisah di n4-74.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Di toko</span><span class='gd-jp'>いらっしゃいませ。</span>(Selamat datang) sebenarnya berasal dari いらっしゃる.<br><span class='gd-tag'>Tolong ～</span>お＋bentuk ます＋ください: <span class='gd-jp'>少々お待ちください。</span>(Mohon tunggu sebentar)<br><span class='gd-tag'>Menanyakan apakah lawan bicara tahu</span><span class='gd-jp'>このお店、ご存じですか。</span>(Apakah Anda tahu toko ini?)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Sonkeigo <b>tidak boleh dipakai untuk dirimu sendiri</b>. Untuk bilang “Saya akan pergi besok”, kamu tidak boleh bilang <span class='gd-jp'>私がいらっしゃいます</span>. Pakai bentuk biasa atau kenjōgo: <span class='gd-jp'>私が参ります</span>.<br>・Kata kerja berikut tidak bisa dipaksa pakai rumus: tidak ada お見になる、お言いになる、おしになる. Yang benar adalah <span class='gd-jp'>ご覧になる</span>, <span class='gd-jp'>おっしゃる</span>, <span class='gd-jp'>なさる</span>.<br>・Bentuk ます-nya gampang tertulis salah: yang benar <span class='gd-jp'>いらっしゃいます</span>, <span class='gd-jp'>おっしゃいます</span>, <span class='gd-jp'>なさいます</span>, <span class='gd-jp'>くださいます</span>, bukan いらっしゃります atau おっしゃります.<br>・Saat membicarakan atasanmu sendiri kepada tamu dari luar perusahaan, jangan pakai sonkeigo. Rendahkan orang dari perusahaanmu sendiri. Misalnya kalau tamu menelepon mencari Kepala Bagian, jawablah <span class='gd-jp'>田中は今おりません。</span>, jangan bilang “部長はいらっしゃいません”.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Kenjōgo (n4-63) juga termasuk bahasa sopan, tapi arahnya berlawanan. Sonkeigo <b>mengangkat lawan bicara</b>, sedangkan kenjōgo <b>merendahkan diri sendiri</b>. Lihat dalam satu percakapan:<br><span class='gd-jp'>A：この資料、ご覧になりましたか。</span>(Dokumen ini, apakah Anda sudah melihatnya? Lawan bicara yang melihat, jadi pakai sonkeigo)<br><span class='gd-jp'>B：はい、拝見しました。</span>(Ya, saya sudah melihatnya. Saya sendiri yang melihat, jadi pakai kenjōgo)<br><span class='gd-jp'>A：何を召し上がりますか。</span>(Anda mau makan apa?)<br><span class='gd-jp'>B：じゃ、ケーキをいただきます。</span>(Kalau begitu, saya makan kue)</div><div class='gd-warn'>Trik menentukan: lihat dulu <b>siapa yang melakukan tindakan itu</b>. Kalau lawan bicara, orang yang lebih tua, atau atasan → sonkeigo. Kalau saya sendiri (atau orang dari pihak saya) → kenjōgo.</div><div class='gd-h'>Setelah ini belajar apa</div><div class='gd-sec'>Lanjut ke kenjōgo (n4-63). Kalau dihafal berdua, kamu paling tidak akan tertukar. Setelah itu lihat juga pemakaian hormat dari「れる・られる」(n4-74).</div>","n4-63":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Kenjōgo (bahasa merendah) artinya <b>merendahkan tindakan diri sendiri, sehingga lawan bicara otomatis terlihat lebih tinggi</b>. Bahasa Indonesia sebenarnya juga punya, misalnya “Izinkan saya memperkenalkan diri”, “Saya mohon pamit”, atau “Saya akan segera menghubungi Bapak”. Kenjōgo bahasa Jepang punya konsep yang sama, tapi dipakai jauh lebih sering.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'>Dipakai kepada tamu, guru, atasan, dan orang lain yang harus kamu hormati, saat membicarakan <b>hal yang akan kamu lakukan sendiri</b>. Kalau kamu kerja paruh waktu, bekerja di kantor, atau menulis surat kepada guru, hampir tiap hari kamu akan menemuinya.</div><div class='gd-h'>Cara 1: お＋kata kerja＋します</div><div class='gd-sec'>Buang「ます」dari bentuk ます, tambahkan「お」di depan dan「します」di belakang.<br><span class='gd-pair'><span class='gd-jp'>持ちます</span> → buang ます → <span class='gd-jp'>お持ちします</span></span><br><span class='gd-pair'><span class='gd-jp'>待ちます</span> → <span class='gd-jp'>お待ちします</span></span><br><span class='gd-pair'><span class='gd-jp'>送ります</span> → <span class='gd-jp'>お送りします</span></span><br>Untuk kata kanji seperti「案内」「連絡」, biasanya ditambahkan「ご」di depan:<br><span class='gd-pair'><span class='gd-jp'>案内します</span> → <span class='gd-jp'>ご案内します</span></span><br><span class='gd-pair'><span class='gd-jp'>連絡します</span> → <span class='gd-jp'>ご連絡します</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>荷物、お持ちします。</span>(Barangnya, biar saya bawakan.)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅までお送りします。</span>(Saya antar Anda sampai stasiun.)</div><div class='gd-ex-line'>・<span class='gd-jp'>あとでご連絡します。</span>(Nanti saya hubungi Anda lagi.)</div><div class='gd-sec'>Cara ini hanya bisa dipakai untuk tindakan yang <b>dilakukan untuk lawan bicara, atau yang berkaitan dengannya</b>. Makan sendiri atau tidur sendiri tidak ada hubungannya dengan lawan bicara, jadi tidak bisa memakai pola ini.</div><div class='gd-h'>Cara 2: ganti langsung dengan kata kerja khusus</div><div class='gd-sec'>Beberapa kata kerja yang sering dipakai punya versi merendah sendiri. <b>Ganti seluruhnya</b>, tidak perlu pakai お～します. Di level N4, hafalkan dulu yang ini:<br><span class='gd-pair'><span class='gd-jp'>行く・来る</span> → <span class='gd-jp'>参ります</span></span><br><span class='gd-pair'><span class='gd-jp'>いる</span> → <span class='gd-jp'>おります</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>申します</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>いたします</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる・飲む・もらう</span> → <span class='gd-jp'>いただきます</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>拝見します</span></span><br><span class='gd-pair'>bertanya, berkunjung ke tempat lawan bicara → <span class='gd-jp'>伺います</span></span><br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>存じております</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>お目にかかります</span></span><br>「いただきます」yang diucapkan sebelum makan sebenarnya adalah いただく yang merendah ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>はじめまして、林と申します。</span>(Senang berkenalan, nama saya Hayashi.)</div><div class='gd-ex-line'>・<span class='gd-jp'>資料、拝見しました。</span>(Dokumennya sudah saya lihat.)</div><div class='gd-ex-line'>・<span class='gd-jp'>では、お先に失礼いたします。</span>(Kalau begitu, saya mohon pamit duluan.)</div><div class='gd-sec'>Saat membicarakan tindakan <b>anggota keluargamu sendiri</b> kepada orang luar, kenjōgo juga dipakai, karena keluarga dianggap bagian dari “pihak kita”.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は今、出かけております。</span>(Ayah saya sedang keluar sekarang.)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kenjōgo hanya boleh dipakai untuk <b>diri sendiri (dan pihak sendiri)</b>. Mempersilakan guru makan dengan <span class='gd-jp'>いただいてください</span> itu salah, yang benar <span class='gd-jp'>召し上がってください</span>. Menanyakan apakah guru ikut pergi juga tidak bisa <span class='gd-jp'>先生も参りますか</span>, yang benar <span class='gd-jp'>先生もいらっしゃいますか</span>.<br>・Kalau kata kerjanya punya versi khusus, pakai versi khusus itu: tidak ada お見します, yang benar <span class='gd-jp'>拝見します</span>; tidak ada お行きします, yang benar <span class='gd-jp'>参ります</span> atau <span class='gd-jp'>伺います</span>.<br>・<span class='gd-jp'>お待ちします</span> artinya “saya menunggu Anda”, sedangkan <span class='gd-jp'>お待ちください</span> artinya “silakan Anda menunggu”. Pelakunya berbeda. Kalau pegawai toko bilang <span class='gd-jp'>少々お待ちください</span>, kamu yang diminta menunggu. Kalau bilang <span class='gd-jp'>お待ちしております</span>, mereka yang menunggu kamu.<br>・<span class='gd-jp'>参ります</span> hanya membuat “pergi, datang” terdengar sopan, sedangkan <span class='gd-jp'>伺います</span> artinya “pergi ke tempat lawan bicara”. <span class='gd-jp'>来週、大阪へ参ります。</span>(Minggu depan saya akan pergi ke Osaka.) / <span class='gd-jp'>明日、先生のお宅に伺います。</span>(Besok saya akan berkunjung ke rumah guru.)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Yang paling gampang tertukar adalah <b>sonkeigo</b>. Untuk hal yang sama, kalau pelakunya lawan bicara pakai sonkeigo (mengangkat lawan bicara), kalau pelakunya diri sendiri pakai kenjōgo (merendahkan diri sendiri).</div><div class='gd-ex-line'>・<span class='gd-jp'>先生も召し上がりますか。</span>(Apakah Bapak/Ibu Guru juga mau makan? Lawan bicara yang makan, sonkeigo)</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、私もいただきます。</span>(Ya, saya juga makan. Saya yang makan, kenjōgo)</div><div class='gd-ex-line'>・<span class='gd-jp'>先生、傘をお持ちになりましたか。</span>(Bu/Pak Guru, apakah Anda membawa payung? Lawan bicara yang membawa)</div><div class='gd-ex-line'>・<span class='gd-jp'>傘、お持ちします。</span>(Payungnya, biar saya bawakan. Saya yang membawa)</div><div class='gd-warn'>Trik menentukan: tanyakan dulu “siapa yang melakukan tindakan ini?” Lawan bicara → sonkeigo (お～になる、いらっしゃる、召し上がる). Diri sendiri → kenjōgo (お～します、参ります、いただきます).</div><div class='gd-h'>Setelah ini belajar apa</div><div class='gd-sec'>Lanjut ke「〜させていただきます」, ungkapan yang sangat merendah untuk mengatakan “saya akan melakukan ～” (secara harfiah “atas kebaikan Anda yang mengizinkan saya melakukan ～”), misalnya <span class='gd-jp'>本日は休ませていただきます。</span>(Hari ini mohon izinkan saya beristirahat.) Kalau kamu kerja paruh waktu atau bekerja di kantor, ungkapan ini terdengar setiap hari.</div>","n4-56":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「なら」kira-kira artinya <b>「kalau (soal) ～」</b>. Temanmu bilang \"Aku mau berendam di onsen\", lalu kamu menyambung \"Kalau onsen, Hakone bagus lho.\" Tangkap dulu hal yang diangkat lawan bicara, baru beri saran atau pendapatmu. Itulah pemakaian なら yang paling umum.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyambung sambil memberi saran</span>Lawan bicara menyebut sesuatu, lalu kamu memberi pendapat soal hal itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：週末、温泉に行きたいな。</span>（Pengin banget pergi ke onsen akhir pekan ini）</div><div class='gd-ex-line'>・<span class='gd-jp'>B：温泉なら、箱根がいいよ。</span>（Kalau onsen, Hakone bagus lho）</div><div class='gd-sec'><span class='gd-tag'>Berandai dulu, lalu bilang rencanamu</span>Maksudnya \"Kalau begitu, aku akan ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたが行くなら、私も行きます。</span>（Kalau kamu pergi, aku juga ikut）</div><div class='gd-ex-line'>・<span class='gd-jp'>家賃が予算内なら、契約したいです。</span>（Kalau sewanya masuk anggaran, aku mau tanda tangan kontrak）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: sambung langsung dengan bentuk biasa (bentuk tanpa ます).<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くなら</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないなら</span></span><br><b>Kata sifat い</b>: sambung langsung. <span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いなら</span></span><br><b>Kata sifat な</b>: buang 「だ」 lalu sambung. <span class='gd-pair'><span class='gd-jp'>静かだ</span> → <span class='gd-jp'>静かなら</span></span><br><b>Kata benda</b>: sambung langsung. <span class='gd-pair'><span class='gd-jp'>日本語</span> → <span class='gd-jp'>日本語なら</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Kata benda＋なら</span>Artinya \"kalau bicara soal ～\", mempersempit topik ke satu hal itu saja.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーなら、駅前の店がおいしいですよ。</span>（Kalau soal kopi, toko di depan stasiun itu enak lho）</div><div class='gd-sec'><span class='gd-tag'>それなら</span>Ditaruh di awal kalimat, artinya \"kalau begitu\". Dalam percakapan, orang sering cukup bilang 「なら」.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：明日は忙しいです。</span>（Besok aku sibuk）</div><div class='gd-ex-line'>・<span class='gd-jp'>B：それなら、あさってにしましょう。</span>（Kalau begitu, kita ganti lusa saja）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata benda dan kata sifat な <b>jangan ditambah だ</b>: yang benar <span class='gd-jp'>学生なら</span>, bukan 学生だなら.<br>・Hal yang ada setelah なら <b>boleh dikerjakan lebih dulu daripada hal sebelumnya</b>: <span class='gd-jp'>京都へ行くなら、ホテルを早く予約したほうがいいですよ。</span>（Kalau mau ke Kyoto, sebaiknya pesan hotel lebih awal）Memesan hotel itu dilakukan sebelum berangkat. Ini kebalikan dari たら.<br>・Setelah なら biasanya ada saran, permintaan, rencanamu sendiri, atau penilaian. Untuk hal yang pasti terjadi, seperti \"kalau musim semi tiba, bunga mekar\", jangan pakai なら, tapi と: <span class='gd-jp'>春になると、桜が咲きます。</span>（Begitu musim semi tiba, sakura mekar）</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>なら dan たら sama-sama bisa diartikan \"kalau ～\", jadi paling gampang tertukar. Bedanya ada di <b>kapan hal setelahnya dilakukan</b>. Sama-sama soal pergi ke Jepang:<br><b>なら</b> = dilakukan sebelum pergi:</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行くなら、日本語を勉強しておいたほうがいいよ。</span>（Kalau mau ke Jepang, sebaiknya belajar bahasa Jepang dulu）</div><div class='gd-sec'><b>たら</b> = dilakukan setelah sampai:</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行ったら、ラーメンを食べたい。</span>（Kalau sudah sampai di Jepang, aku mau makan ramen）</div><div class='gd-sec'>Kalau kalimat pertama diganti jadi 「行ったら」, artinya berubah menjadi \"baru mulai belajar bahasa Jepang setelah sampai di Jepang\", beda dengan maksudmu. Sebaliknya, \"telepon aku setelah sampai di stasiun\" pasti baru dilakukan setelah sampai, jadi pakai たら: <span class='gd-jp'>駅に着いたら、電話してください。</span>（Kalau sudah sampai stasiun, tolong telepon aku）</div><div class='gd-warn'>Trik menentukan: \"belum dilakukan, kasih saran dulu\" pakai なら; \"setelah selesai, setelah sampai baru terjadi\" pakai たら. Kalau lawan bicara baru saja menyebut sesuatu dan kamu menyambung dengan pendapat, hampir pasti なら.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Ada empat \"kalau\" dalam bahasa Jepang: と、ば、たら、なら. Setelah selesai belajar なら, coba bandingkan dengan <span class='gd-jp'>〜ば</span> (n4-54) dan <span class='gd-jp'>〜と</span> (n4-57) untuk melihat kapan masing-masing dipakai.</div>","n4-59":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Bentuk pasif (受身形) mirip dengan <b>\"di-\"</b> dalam bahasa Indonesia: <span class='gd-jp'>先生に褒められた</span> artinya \"dipuji oleh guru\". Tapi pasif bahasa Jepang dipakai lebih luas daripada \"di-\", dan sering membawa nuansa <b>\"aku jadi sial dan repot\"</b>, mirip kita bilang \"kena marah\" atau \"kehujanan\".</div><div class='gd-h'>Cara mengubahnya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: ubah bunyi terakhir menjadi bunyi baris 「あ」 yang sama, lalu tambah 「れる」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti か → <span class='gd-jp'>書かれる</span></span><br><span class='gd-pair'><span class='gd-jp'>踏む</span> → <span class='gd-jp'>踏まれる</span></span><span class='gd-pair'><span class='gd-jp'>叱る</span> → <span class='gd-jp'>叱られる</span></span><br>Yang berakhiran 「う」 perlu hati-hati: う tidak diganti あ, tapi <b>わ</b>:<br><span class='gd-pair'><span class='gd-jp'>言う</span> → う diganti わ → <span class='gd-jp'>言われる</span></span><span class='gd-pair'><span class='gd-jp'>誘う</span> → <span class='gd-jp'>誘われる</span></span><br>Dari bentuk ます juga bisa: 「き」 pada <span class='gd-jp'>書きます</span> diganti 「か」, lalu tambah 「れます」→<span class='gd-jp'>書かれます</span>.</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang 「る」 di akhir, lalu tambah 「られる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span></div><div class='gd-sec'><b>Golongan 3 (cuma dua, hafalkan saja)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>Setelah jadi 「〜れる／〜られる」, anggap saja sebagai kata kerja golongan 2 untuk perubahan selanjutnya: <span class='gd-jp'>叱られます</span>、<span class='gd-jp'>叱られた</span>、<span class='gd-jp'>叱られて</span>.</div><div class='gd-h'>Tiga jenis pasif yang paling sering muncul</div><div class='gd-sec'>Apa pun jenisnya, <b>pelaku tindakan selalu diikuti 「に」</b>.</div><div class='gd-sec'><span class='gd-tag'>Aku dikenai suatu tindakan</span>（私は）orang に＋pasif. Paling mirip dengan \"di-\" dalam bahasa Indonesia, bisa untuk hal baik maupun buruk.<br><span class='gd-jp'>先生が私を褒めた。</span>（Guru memuji aku）→ jadi pasif:</div><div class='gd-ex-line'>・<span class='gd-jp'>私は先生に褒められた。</span>（Aku dipuji oleh guru）</div><div class='gd-ex-line'>・<span class='gd-jp'>母に叱られました。</span>（Aku dimarahi ibu）</div><div class='gd-sec'><span class='gd-tag'>Barang milikku dikenai tindakan</span>（私は）orang に＋benda を＋pasif. Bahasa Jepang suka menjadikan \"pihak yang dirugikan\" sebagai tokoh utama, sedangkan bendanya memakai 「を」.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で足を踏まれた。</span>（Kakiku diinjak di kereta）</div><div class='gd-ex-line'>・<span class='gd-jp'>弟にケーキを食べられた。</span>（Kuenya dimakan adikku）</div><div class='gd-sec'><span class='gd-tag'>Jadi repot atau dirugikan</span>Tindakan orang lain sebenarnya tak ada hubungannya denganmu, tapi kamu jadi kena imbasnya. Bahkan tindakan seperti \"hujan\" atau \"menangis\" bisa dibuat pasif. Dalam bahasa Indonesia biasanya jadi \"kehujanan\" atau \"kena tangis\", bukan \"di-\".</div><div class='gd-ex-line'>・<span class='gd-jp'>雨に降られて、びしょびしょになった。</span>（Kehujanan, jadi basah kuyup）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に子供に泣かれて、寝られなかった。</span>（Tengah malam anakku menangis terus, jadi aku tidak bisa tidur）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Pasif dari <span class='gd-jp'>言う</span> adalah <span class='gd-jp'>言われる</span>, bukan 「言あれる」 dan bukan 「言られる」. <span class='gd-jp'>買う</span>、<span class='gd-jp'>使う</span> juga sama-sama pakai わ.<br>・Pelaku tindakan pakai 「に」: yang benar <span class='gd-jp'>先生に褒められた</span>, bukan 「先生が褒められた」, karena itu berarti \"guru yang dipuji\".<br>・Dalam bahasa Indonesia kita bilang \"kakiku diinjak\", tapi dalam bahasa Jepang jangan diterjemahkan mentah-mentah jadi 「私の足が踏まれた」. Yang natural adalah <span class='gd-jp'>足を踏まれた</span>.<br>・Pasif \"kena\" dalam bahasa Indonesia sering bernuansa buruk, tapi pasif bahasa Jepang juga bisa untuk hal baik: <span class='gd-jp'>褒められた</span> (dipuji), <span class='gd-jp'>誘われた</span> (diajak) sangat umum.<br>・Kalau ketemu kalimat pasif, tanya dulu: \"Apakah tokoh utamanya pihak yang terkena dampak, bahkan dirugikan?\" Dengan begitu nuansanya akan terasa.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>Bentuk pasif vs bentuk potensial</b>: pada kata kerja golongan 2 dan 来る, kedua bentuknya persis sama.<br><span class='gd-jp'>犬にパンを食べられた。</span>（Rotinya dimakan anjing: pasif）<br><span class='gd-jp'>このパンはまだ食べられる。</span>（Roti ini masih bisa dimakan: potensial）<br>Kalau di depannya ada 「orang に」 dan kalimatnya membahas siapa yang diperlakukan bagaimana, itu pasif. Kalau membahas \"bisa atau tidak\", itu bentuk potensial.</div><div class='gd-sec'><b>〜られる vs 〜てもらう</b>: sama-sama soal temanmu yang datang.<br><span class='gd-jp'>友達に来られて困った。</span>（Temanku datang dan aku jadi repot）<br><span class='gd-jp'>友達に来てもらって助かった。</span>（Temanku datang membantu, aku sangat tertolong）<br>Pasif sering bernuansa \"diganggu\"; てもらう artinya \"dibantu oleh orang itu\" dan membawa rasa terima kasih.</div><div class='gd-warn'>Trik menentukan: kalau yang kamu rasakan \"kena, sial\", pakai 〜れる／〜られる; kalau yang kamu rasakan \"dibantu orang, senangnya\", pakai 〜てもらう.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Bentuk kausatif (menyuruh orang lain melakukan): <span class='gd-jp'>書かせる</span>; lalu satu tingkat di atasnya ada kausatif-pasif (dipaksa melakukan): <span class='gd-jp'>母に野菜を食べさせられた。</span>（Dipaksa ibu makan sayur）. Selain itu, 〜れる／〜られる yang sama juga bisa dipakai untuk menghormati orang yang lebih tua, misalnya <span class='gd-jp'>先生が書かれた本</span>（buku yang ditulis oleh guru）. Kamu akan bertemu lagi dengan pemakaian ini saat belajar bentuk hormat.</div>","n4-10":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜たことがあります」 sama dengan <b>“pernah ～”</b> dalam bahasa Indonesia. Pola ini dipakai untuk bilang kamu <b>pernah atau belum pernah punya pengalaman itu</b> seumur hidupmu. “Aku pernah ke Jepang” jadi <span class='gd-jp'>日本へ行ったことがあります。</span>, dan “Aku belum pernah makan daun ketumbar” jadi <span class='gd-jp'>パクチーを食べたことがありません。</span></div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah verba ke <b>bentuk た</b> dulu (bentuk lampau biasa, yang artinya “sudah makan” atau “sudah pergi”), lalu tambahkan <span class='gd-jp'>ことがあります</span>.<br>Cara membentuk た sama dengan bentuk て, hanya て diganti た dan で diganti だ:<br><b>Golongan 1 (verba godan)</b>：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>乗る</span> → <span class='gd-jp'>乗った</span></span><br><b>Golongan 2 (verba ichidan)</b>：buang 「る」, lalu tambahkan た。<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span><br><b>Golongan 3 (hanya dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span><br>Setelah itu sambungkan semuanya：<span class='gd-pair'><span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたことがあります</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Pernah</span>Untuk menceritakan pengalamanmu sendiri. Kamu bisa menambahkan jumlah kali di depannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>着物を着たことがあります。</span>（Aku pernah memakai kimono）</div><div class='gd-ex-line'>・<span class='gd-jp'>大阪には二回行ったことがあります。</span>（Aku pernah ke Osaka dua kali）</div><div class='gd-sec'><span class='gd-tag'>Belum pernah</span>Ganti あります menjadi <b>ありません</b>. Kalau ditambah 「一度も」, artinya “sekali pun tidak pernah”.</div><div class='gd-ex-line'>・<span class='gd-jp'>一度も雪を見たことがありません。</span>（Aku belum pernah melihat salju sekali pun）</div><div class='gd-sec'><span class='gd-tag'>Bertanya</span>Tambahkan か di akhir kalimat. Saat menjawab, kamu tidak perlu mengulang seluruh kalimat. Cukup あります／ありません.</div><div class='gd-ex-line'>・<span class='gd-jp'>馬に乗ったことがありますか。</span>（Kamu pernah naik kuda?）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、あります。</span>／<span class='gd-jp'>いいえ、ありません。</span>（Pernah／Belum pernah）</div><div class='gd-sec'><span class='gd-tag'>Versi teman</span>Dengan teman, pakai <span class='gd-jp'>ことがある</span>／<span class='gd-jp'>ことがない</span>. Dalam percakapan, が sering dihilangkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山、登ったことある？</span>（Kamu pernah mendaki Gunung Fuji?）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Pola ini bicara soal “pernah atau tidaknya kamu punya pengalaman itu dalam hidup”, jadi <b>untuk hal yang baru saja terjadi seperti tadi atau kemarin, jangan dipakai</b>: <span class='gd-jp'>さっき食べたことがある</span> itu salah, langsung saja bilang <span class='gd-jp'>さっき食べた</span>. Untuk rentang waktu yang jauh dan luas seperti “waktu kecil”, boleh: <span class='gd-jp'>子どものころ、日本に住んだことがあります。</span>（Waktu kecil aku pernah tinggal di Jepang）<br>・<b>Jangan dipakai untuk hal yang pasti dialami semua orang</b>: kalau “Aku pernah makan nasi” kamu ucapkan sebagai <span class='gd-jp'>ご飯を食べたことがあります</span>, orang Jepang akan merasa aneh, seolah makan nasi itu pengalaman yang langka.<br>・“Belum pernah melakukan” adalah <span class='gd-jp'>食べたことがありません</span>, bukan <span class='gd-jp'>食べなかったことがあります</span>. Yang terakhir artinya “pernah mengalami satu kali tidak makan”.<br>・Bagian depannya harus <b>bentuk た</b>. Kalau diganti bentuk kamus, artinya berubah total, lihat di bawah.<br>・Huruf 来 di <span class='gd-jp'>来たことがあります</span> dibaca <b>き</b>, bukan く dan bukan こ.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>Bentuk た＋ことがあります</b>＝pernah ～ (pengalaman)<br><span class='gd-jp'>納豆を食べたことがあります。</span>（Aku pernah makan natto）<br><b>Bentuk kamus＋ことがあります</b>＝kadang-kadang ～ (sesekali terjadi)<br><span class='gd-jp'>納豆を食べることがあります。</span>（Aku kadang-kadang makan natto）</div><div class='gd-sec'>Satu lagi, bedakan juga “pernah” dan “sudah”. Kalau maksudmu “sudah selesai melakukan”, bahasa Jepang <b>tidak memakai</b> ことがある:<br><span class='gd-jp'>もう食べましたか。</span>（Kamu sudah makan? = sudah makan belum）<br><span class='gd-jp'>食べたことがありますか。</span>（Kamu pernah makan? = punya pengalaman itu atau tidak）</div><div class='gd-warn'>Trik cepat menentukan: kalau bisa diubah jadi “pernah ～ atau belum?”, pakai たことがある. Kalau artinya “sudah ～ belum?”, pakai <span class='gd-jp'>もう〜ました</span>. Kalau di depannya bentuk kamus, artinya “kadang-kadang”.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Pola ini bisa dipadukan dengan 「〜てみたい」 (ingin mencoba), sangat berguna untuk perkenalan diri dan ngobrol:<br><span class='gd-jp'>温泉に入ったことがないので、一度入ってみたいです。</span>（Aku belum pernah berendam di onsen, jadi ingin mencoba sekali）</div>","n4-45":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜んです」 mirip dengan <b>“soalnya ～”, “sebenarnya begini lho ～”, “memangnya ada apa?”</b> dalam bahasa Indonesia, dengan nuansa seperti “sih”, “kok”, dan “lho”. Arti kalimatnya tidak berubah, hanya ada tambahan nuansa: <b>aku sedang menjelaskan latar belakang</b>, atau <b>aku melihat suatu keadaan dan ingin tahu apa yang sebenarnya terjadi</b>. Orang Jepang sangat sering memakainya. Dalam percakapan hampir selalu 「んです」, sedangkan 「のです」 adalah versi untuk tulisan dan pidato.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menjelaskan alasan</span>Saat orang menanyakan alasanmu, atau saat kamu merasa perlu menjelaskan sebabnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして昨日休んだんですか。</span>（Kenapa kemarin kamu izin tidak masuk?）</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったんです。</span>（Soalnya aku demam）</div><div class='gd-sec'><span class='gd-tag'>Melihat keadaan lalu bertanya</span>Kamu melihat suatu situasi di depan mata dan ingin tahu apa yang terjadi di baliknya.</div><div class='gd-ex-line'>・<span class='gd-jp'>どうしたんですか。</span>（Ada apa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降っているんですか。</span>（Di luar hujan, ya? Misalnya saat kamu melihat lawan bicara masuk membawa payung yang basah）</div><div class='gd-sec'><span class='gd-tag'>Membuka dengan latar</span>Pakai 「〜んですが」「〜んですけど」 untuk menyampaikan situasinya dulu, baru meminta tolong atau bertanya. Ini pembukaan yang sangat natural.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅に行きたいんですが…。</span>（Permisi, saya mau ke stasiun…）</div><div class='gd-sec'><span class='gd-tag'>Menyampaikan kabar dan perasaan</span>Memberi tahu lawan bicara suatu hal secara langsung, atau menekankan perasaanmu.</div><div class='gd-ex-line'>・<span class='gd-jp'>実は来月結婚するんです。</span>（Sebenarnya bulan depan aku akan menikah）</div><div class='gd-ex-line'>・<span class='gd-jp'>本当に困っているんです。</span>（Aku benar-benar kesulitan）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Verba dan adjektiva-い</b>：bentuk biasa (yaitu bentuk tanpa ます dan です) langsung ditambah んです.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くんです</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないんです</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったんです</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いんです</span></span></div><div class='gd-sec'><b>Adjektiva-な dan nomina</b>：dalam bentuk positif masa kini, di tengahnya harus ditambah <b>な</b>.<br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きなんです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なんです</span></span><br>Untuk lampau atau negatif, cukup sambung dari bentuk biasanya, tanpa な：<span class='gd-pair'><span class='gd-jp'>学生だった</span> → <span class='gd-jp'>学生だったんです</span></span><span class='gd-pair'><span class='gd-jp'>好きじゃない</span> → <span class='gd-jp'>好きじゃないんです</span></span></div><div class='gd-sec'>Saat bicara dengan teman, untuk menjelaskan pakai 「〜んだ」 atau 「〜の」, dan untuk bertanya pakai 「〜の？」：<span class='gd-jp'>どうしたの？</span>（Ada apa?）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Lupa menambah な pada adjektiva-な dan nomina: bukan 学生んです, bukan juga 学生だんです, tetapi <span class='gd-jp'>学生なんです</span>.<br>・Tidak bisa dipasang setelah ます atau です: bukan 行きますんです atau 高いですんです, tetapi <span class='gd-jp'>行くんです</span> dan <span class='gd-jp'>高いんです</span>.<br>・Jangan ditambahkan di setiap kalimat. Untuk menyatakan fakta biasa, cukup pakai ます. Kalau tiap kalimat memakai んです, kamu akan terdengar terus-menerus menjelaskan dan mencari alasan.<br>・Saat menanyakan perbuatan orang lain dengan 「〜んですか」, kalau nada dan situasinya kurang pas, bisa terdengar seperti menyelidiki atau menginterogasi. Misalnya <span class='gd-jp'>何をしているんですか</span> kalau nadanya keras jadi “Kamu ngapain sih!”, dan <span class='gd-jp'>どうして遅れたんですか</span> juga bisa terdengar seperti menyalahkan. Saat bertanya pada orang yang lebih tua, lembutkan nadamu, misalnya dengan mengawali <span class='gd-jp'>あのう</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Situasinya sama: rencana rekan kerjamu besok.<br><b>〜ますか</b>＝bertanya biasa, tanpa petunjuk apa pun:<br><span class='gd-jp'>明日、どこかへ行きますか。</span>（Besok kamu ada rencana pergi ke suatu tempat?）<br><b>〜んですか</b>＝kamu melihat rekanmu menyeret koper dan ingin tahu ada apa:<br><span class='gd-jp'>どこかへ行くんですか。</span>（Kamu mau pergi ke suatu tempat, ya?）<br>Jawabannya juga sama, kalau mau menjelaskan alasan, pakai んです：<span class='gd-jp'>大阪に出張なんです。</span>（Aku dinas ke Osaka）</div><div class='gd-warn'>Trik cepat menentukan: kalau kamu melihat sesuatu dan ingin tahu alasan di baliknya, pakai んですか. Kalau cuma bertanya hal biasa, pakai ますか.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜んですが」 yang diikuti kalimat permintaan menjadi cara meminta tolong yang sangat sopan: <span class='gd-jp'>日本語がよくわからないんですが、ゆっくり話していただけませんか。</span>（Bahasa Jepangku belum begitu lancar, bisakah Anda bicara lebih pelan?）</div>","n4-47":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Keduanya sama-sama bicara soal 「keputusan」, bedanya ada pada <b>siapa yang memutuskan</b>.<br><b>ことにする</b>＝\"Aku memutuskan untuk ~\", kamu sendiri yang menentukan.<br><b>ことになる</b>＝\"Jadinya akan ~\", bisa karena diatur oleh perusahaan atau sekolah, bisa juga karena keadaan berkembang begitu saja. Mirip beda antara \"Aku memutuskan pindah rumah\" dan \"Aku dipindahtugaskan ke Surabaya\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Hal yang akan dilakukan: bentuk kamus＋ことにする／ことになる<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くことにする</span></span><br>Hal yang tidak akan dilakukan: bentuk ない＋ことにする／ことになる<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないことにする</span></span><br>Keputusan biasanya sudah dibuat, jadi yang paling sering dipakai adalah bentuk lampau: <b>ことにした</b>, <b>ことになった</b>.</div><div class='gd-h'>Empat bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ことにした</span>Keputusan yang baru saja kamu buat sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本に留学することにしました。</span>（Aku memutuskan untuk kuliah di Jepang tahun depan）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はどこにも行かないことにした。</span>（Aku memutuskan hari ini tidak pergi ke mana-mana）</div><div class='gd-sec'><span class='gd-tag'>ことになった</span>Diputuskan orang lain, atau keadaan memang jadi begitu dengan sendirinya.</div><div class='gd-ex-line'>・<span class='gd-jp'>来月から大阪に転勤することになりました。</span>（Mulai bulan depan aku dipindahtugaskan ke Osaka）</div><div class='gd-ex-line'>・<span class='gd-jp'>6月に結婚することになりました。</span>（Aku akan menikah bulan Juni）</div><div class='gd-sec'>Menikah kan keputusan sendiri, kenapa pakai なる? Karena なる terdengar seperti \"keadaan sampai ke titik ini\", jadi lebih <b>rendah hati dan sopan</b>. Orang Jepang sering memakainya saat melapor ke rekan kerja atau atasan.</div><div class='gd-sec'><span class='gd-tag'>ことにしている</span>Aturan yang kamu buat untuk diri sendiri dan terus kamu jalankan.</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前はスマホを見ないことにしている。</span>（Aku punya aturan untuk tidak melihat ponsel sebelum tidur）</div><div class='gd-sec'><span class='gd-tag'>ことになっている</span>Aturan atau kebiasaan sebuah kelompok, bukan kamu yang membuatnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>この寮では、10時までに帰ることになっている。</span>（Di asrama ini, kita harus sudah pulang sebelum jam 10）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata benda, langsung pakai にする tanpa こと: saat memesan, bilang <span class='gd-jp'>コーヒーにします</span> (Aku pilih kopi). Untuk kata kerja, tambahkan こと dulu baru にする: <span class='gd-jp'>コーヒーをやめることにします</span> (Aku memutuskan berhenti minum kopi).<br>・Partikelnya <b>に</b>, bukan を: <span class='gd-jp'>行くことにした</span>, bukan 「行くことをした」.<br>・Saat memberi tahu orang lain bahwa kamu akan berhenti kerja, <span class='gd-jp'>辞めることにしました</span> terdengar seperti \"aku sendiri yang memutuskan\", sikapnya jelas. <span class='gd-jp'>辞めることになりました</span> lebih halus dan tidak sefrontal itu.<br>・ことにしている itu \"aturan buatan sendiri\", sedangkan ことになっている itu \"memang aturannya begitu\". Jangan bilang aturan asrama dengan ことにしている.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bicara soal \"jalan kaki setiap hari\":<br><b>ことにする</b>＝saat kamu membuat keputusan: <span class='gd-jp'>毎日歩くことにした。</span>（Aku memutuskan jalan kaki setiap hari）<br><b>ようにする</b>＝berusaha sebisa mungkin dan memang sedang diupayakan: <span class='gd-jp'>毎日歩くようにしている。</span>（Aku berusaha jalan kaki setiap hari）<br><b>つもり</b>＝rencana di dalam hati, belum benar-benar diputuskan: <span class='gd-jp'>毎日歩くつもりだ。</span>（Aku berencana jalan kaki setiap hari）</div><div class='gd-sec'>Selain itu, <b>ことになる</b> dan <b>ようになる</b> juga sering tertukar:<br><span class='gd-jp'>日本で働くことになった。</span>（Aku akan bekerja di Jepang: diatur, urusannya sudah pasti）<br><span class='gd-jp'>日本語が話せるようになった。</span>（Sekarang aku bisa berbahasa Jepang: kemampuan atau kebiasaan berubah pelan-pelan）</div><div class='gd-warn'>Tips cepat: \"aku memutuskan\" pakai ことにする, \"jadinya begitu\" pakai ことになる, \"berusaha\" pakai ようにする, \"berencana\" pakai つもり.</div>","n4-48":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜まま」artinya <b>\"dibiarkan begitu saja\" atau \"tetap dalam keadaan ~\"</b>: suatu keadaan <b>tidak berubah</b>, lalu kamu langsung melakukan hal berikutnya. Misalnya keluar rumah dengan AC masih menyala, atau masuk kamar dengan sepatu masih terpakai. Biasanya ada kesan \"seharusnya diubah dulu, tapi tidak dilakukan\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja bentuk た＋まま</b>: yang paling sering dipakai. Kamu melakukan suatu tindakan, meninggalkan suatu keadaan, lalu keadaan itu tidak berubah.<br><span class='gd-pair'><span class='gd-jp'>開けた</span> → <span class='gd-jp'>開けたまま</span>（dibiarkan terbuka）</span><br><span class='gd-pair'><span class='gd-jp'>つけた</span> → <span class='gd-jp'>つけたまま</span>（lampu atau TV dibiarkan menyala）</span><br><b>Kata kerja bentuk ない＋まま</b>: keadaan terus \"tidak melakukan\" sesuatu.<br><span class='gd-pair'><span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わないまま</span>（terus tidak mengatakannya）</span><br><b>Kata benda＋の＋まま</b>: <span class='gd-pair'><span class='gd-jp'>昔</span> → <span class='gd-jp'>昔のまま</span>（sama seperti dulu）</span><br><b>この・その・あの＋まま</b>: <span class='gd-jp'>このまま</span> (begini saja), <span class='gd-jp'>そのまま</span> (begitu saja)<br>Kata sifat juga bisa: kata sifat い langsung disambung, seperti <span class='gd-jp'>若いまま</span> (tetap muda); kata sifat な perlu tambah な, seperti <span class='gd-jp'>きれいなまま</span> (tetap bersih).</div><div class='gd-h'>Pola yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Tanpa sengaja jadi begitu</span>Dipakai bersama 「〜てしまう」, menunjukkan penyesalan atau \"aduh, gawat\".</div><div class='gd-ex-line'>・<span class='gd-jp'>眼鏡をかけたままシャワーを浴びてしまった。</span>（Aku mandi dengan kacamata masih terpakai）</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビをつけたまま寝てしまった。</span>（Aku ketiduran dengan TV masih menyala）</div><div class='gd-sec'><span class='gd-tag'>Aturan, pengingat</span>Memberi tahu orang lain untuk tidak melakukan sesuatu sambil membiarkan keadaan tertentu.</div><div class='gd-ex-line'>・<span class='gd-jp'>靴を履いたまま部屋に入らないでください。</span>（Tolong jangan masuk kamar dengan sepatu masih terpakai）</div><div class='gd-sec'><span class='gd-tag'>Terus tidak melakukan</span>Pakai bentuk ない untuk mengatakan sesuatu sama sekali tidak dilakukan dari awal sampai akhir.</div><div class='gd-ex-line'>・<span class='gd-jp'>何も言わないまま帰ってしまった。</span>（Dia pulang tanpa mengatakan apa-apa）</div><div class='gd-sec'><span class='gd-tag'>このまま・そのまま</span>Sering sekali terdengar sehari-hari, apalagi dari pelayan toko dan layanan pelanggan.</div><div class='gd-ex-line'>・<span class='gd-jp'>そのままお待ちください。</span>（Mohon tunggu sebentar seperti itu）</div><div class='gd-ex-line'>・<span class='gd-jp'>袋はいりません。このままで大丈夫です。</span>（Tidak usah pakai kantong. Begini saja sudah cukup）</div><div class='gd-sec'><span class='gd-tag'>Di akhir kalimat</span>Pakai 「〜のままだ／のままです」untuk mengatakan \"masih sama seperti dulu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は昔のままだ。</span>（Kota ini masih persis seperti dulu）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・た di sini <b>bukan \"lampau\"</b>, tapi artinya \"sudah menjadi keadaan itu\". Untuk masa kini atau masa depan, tetap pakai bentuk た: <span class='gd-jp'>靴を履いたまま入ってもいいですよ。</span>（Boleh masuk dengan sepatu masih terpakai）<br>・Untuk \"mempertahankan suatu keadaan\", jangan pakai bentuk kamus: ×<span class='gd-jp'>眼鏡をかけるまま</span>, yang benar ○<span class='gd-jp'>眼鏡をかけたまま</span>.<br>・Setelah kata benda wajib ada の: ×<span class='gd-jp'>昔まま</span>, yang benar ○<span class='gd-jp'>昔のまま</span>.<br>・Tidak semua \"sambil\" atau \"dengan ... masih ...\" dalam bahasa Indonesia berarti まま. Kalau dua hal sekadar dilakukan bersamaan (makan sambil menonton), bahasa Jepangnya pakai ながら, lihat di bawah.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>〜ながら</b>＝dua tindakan <b>dilakukan bersamaan</b>, dan keduanya kamu lakukan dengan sadar:<br><span class='gd-jp'>テレビを見ながら勉強した。</span>（Aku belajar sambil menonton TV）<br><b>〜たまま</b>＝suatu keadaan <b>dibiarkan saja</b>, lalu kamu melakukan hal berikutnya:<br><span class='gd-jp'>テレビをつけたまま勉強した。</span>（Aku belajar dengan TV dibiarkan menyala）<br>Di kalimat pertama kamu benar-benar menonton TV; di kalimat kedua TV hanya menyala, dan mungkin kamu sama sekali tidak menontonnya.</div><div class='gd-sec'><b>〜て</b>＝\"melakukan sambil ~\" yang biasa saja, tanpa kesan \"seharusnya diubah tapi tidak\":<br><span class='gd-jp'>帽子をかぶって出かけた。</span>（Aku memakai topi lalu pergi keluar）<br><b>〜たまま</b>＝pendengar akan merasa \"seharusnya dilepas dulu, kan\":<br><span class='gd-jp'>帽子をかぶったまま教室に入った。</span>（Dia masuk kelas dengan topi masih terpakai, kesannya seharusnya dilepas dulu）</div><div class='gd-warn'>Tips cepat: dua hal dilakukan bersamaan pakai ながら; suatu keadaan dibiarkan tanpa disentuh lalu kamu melakukan hal lain pakai たまま.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Tambahkan 「にしておく」di belakangnya＝<b>sengaja membiarkannya tetap begitu</b>: <span class='gd-jp'>窓を開けたままにしておいてください。</span>（Tolong biarkan jendelanya terbuka, jangan ditutup）</div>","n4-2":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜つもりです」artinya <b>「aku berencana ～」</b>. Kamu sudah memutuskan di hati untuk melakukan sesuatu, dan saat menyampaikan rencanamu ke orang lain, pakai pola ini.<br>Misalnya temanmu bertanya kamu mau ngapain waktu liburan musim panas, lalu kamu jawab \"Aku berencana pergi ke Jepang\". Dalam bahasa Jepang jadi <span class='gd-jp'>日本へ行くつもりです</span>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Berencana melakukan</span><b>Bentuk kamus</b> kata kerja (bentuk dasar yang kamu temukan di kamus) ＋つもりです<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くつもりです</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買うつもりです</span></span><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強するつもりです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本へ留学するつもりです。</span>（Aku berencana kuliah di Jepang tahun depan）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は家でゆっくりするつもりです。</span>（Akhir pekan aku berencana santai di rumah）</div><div class='gd-sec'><span class='gd-tag'>Berencana tidak melakukan</span><b>Bentuk ない</b> kata kerja ＋つもりです<br><span class='gd-pair'><span class='gd-jp'>吸う</span> → <span class='gd-jp'>吸わない</span> → <span class='gd-jp'>吸わないつもりです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>もうタバコは吸わないつもりです。</span>（Aku berencana tidak merokok lagi）</div><div class='gd-sec'>Saat ngobrol dengan teman, ganti です dengan <b>だ</b>, atau berhenti saja sampai つもり: <span class='gd-jp'>夏休み、どうするつもり？</span>（Liburan musim panas nanti kamu mau ngapain?）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>つもりはありません</span>\"Sama sekali tidak ada niat itu\", lebih tegas daripada 「〜ないつもりです」 dan sering dipakai untuk menolak.</div><div class='gd-ex-line'>・<span class='gd-jp'>会社をやめるつもりはありません。</span>（Aku sama sekali tidak berniat berhenti dari perusahaan）</div><div class='gd-sec'><span class='gd-tag'>つもりでした</span>\"Tadinya berencana ～\", biasanya diikuti hasil bahwa rencana itu tidak terlaksana.</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝るつもりでしたが、ゲームをしてしまいました。</span>（Tadinya aku berencana tidur lebih awal, tapi malah main game）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depan つもり pakai <b>bentuk kamus</b>, bukan bentuk ます: yang benar <span class='gd-jp'>行くつもりです</span>, bukan 「行きますつもりです」.<br>・Pola ini membahas <b>rencana seseorang</b>, jadi tidak bisa dipakai untuk hal yang di luar kendali kita. Kalimat seperti \"Besok rencananya cerah\" tidak diucapkan dengan つもり dalam bahasa Jepang.<br>・Terutama dipakai untuk rencana <b>diri sendiri</b>. Untuk rencana orang lain, biasanya ditambah 「そうです」 atau 「と言っていました」: <span class='gd-jp'>田中さんは留学するつもりだそうです。</span>（Katanya Tanaka berencana kuliah di luar negeri）<br>・Kalau kamu langsung bertanya ke guru atau atasan 「<span class='gd-jp'>どうするつもりですか</span>」, kedengarannya seperti menginterogasi \"Sebenarnya kamu mau bagaimana?\". Untuk menanyakan rencana orang yang lebih tua, lebih sopan pakai <span class='gd-jp'>ご予定は？</span></div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama \"pergi ke Jepang tahun depan\", tapi cara bilangnya menunjukkan seberapa pasti rencananya:<br><b>ようと思っています</b>＝ada keinginan di hati dan sedang dipertimbangkan (N4-42)<br><span class='gd-jp'>来年、日本へ行こうと思っています。</span>（Aku sedang kepikiran pergi ke Jepang tahun depan）<br><b>つもりです</b>＝rencana yang sudah kamu putuskan sendiri, lebih mantap daripada kalimat di atas<br><span class='gd-jp'>来年、日本へ行くつもりです。</span>（Aku berencana pergi ke Jepang tahun depan）<br><b>予定です</b>＝jadwal yang sudah diatur dan punya rincian konkret, misalnya tiket sudah dipesan dan tanggal sudah ditetapkan<br><span class='gd-jp'>来年3月に日本へ行く予定です。</span>（Aku dijadwalkan pergi ke Jepang bulan Maret tahun depan）</div><div class='gd-warn'>Trik cepat: \"masih mikir-mikir\" pakai ようと思う, \"tekadku sudah bulat\" pakai つもり, \"sudah masuk kalender\" pakai 予定.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau mau bilang \"Aku memutuskan ～\", lanjut ke <span class='gd-jp'>〜ことにします</span> (N4-47): <span class='gd-jp'>来年留学することにしました。</span>（Aku memutuskan untuk kuliah di luar negeri tahun depan）</div>","n4-3":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜かもしれません」artinya <b>\"mungkin ～\" atau \"bisa jadi ～\"</b>. Kamu tidak yakin, merasa hal itu ada kemungkinan terjadi, tapi bisa juga tidak. Seperti saat kamu bilang \"Besok mungkin hujan, lho\", dalam bahasa Jepang jadi <span class='gd-jp'>明日は雨が降るかもしれません</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menebak</span>Kamu tidak yakin soal sesuatu, lalu menyampaikan situasi yang menurutmu \"mungkin saja terjadi\".</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るかもしれません。</span>（Besok mungkin hujan）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店、今日は休みかもしれない。</span>（Toko itu hari ini mungkin tutup）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はもう帰ったかもしれない。</span>（Dia mungkin sudah pulang）</div><div class='gd-sec'><span class='gd-tag'>Memberi peringatan lebih dulu</span>Sering juga dipakai untuk hal tentang diri sendiri, supaya ucapan terdengar lebih lembut dan lawan bicara punya persiapan.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、少し遅れるかもしれません。</span>（Maaf, aku mungkin akan terlambat sedikit）</div><div class='gd-ex-line'>・<span class='gd-jp'>土曜日はちょっと行けないかもしれない。</span>（Hari Sabtu aku mungkin tidak bisa datang）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: tidak perlu diubah, langsung disambung. Bentuk negatif dan lampau juga langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くかもしれない</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないかもしれない</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったかもしれない</span></span></div><div class='gd-sec'><b>Kata sifat い</b>: langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いかもしれない</span></span></div><div class='gd-sec'><b>Kata sifat な dan kata benda</b>: 「だ」 dibuang dulu baru disambung.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → buang だ → <span class='gd-jp'>静かかもしれない</span></span><br><span class='gd-pair'><span class='gd-jp'>雨だ</span> → buang だ → <span class='gd-jp'>雨かもしれない</span></span><br>Tapi 「だった」 untuk lampau tetap dipertahankan: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったかもしれない</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>かもしれません</span>Versi sopan, dipakai ke guru, rekan kerja, dan pelanggan.<br><span class='gd-tag'>かもしれない</span>Dipakai antar teman dan keluarga.<br><span class='gd-tag'>かも</span>Versi singkat yang lebih kasual, sering sekali terdengar saat anak muda dan teman mengobrol.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、財布忘れたかも。</span>（Ah, kayaknya dompetku ketinggalan）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata benda dan kata sifat な, 「だ」 tidak boleh dipertahankan: yang benar <span class='gd-jp'>雨かもしれない</span>, bukan 「雨だかもしれない」.<br>・「ない」 di akhir 「かもしれない」 <b>bukan negasi</b>. <span class='gd-jp'>来るかもしれない</span> artinya \"mungkin datang\". Untuk bilang \"mungkin tidak datang\", ubah kata kerja di depannya jadi negatif: <span class='gd-jp'>来ないかもしれない</span>.<br>・Tingkat keyakinannya rendah, kira-kira fifty-fifty atau bahkan lebih rendah. Jangan dipakai untuk hal yang sudah pasti, karena kedengarannya tidak bertanggung jawab. Misalnya, kalau sudah janjian lalu kamu bilang <span class='gd-jp'>行くかもしれません</span>, lawan bicara akan mengira kamu mungkin tidak datang.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama menebak \"Suzuki datang atau tidak\", tapi tingkat keyakinannya berbeda:<br><b>かもしれない</b>＝mungkin datang, mungkin juga tidak, tidak ada pegangan: <span class='gd-jp'>鈴木さんは来るかもしれません。</span>（Suzuki bisa jadi datang）<br><b>でしょう</b>＝kemungkinan besar datang, rasanya cukup mungkin: <span class='gd-jp'>鈴木さんは来るでしょう。</span>（Suzuki kemungkinan besar datang）<br><b>はず</b>＝seharusnya datang, ada dasarnya, misalnya kemarin dia sendiri bilang akan datang: <span class='gd-jp'>鈴木さんは来るはずです。</span>（Suzuki seharusnya datang）</div><div class='gd-warn'>Trik cepat: dari keyakinan rendah ke tinggi urutannya かもしれない ＜ でしょう ＜ はず. Kalau tidak ada pegangan dan cuma \"bisa jadi\", pakai かもしれない; kalau ada alasan dan merasa \"seharusnya begitu\", pakai はず.</div>","n4-13":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜てもいいです」artinya <b>\"boleh ~\"</b> atau <b>\"~ juga tidak apa-apa\"</b>. Kalau ditambah 「か」di belakangnya jadi \"bolehkah ~?\". Ini ungkapan yang paling sering dipakai di Jepang untuk <b>meminta izin</b>. Di toko, saat mau memotret, duduk di kursi kosong, atau mencoba baju, kamu membuka pembicaraan dengan pola ini.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah verba ke bentuk て dulu, lalu tambahkan 「もいいです」.<br><span class='gd-pair'><span class='gd-jp'>使う</span> → <span class='gd-jp'>使って</span> → <span class='gd-jp'>使ってもいいです</span></span></div><div class='gd-h'>Cara mengubah: lihat dulu kelompok verbanya</div><div class='gd-sec'><b>Kelompok 1 (verba godan)</b>: lihat huruf terakhirnya.<br>う、つ、る → って：<span class='gd-pair'><span class='gd-jp'>座る</span> → <span class='gd-jp'>座って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><br>む、ぶ、ぬ → んで：<span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休んで</span></span><span class='gd-pair'><span class='gd-jp'>呼ぶ</span> → <span class='gd-jp'>呼んで</span></span><br>く → いて：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span>（hanya <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span> yang jadi pengecualian）<br>ぐ → いで：<span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br>す → して：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span></div><div class='gd-sec'><b>Kelompok 2 (verba ichidan)</b>: buang 「る」, lalu tambahkan て.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見て</span></span></div><div class='gd-sec'><b>Kelompok 3 (hanya dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span>（きて）</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Menanyakan boleh atau tidak</span>Tambahkan 「か」di akhir kalimat.</div><div class='gd-ex-line'>・<span class='gd-jp'>この椅子を使ってもいいですか。</span>（Boleh pakai kursi ini?）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに座ってもいいですか。</span>（Boleh duduk di sini?）</div><div class='gd-sec'><span class='gd-tag'>Cara menjawab</span>Boleh：<span class='gd-jp'>はい、どうぞ。</span>（Ya, silakan）、<span class='gd-jp'>いいですよ。</span>（Boleh kok）<br>Tidak boleh：<span class='gd-jp'>すみません、ちょっと…。</span>（Maaf, agak kurang pas...）</div><div class='gd-sec'><span class='gd-tag'>Memberi tahu bahwa boleh</span>Biasanya ditambah 「よ」di akhir kalimat, supaya terdengar lebih ramah.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休んでもいいですよ。</span>（Besok boleh libur kok）</div><div class='gd-ex-line'>・<span class='gd-jp'>鉛筆で書いてもいいです。</span>（Boleh menulis pakai pensil）</div><div class='gd-sec'><span class='gd-tag'>Antar teman</span>Buang です, dan dalam percakapan 「も」pun sering dihilangkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>これ、食べていい？</span>（Ini boleh dimakan?）</div><div class='gd-sec'>Kalau mau bertanya dengan lebih sopan kepada atasan atau tamu, ganti いい dengan <span class='gd-jp'>よろしい</span>：<span class='gd-jp'>写真を撮ってもよろしいですか。</span>（Permisi, boleh saya mengambil foto?）</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Kalau bentuk て-nya berakhiran 「で」, yang menyusul adalah 「でもいい」：<span class='gd-jp'>休んでもいい</span>, jangan ditulis 休んてもいい.<br>・Buku pelajaran mengajarkan <span class='gd-jp'>いいえ、いけません</span> untuk menolak pertanyaan 「〜てもいいですか」, tapi dalam percakapan nyata itu terdengar sangat keras, seperti memarahi orang. Sehari-hari orang biasanya bilang <span class='gd-jp'>すみません、ちょっと…</span>.<br>・「〜てもいいですよ」artinya <b>memberi izin</b>, nadanya agak dari atas ke bawah. Kalau kamu bilang <span class='gd-jp'>帰ってもいいですよ</span> kepada guru atau atasan, itu sangat tidak sopan.<br>・Kata \"bisa\" dalam bahasa Indonesia juga dipakai untuk kemampuan. \"Saya bisa bicara bahasa Jepang\" sebenarnya berarti \"saya mampu bicara\", jadi dalam bahasa Jepang katakan <span class='gd-jp'>日本語が話せます</span>. Kalau kamu bilang <span class='gd-jp'>日本語を話してもいいです</span>, artinya jadi \"boleh bicara bahasa Jepang\".</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Empat pola \"boleh, tidak boleh, tidak perlu, harus\" ini mirip sekali. Lihat dengan satu hal yang sama:<br><span class='gd-tag'>Melakukan, OK</span><span class='gd-jp'>明日は来てもいいです。</span>（Besok boleh datang）<br><span class='gd-tag'>Melakukan, NG</span><span class='gd-jp'>明日は来てはいけません。</span>（Besok tidak boleh datang）<br><span class='gd-tag'>Tidak melakukan, OK</span><span class='gd-jp'>明日は来なくてもいいです。</span>（Besok tidak datang pun tidak apa-apa）<br><span class='gd-tag'>Tidak melakukan, NG</span><span class='gd-jp'>明日は来なくてはいけません。</span>（Besok harus datang）<br>Kotak terakhir juga sering diucapkan <span class='gd-jp'>来なければなりません</span>, artinya sama.</div><div class='gd-warn'>Trik menilai: lihat dulu apakah di depannya 「て」atau 「なくて」, lalu lihat apakah di belakangnya 「いい」atau 「いけない」.</div><div class='gd-sec'>Jangan tertukar juga dengan <b>ことができます</b>:<br><span class='gd-jp'>ここで泳いでもいいですか。</span>（Boleh berenang di sini?：menanyakan izin）<br><span class='gd-jp'>泳ぐことができますか。</span>（Kamu bisa berenang?：menanyakan kemampuan）</div><div class='gd-warn'>Trik menilai: untuk menanyakan \"boleh atau tidak\" pakai てもいい; untuk \"bisa atau tidak, mampu atau tidak\" pakai ことができる.</div><div class='gd-h'>Setelah ini, lanjut pelajari</div><div class='gd-sec'>Pelajari tiga kotak lain dari tabel di atas: 「〜てはいけません」（larangan）、「〜なくてもいいです」（tidak perlu）、「〜なければなりません」（kewajiban）.</div>","n4-14":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜てはいけません」artinya <b>\"tidak boleh ~\"</b> atau <b>\"dilarang ~\"</b>. Pola ini dipakai guru saat mengumumkan aturan, saat menjelaskan tata tertib suatu tempat, atau saat orang tua bilang ke anak \"tidak boleh berbohong\". (Papan pengumuman sungguhan biasanya menulis 「<span class='gd-jp'>撮影禁止</span>」atau 「<span class='gd-jp'>〜ないでください</span>」, jarang menulis kalimat lengkapnya.)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menjelaskan aturan</span>Aturan sekolah, kantor, atau tempat tertentu, disampaikan secara lisan kepada lawan bicara.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ってはいけません。</span>（Di sini tidak boleh memotret）</div><div class='gd-ex-line'>・<span class='gd-jp'>授業中に寝てはいけません。</span>（Saat pelajaran tidak boleh tidur）</div><div class='gd-sec'><span class='gd-tag'>Mengajari anak, menyampaikan nasihat</span>Orang dewasa kepada anak, atau untuk hal yang harus dipatuhi semua orang, sering memakai 「〜てはいけない」tanpa ます.</div><div class='gd-ex-line'>・<span class='gd-jp'>うそをついてはいけないよ。</span>（Tidak boleh berbohong, ya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah verba ke <b>bentuk て</b> (bentuk yang sama dengan yang dipakai di 「〜てください」), lalu langsung tambahkan 「はいけません」.<br><span class='gd-pair'><span class='gd-jp'>撮る</span> → <span class='gd-jp'>撮って</span> → <span class='gd-jp'>撮ってはいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べてはいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してはいけません</span></span><br>Sebagian verba kelompok 1 (verba godan) punya bentuk て berakhiran 「で」, jadi menjadi 「ではいけません」：<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んではいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span> → <span class='gd-jp'>遊んではいけません</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>〜てはいけません</span>Bentuk sopan, dipakai saat menjelaskan aturan.<br><span class='gd-tag'>〜てはいけない</span>Bentuk biasa, untuk keluarga, teman, dan anak-anak.<br><span class='gd-tag'>〜ちゃいけない</span>Versi singkat percakapan: 「ては」jadi 「ちゃ」, 「では」jadi 「じゃ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>危ないから、ここで遊んじゃいけないよ。</span>（Berbahaya, jadi tidak boleh main di sini, ya）</div><div class='gd-sec'><span class='gd-tag'>〜ちゃだめ</span>Ganti 「いけない」dengan 「だめ」, lebih kasual, dan sering sekali terdengar saat orang tua menegur anak.</div><div class='gd-ex-line'>・<span class='gd-jp'>まだ食べちゃだめ。</span>（Belum boleh dimakan）</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・「は」di 「ては」dibaca <b>wa</b>, bukan ha.<br>・Setelah 「飲んで」「遊んで」harus <b>では</b>, jangan ditulis 飲んてはいけません. Saat dipersingkat, ia juga ikut menjadi 「じゃ」：<span class='gd-jp'>飲んじゃだめ</span>.<br>・Ungkapan ini <b>nadanya keras</b>, seperti sedang menetapkan aturan. Jangan dipakai langsung kepada atasan, tamu, atau orang yang lebih tua. Gunakan <span class='gd-jp'>〜ないでください</span> (tolong jangan ~), atau <span class='gd-jp'>〜はご遠慮ください</span> yang sering dipakai toko.<br>・Buku pelajaran sering mengajarkan 「<span class='gd-jp'>〜てもいいですか</span>」→「<span class='gd-jp'>いいえ、〜てはいけません</span>」, tapi dalam kenyataan, menjawab begitu terlalu ketus. Orang Jepang biasanya bilang <span class='gd-jp'>すみません、ここはちょっと…</span>, menolak dengan halus lewat 「ちょっと」.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Empat pola \"boleh / tidak boleh / tidak perlu / harus\" ini gampang tertukar. Lihat sekaligus dalam satu situasi yang sama (dokter menjelaskan soal obat):<br><b>てもいい</b> = boleh melakukan: <span class='gd-jp'>この薬は飲んでもいいです。</span>（Obat ini boleh diminum）<br><b>てはいけない</b> = tidak boleh melakukan: <span class='gd-jp'>この薬は飲んではいけません。</span>（Obat ini tidak boleh diminum）<br><b>なくてもいい</b> = tidak melakukan pun boleh: <span class='gd-jp'>この薬は飲まなくてもいいです。</span>（Obat ini tidak diminum pun tidak apa-apa）<br><b>なければならない</b> = harus melakukan: <span class='gd-jp'>この薬は飲まなければなりません。</span>（Obat ini harus diminum）</div><div class='gd-sec'>Yang paling perlu diwaspadai adalah 「<b>なくてはいけません</b>」. Di situ juga ada 「いけません」, tapi artinya <b>harus</b>, sama dengan 「なければなりません」:<br><span class='gd-jp'>飲んではいけません</span>（tidak boleh diminum）<br><span class='gd-jp'>飲まなくてはいけません</span>（harus diminum）<br>Bedanya hanya beberapa huruf, tapi artinya benar-benar berlawanan.</div><div class='gd-warn'>Trik menilai: lihat bagian di depan 「はいけません」. Kalau bentuk て biasa (<span class='gd-jp'>飲んで</span>) → tidak boleh; kalau 「なくて」(<span class='gd-jp'>飲まなくて</span>) → harus.</div>","n4-15":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜なくてもいいです」artinya <b>“tidak perlu ~”, “tidak ~ pun tidak apa-apa”</b>. Misalnya pegawai toko bilang “sepatunya tidak perlu dilepas ya”. Artinya hal itu <b>boleh tidak dilakukan, tapi kalau mau dilakukan juga boleh</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bilang ke lawan bicara bahwa tidak wajib</span>Dipakai untuk menenangkan lawan bicara dan meringankan bebannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は来なくてもいいです。</span>（Besok tidak perlu datang）</div><div class='gd-ex-line'>・<span class='gd-jp'>全部食べなくてもいいですよ。</span>（Tidak perlu dihabiskan semua, kok）</div><div class='gd-sec'><span class='gd-tag'>Menanyakan perlu atau tidak</span>Tambahkan「か」di akhir kalimat, artinya “Tidak ~ juga boleh?”.</div><div class='gd-ex-line'>・<span class='gd-jp'>靴を脱がなくてもいいですか。</span>（Tidak perlu lepas sepatu?）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、脱がなくてもいいですよ。</span>（Iya, tidak perlu dilepas）</div><div class='gd-h'>Cara membentuknya</div><div class='gd-sec'>Ubah verba ke bentuk ない (bentuk “tidak ~”), lalu ganti 「い」 di akhir dengan 「くて」, dan tambahkan 「もいい」.<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → い diganti くて → <span class='gd-jp'>行かなくて</span></span> → tambah もいい → <span class='gd-pair'><span class='gd-jp'>行かなくてもいい</span></span><br>Supaya sopan, tambahkan 「です」 di belakangnya.</div><div class='gd-h'>Perubahan bentuk: lihat dulu kelompok verbanya</div><div class='gd-sec'><b>Kelompok 1 (verba godan)</b>: ganti bunyi terakhir dengan bunyi baris 「あ」 pada baris yang sama, tambah ない, lalu ubah jadi なくてもいい.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti か → <span class='gd-jp'>書かなくてもいい</span></span><br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らなくてもいい</span></span><br>Kalau berakhiran 「う」, ganti jadi <b>わ</b>: <span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わなくてもいい</span></span><br>Pengecualian: bentuk ない dari <span class='gd-jp'>ある</span> adalah 「ない」, jadi bentuknya <span class='gd-jp'>なくてもいい</span>, bukan あらなくてもいい.</div><div class='gd-ex-line'>・<span class='gd-jp'>予約がなくてもいいですか。</span>（Tanpa reservasi juga boleh?）</div><div class='gd-sec'><b>Kelompok 2 (verba ichidan)</b>: buang 「る」, lalu tambah なくてもいい.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>慌てる</span> → <span class='gd-jp'>慌てなくてもいい</span></span></div><div class='gd-sec'><b>Kelompok 3 (hanya dua, hafalkan saja)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来なくてもいい</span>（こなくても）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>今日は残業しなくてもいいです。</span>（Hari ini tidak perlu lembur）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Antar teman</span>Ganti 「です」 dengan 「よ」, dan sering kali 「も」 juga dibuang.</div><div class='gd-ex-line'>・<span class='gd-jp'>無理しなくていいよ。</span>（Tidak usah memaksakan diri, ya）</div><div class='gd-sec'><span class='gd-tag'>Cara lain</span>Ganti 「いい」 dengan 「大丈夫」, artinya sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>返事しなくても大丈夫です。</span>（Tidak perlu membalas juga tidak apa-apa）</div><div class='gd-sec'><span class='gd-tag'>Lebih sopan</span>Di kantor, toko, atau pengumuman resmi, kamu akan mendengar 「なくてもかまいません」.</div><div class='gd-ex-line'>・<span class='gd-jp'>印鑑は持ってこなくてもかまいません。</span>（Tidak perlu membawa stempel juga tidak apa-apa）</div><div class='gd-h'>Kesalahan yang sering terjadi</div><div class='gd-warn'>・Jangan langsung menempelkan ても setelah ない: 「行かないてもいい」 itu salah. Ganti い jadi くて, sehingga menjadi <span class='gd-jp'>行かなくてもいい</span>.<br>・<span class='gd-jp'>買う</span> menjadi <span class='gd-jp'>買わない</span>, bukan 買あない; <span class='gd-jp'>ある</span> menjadi <span class='gd-jp'>ない</span>, bukan あらない.<br>・Dalam bahasa Indonesia, “tidak usah datang” dan “jangan datang” hanya beda satu kata dan terdengar mirip, tapi dalam bahasa Jepang bedanya besar. <span class='gd-jp'>来なくてもいい</span> artinya “tidak datang boleh, datang juga boleh”. Tidak ada maksud menyuruh orang itu jangan datang.<br>・Kalau ada yang bertanya 「<span class='gd-jp'>〜なくてもいいですか</span>」 dan jawabannya “wajib dilakukan”, jawablah dengan <span class='gd-jp'>いいえ、〜なければなりません</span>. Jangan hanya bilang いいえ lalu berhenti.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Satu hal yang sama, “pergi ke kantor besok”, dengan empat cara bilang:<br><b>てもいい</b> = boleh dilakukan: <span class='gd-jp'>明日、会社に行ってもいいです。</span>（Besok boleh pergi ke kantor）<br><b>なくてもいい</b> = tidak dilakukan juga boleh: <span class='gd-jp'>明日、会社に行かなくてもいいです。</span>（Besok tidak perlu pergi ke kantor）<br><b>てはいけない</b> = tidak boleh dilakukan: <span class='gd-jp'>明日、会社に行ってはいけません。</span>（Besok tidak boleh pergi ke kantor）<br><b>なければならない</b> = harus dilakukan: <span class='gd-jp'>明日、会社に行かなければなりません。</span>（Besok harus pergi ke kantor）</div><div class='gd-sec'>Satu lagi yang sering tertukar adalah 「ないでください」:<br><span class='gd-jp'>来ないでください。</span>（Tolong jangan datang: menyuruh orang itu tidak melakukannya）<br><span class='gd-jp'>来なくてもいいです。</span>（Tidak perlu datang: datang atau tidak sama saja）</div><div class='gd-warn'>Trik membedakan: kalau mau bilang “tidak perlu, tidak usah”, pakai なくてもいい; kalau mau bilang “jangan, dilarang”, pakai ないでください atau てはいけない.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kata sifat dan kata benda juga bisa dipakai dengan arti yang sama: <span class='gd-jp'>高くなくてもいいです。</span>（Tidak mahal juga tidak apa-apa）、<span class='gd-jp'>上手じゃなくてもいいです。</span>（Tidak jago juga tidak apa-apa）. Lanjutkan dengan 「<span class='gd-jp'>〜なければなりません</span>」, dan kamu bisa menjelaskan “tidak perlu” dan “harus” sekaligus dengan jelas.</div>","n4-16":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜なければなりません」artinya <b>“harus ~”, “wajib ~”</b>. Cara berpikir bahasa Jepang di sini menarik: sebenarnya artinya “kalau tidak dilakukan, tidak boleh”. Tidak boleh tidak dilakukan, berarti harus dilakukan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Aturan・kewajiban</span>Dipakai untuk aturan dan kewajiban: hal yang ditetapkan sekolah atau kantor, atau hal yang mau tidak mau harus dilakukan karena keadaan.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにレポートを出さなければなりません。</span>（Laporan harus dikumpulkan paling lambat besok）</div><div class='gd-ex-line'>・<span class='gd-jp'>学校では制服を着なければなりません。</span>（Di sekolah harus memakai seragam）</div><div class='gd-sec'><span class='gd-tag'>Merasa diri harus melakukannya</span>Tidak ada yang mengharuskan, tapi kamu sendiri merasa “sudah waktunya”.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう11時だ。帰らなければならない。</span>（Sudah jam 11. Aku harus pulang）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を毎日飲まなければなりません。</span>（Aku harus minum obat setiap hari）</div><div class='gd-h'>Cara membentuknya</div><div class='gd-sec'>Tiga langkah: ubah dulu ke bentuk ない (bentuk “tidak ~”), buang 「ない」 di akhir, lalu sambungkan <b>なければなりません</b>.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span></span> → buang ない → <span class='gd-pair'><span class='gd-jp'>行か</span> → <span class='gd-jp'>行かなければなりません</span></span></div><div class='gd-sec'><b>Kelompok 1 (verba godan)</b>:<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書かなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わなければなりません</span></span>（yang berakhiran う berubah jadi わ, bukan あ）</div><div class='gd-sec'><b>Kelompok 2 (verba ichidan)</b>:<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きなければなりません</span></span></div><div class='gd-sec'><b>Kelompok 3 (hanya dua, hafalkan saja)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来なければなりません</span>（こなければ）</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>なければなりません</span>Bentuk sopan, dipakai kepada guru, atasan, dan tamu.<br><span class='gd-tag'>なければならない</span>Bentuk biasa, dipakai saat bicara sendiri dan dalam tulisan.<br><span class='gd-tag'>なきゃ／ないと</span>Bahasa lisan antar teman. 「なければ」 dipersingkat jadi 「なきゃ」, atau kalimat langsung berhenti di 「ないと」.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、もう行かなきゃ。</span>（Ah, aku harus pergi sekarang）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日早いから、早く寝ないと。</span>（Besok harus bangun pagi, jadi harus tidur lebih awal）</div><div class='gd-sec'>Untuk bilang “waktu itu harus ~” (lampau), ubah akhirannya jadi <b>なりませんでした</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は遅くまで働かなければなりませんでした。</span>（Kemarin aku harus bekerja sampai larut）</div><div class='gd-sec'>Kamu juga akan mendengar 「<span class='gd-jp'>〜なければいけません</span>」. Artinya hampir sama dan sering dipakai dalam percakapan sehari-hari.</div><div class='gd-h'>Kesalahan yang sering terjadi</div><div class='gd-warn'>・Sambungkan ke bentuk ない, bukan bentuk kamus (bentuk asli di kamus): bukan 行くなければ, tapi <span class='gd-jp'>行かなければ</span>.<br>・Kalimatnya panjang sehingga mudah salah ucap. Ingat dengan memecahnya jadi 「な・け・れ・ば」 + 「なりません」, bukan なくれば atau なけば.<br>・Jangan mengira 「ません」 di akhir berarti “tidak melakukan”. Arti seluruh kalimatnya adalah <b>harus dilakukan</b>.<br>・<span class='gd-jp'>来る</span> dibaca <b>こなければ</b>, bukan きなければ.<br>・「なきゃ」「ないと」 dipakai antar teman. Kepada atasan atau guru, pakai bentuk lengkap なければなりません.<br>・Saat meminta orang lain melakukan sesuatu, langsung bilang “kamu harus ~” terdengar sangat keras. Biasanya pakai 「〜てください」 supaya lebih sopan.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Keempat pola ini sering keluar bersamaan di ujian. Bandingkan dengan satu hal yang sama, “pergi ke sekolah besok”:<br><span class='gd-jp'>明日、学校に行かなければなりません。</span>（Besok <b>harus</b> pergi ke sekolah）<br><span class='gd-jp'>明日、学校に行かなくてもいいです。</span>（Besok <b>tidak pergi juga boleh</b>）<br><span class='gd-jp'>明日、学校に行ってもいいです。</span>（Besok <b>boleh</b> pergi ke sekolah）<br><span class='gd-jp'>明日、学校に行ってはいけません。</span>（Besok <b>tidak boleh</b> pergi ke sekolah）</div><div class='gd-sec'>Perhatian khusus: kalau ditanya 「<span class='gd-jp'>〜なければなりませんか</span>」 (Harus ~?) dan kamu mau menjawab “tidak perlu”, katakan <b>なくてもいいです</b>. Itu bukan bentuk negatif dari なければなりません.</div><div class='gd-ex-line'>・<span class='gd-jp'>名前を書かなければなりませんか。</span>（Apakah harus menulis nama?）</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、書かなくてもいいです。</span>（Tidak, tidak perlu menulis juga boleh）</div><div class='gd-sec'>Satu lagi yang sering tertukar adalah <b>ほうがいい</b>. Ini hanya “saran”, bukan paksaan:<br><span class='gd-jp'>薬を飲んだほうがいいです。</span>（Sebaiknya minum obat）<br><span class='gd-jp'>薬を飲まなければなりません。</span>（Harus minum obat）</div><div class='gd-warn'>Trik membedakan: “harus” adalah なければなりません, “tidak perlu” adalah なくてもいい, “sebaiknya” adalah ほうがいい.</div>","n4-1":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜までに」artinya <b>「paling lambat sebelum ～ (harus sudah selesai)」</b>, alias batas waktu. Mirip tulisan di tagihan: \"Harap bayar sebelum tanggal 10 Mei\", nah kata \"sebelum\" itu padanannya までに. Intinya: <b>sebelum titik waktu itu tiba, satu hal harus sudah beres</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyampaikan batas waktu</span>Guru, atasan, atau pemilik toko bilang kepadamu \"paling lambat kapan harus selesai\".</div><div class='gd-ex-line'>・<span class='gd-jp'>レポートは金曜日までに出してください。</span>（Tolong kumpulkan laporannya paling lambat hari Jumat）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにお願いします。</span>（Tolong berikan paling lambat besok ya）</div><div class='gd-sec'><span class='gd-tag'>Target sendiri</span>Menetapkan batas waktu untuk diri sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>5時までに駅に着きたい。</span>（Aku ingin sampai di stasiun sebelum jam 5）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏までに5キロやせたい。</span>（Aku ingin turun 5 kilo sebelum musim panas）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Waktu, hari, kejadian</b> langsung diberi までに：<br><span class='gd-pair'><span class='gd-jp'>3時</span> → <span class='gd-jp'>3時までに</span></span><span class='gd-pair'><span class='gd-jp'>試験</span> → <span class='gd-jp'>試験までに</span></span><br><b>Kata kerja</b> memakai bentuk kamus (bentuk dasar) + までに, artinya \"sebelum ～ terjadi\":<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るまでに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>母が帰るまでに部屋を片付けます。</span>（Aku akan merapikan kamar sebelum ibu pulang）</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Bedanya cuma satu 「に」, tapi artinya jauh berbeda.<br><b>まで</b> = tindakan <b>berlangsung terus</b> sampai waktu itu, baru berhenti.<br><b>までに</b> = <b>menyelesaikan</b> sesuatu sebelum waktu itu; begitu selesai, ya sudah.</div><div class='gd-ex-line'>・<span class='gd-jp'>5時まで待ちます。</span>（Aku menunggu sampai jam 5: menunggu terus dari sekarang hingga jam 5）</div><div class='gd-ex-line'>・<span class='gd-jp'>5時までに来てください。</span>（Tolong datang sebelum jam 5: jam 4 atau jam 4.30 boleh）</div><div class='gd-ex-line'>・<span class='gd-jp'>10時まで勉強します。</span>（Aku belajar sampai jam 10）</div><div class='gd-ex-line'>・<span class='gd-jp'>10時までにお風呂に入ります。</span>（Aku akan mandi sebelum jam 10）</div><div class='gd-warn'>Trik cepat: kalau dalam bahasa Indonesia cocok dibilang \"terus ～ sampai …\", pakai <b>まで</b>; kalau cocok dibilang \"paling lambat sebelum … harus sudah ～\", pakai <b>までに</b>.</div><div class='gd-h'>Hati-hati salah paham</div><div class='gd-warn'>・Untuk \"melakukan sesuatu terus-menerus sampai waktu itu\" (misalnya menunggu sampai jam 5, belajar sampai jam 10), harus pakai まで, bukan までに. Contohnya <span class='gd-jp'>5時までに待ちます</span> itu salah; yang benar <span class='gd-jp'>5時まで待ちます</span>. Tapi kalau maksudnya \"menyiapkan sesuatu sebelum waktu tertentu\", までに boleh dipakai, seperti <span class='gd-jp'>試験までに勉強しておきます</span> (belajar dulu sampai siap sebelum ujian), dan orang Jepang sering mengatakannya.<br>・<span class='gd-jp'>金曜日までに</span> biasanya termasuk hari Jumat itu sendiri, jadi mengumpulkan hari Jumat masih dianggap tepat waktu; tidak harus hari Kamis.<br>・Kalau di depannya kata kerja, pakai bentuk kamus: katakan <span class='gd-jp'>日本に来るまでに</span>, bukan 「来たまでに」.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau ditambah 「は」 jadi <span class='gd-jp'>までには</span>, nuansanya menjadi \"setidaknya sebelum ～\": <span class='gd-jp'>夜までには帰ります。</span>（Paling lambat sebelum malam pasti aku sudah pulang）</div>","n4-4":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「AはBより～」artinya <b>\"A lebih ～ daripada B\"</b>. <span class='gd-jp'>東京は大阪より人が多い。</span> berarti \"Penduduk Tokyo lebih banyak daripada Osaka\".<br>Perbedaan terbesarnya ada di <b>urutan</b>: dalam bahasa Indonesia \"daripada\" diletakkan di depan B, sedangkan <span class='gd-jp'>より</span> dalam bahasa Jepang ditaruh <b>setelah</b> B, seperti \"daripada\" yang menempel di belakang B.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Tokoh utama A diberi <span class='gd-jp'>は</span>, B yang dibandingkan diberi <span class='gd-jp'>より</span>, lalu di akhir letakkan kata sifat.<br><span class='gd-tag'>Kata sifat い</span> langsung ditambah です.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は昨日より暑いです。</span>（Hari ini lebih panas daripada kemarin）</div><div class='gd-sec'><span class='gd-tag'>Kata sifat な</span> langsung ditambah です; dalam percakapan santai diganti だ atau tidak ditambah apa-apa.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車はバスより便利です。</span>（Kereta lebih praktis daripada bus）</div><div class='gd-sec'><span class='gd-tag'>Membandingkan satu aspek</span>Kalau yang dibandingkan adalah \"segi tertentu\", pakai pola 「～が＋kata sifat」.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄は私より背が高いです。</span>（Kakakku lebih tinggi daripada aku）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は私より料理が上手です。</span>（Kakak perempuanku lebih pandai memasak daripada aku）</div><div class='gd-sec'><span class='gd-tag'>Bisa juga diikuti kata kerja</span>Di belakangnya tidak harus kata sifat, bisa juga \"bagaimana melakukannya\".</div><div class='gd-ex-line'>・<span class='gd-jp'>弟は私よりよく食べます。</span>（Adikku makannya lebih banyak daripada aku）</div><div class='gd-sec'>Kamu juga akan mendengar <span class='gd-jp'>よりも</span>. Artinya sama, hanya nuansanya lebih menekankan.</div><div class='gd-h'>Hati-hati salah paham</div><div class='gd-warn'>・<b>Kata yang ditempeli より adalah pihak yang \"kalah\" dibandingkan.</b> Kalau menerjemahkan langsung mengikuti urutan bahasa Indonesia, gampang salah taruh: <span class='gd-jp'>東京より大阪は人が多い</span> jadi \"Penduduk Osaka lebih banyak daripada Tokyo\", artinya terbalik total.<br>・Kata sifat <b>tidak berubah bentuk</b>, dan tidak perlu dipaksa menambah kata \"lebih\". Dalam bahasa Indonesia kita sering bilang \"lebih tinggi\", tapi dalam bahasa Jepang <span class='gd-jp'>高いです</span> sudah cukup. Kalau ditambah <span class='gd-jp'>もっと</span>, malah jadi bermakna \"keduanya sudah tinggi, dan A masih lebih tinggi lagi\".<br>・Aspek yang dibandingkan memakai <span class='gd-jp'>が</span>: <span class='gd-jp'>背が高い</span>, <span class='gd-jp'>気温が高い</span>, jangan ditulis dengan を.<br>・Untuk mengatakan \"A tidak seperti B dalam hal ～\", orang Jepang biasanya memakai <span class='gd-jp'>ほど…ない</span>, dan jarang memakai 「より～くない」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama membandingkan jumlah penduduk Tokyo dan Osaka:<br><b>AはBより</b> = memperkenalkan A sebagai tokoh utama, sekalian dibandingkan dengan B: <span class='gd-jp'>東京は大阪より人が多いです。</span>（Penduduk Tokyo lebih banyak daripada Osaka）<br><b>BよりAのほうが</b> = menaruh keduanya berdampingan lalu <b>memilih A</b>, sering dipakai untuk menjawab \"Mana yang lebih ～?\": <span class='gd-jp'>大阪より東京のほうが人が多いです。</span>（Dibandingkan Osaka, penduduk Tokyo lebih banyak）<br><b>BほどAない</b> = sebaliknya, mengatakan \"tidak sampai ～\": <span class='gd-jp'>大阪は東京ほど人が多くないです。</span>（Penduduk Osaka tidak sebanyak Tokyo）</div><div class='gd-warn'>Trik cepat: untuk sekadar menggambarkan \"A lebih ～ daripada B\", pakai <span class='gd-jp'>AはBより</span>; untuk memilih salah satu dari dua, pakai <span class='gd-jp'>のほうが</span>; untuk mengatakan \"tidak sampai ～\", pakai <span class='gd-jp'>ほど…ない</span>.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Menanyakan \"Mana yang lebih ～?\": <span class='gd-jp'>電車とバスとどちらが便利ですか。</span>（Kereta dan bus, mana yang lebih praktis?）Jawabnya pakai <span class='gd-jp'>～より…ほうが</span>. Kalau ada tiga hal atau lebih dan ingin memilih yang nomor satu, lanjutkan belajar <span class='gd-jp'>～でいちばん</span>.</div>","n4-21":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「し」kira-kira berarti <b>“selain ～, ～ juga”</b> atau <b>“lagi pula ～”</b>. Kalau kamu menjelaskan “kenapa”, kamu menumpuk alasan satu per satu, lalu menutupnya dengan kesimpulan. Misalnya “Toko ini murah, enak pula, makanya aku sering ke sini”. Dalam bahasa Jepang, し menyambung “murah” dan “enak”.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いし、おいしいし、よく来ます。</span>（Toko ini murah dan enak, makanya aku sering ke sini）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan pakai <b>bentuk biasa</b> (bentuk tanpa ます atau です), lalu langsung tambahkan し.<br><b>Kata kerja</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るし</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>ないし</span></span><span class='gd-pair'><span class='gd-jp'>疲れた</span> → <span class='gd-jp'>疲れたし</span></span><br><b>Kata sifat-い</b>：<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いし</span></span><span class='gd-pair'><span class='gd-jp'>遠くない</span> → <span class='gd-jp'>遠くないし</span></span><br><b>Kata sifat-な</b>：tambahkan 「だ」dulu, baru し. <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだし</span></span><br><b>Kata benda</b>：sama, tambahkan 「だ」. <span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だし</span></span><br>Kalau bicara dengan orang yang lebih tua atau tamu, kamu juga bisa pakai bentuk sopan: <span class='gd-jp'>便利ですし</span>、<span class='gd-jp'>あまり時間もありませんし</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menumpuk alasan menuju kesimpulan</span>Ini pemakaian yang paling umum. Di depan alasan sering dipasangkan 「も」, kesannya seperti “ini juga ～, itu juga ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>お金もないし、時間もないし、旅行は無理です。</span>（Uang tidak ada, waktu juga tidak ada, jadi liburan itu mustahil）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨も降っているし、疲れているし、タクシーで帰りましょう。</span>（Hujan, mana capek lagi, ayo pulang naik taksi）</div><div class='gd-sec'><span class='gd-tag'>Menyebut kelebihan atau kekurangan orang atau benda</span>Dipakai untuk menggambarkan ciri-ciri seseorang atau suatu tempat.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは優しいし、おもしろいし、みんなに人気がある。</span>（Tanaka itu baik, lucu pula, jadi disukai semua orang）</div><div class='gd-sec'><span class='gd-tag'>Hanya menyebut satu alasan</span>Menyebut satu alasan saja juga boleh. Kesannya seperti “(masih ada alasan lain sih) tapi cuma karena ini saja ～”, nadanya lebih lembut.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう遅いし、そろそろ帰ります。</span>（Sudah larut, aku pulang dulu ya）</div><div class='gd-sec'>Kesimpulannya bahkan bisa dihilangkan supaya lawan bicara mengerti sendiri. Ini berguna sekali untuk menolak orang secara halus:<br><span class='gd-jp'>今日はちょっと疲れてるし…</span>（Hari ini aku agak capek, soalnya……）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata sifat-な dan kata benda <b>wajib ditambah だ</b>: yang benar <span class='gd-jp'>静かだし</span>、<span class='gd-jp'>雨だし</span>, tidak boleh 「静かし」「雨し」.<br>・Alasan yang ditumpuk harus <b>searah</b>, semuanya mendukung satu kesimpulan yang sama. Misalnya untuk mengatakan “aku suka toko ini”, tumpuk “murah” dan “enak”. Jangan campur satu hal baik dengan satu hal buruk.<br>・し punya kesan “bukan hanya ini”. Kalau kamu hanya punya satu alasan yang jelas dan ingin menyampaikannya dengan tegas, 「から」atau「ので」lebih langsung.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>し</b>＝menumpuk beberapa alasan, nuansanya “selain ～, ～ juga, jadi…”:<br><span class='gd-jp'>この店は安いし、おいしいし、よく来ます。</span>（Murah dan enak, makanya aku sering ke sini）<br><b>から・ので</b>＝menyebut jelas “justru karena ini”:<br><span class='gd-jp'>この店は安いから、よく来ます。</span>（Karena murah, aku sering ke sini）</div><div class='gd-sec'><b>たり</b>juga menyebut beberapa hal sekaligus, tetapi yang dideretkan adalah <b>hal-hal yang dilakukan</b> sebagai contoh, bukan alasan:<br><span class='gd-jp'>週末は映画を見たり、買い物をしたりします。</span>（Di akhir pekan aku misalnya nonton film, belanja, dan sebagainya）<br><span class='gd-jp'>週末は暇だし、天気もいいし、出かけよう。</span>（Akhir pekan ini senggang, cuacanya juga bagus, ayo jalan-jalan）</div><div class='gd-warn'>Trik cepat: kalau menjawab “kenapa” dengan beberapa alasan bertumpuk, pakai し. Kalau hanya satu alasan yang jelas, pakai から・ので. Kalau menyebut “apa saja yang dilakukan”, pakai たり.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau setelah menyebut alasan kamu ingin menambah satu lagi, pakai 「それに」(lagi pula) untuk kalimat berikutnya: <span class='gd-jp'>この部屋は広いし、駅にも近い。それに家賃も安い。</span>（Kamar ini luas, dekat stasiun pula. Lagi pula sewanya murah）</div>","n4-36":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜でしょう」mirip dengan <b>“kira-kira ～ ya” / “mungkin ～”</b>. Kalau nada di akhir kalimat turun, artinya kamu sedang <b>menebak</b>. Kalau nada naik, artinya jadi “～ kan?”, yaitu <b>meminta konfirmasi dari lawan bicara</b>. 「だろう」adalah bentuk biasanya dengan arti yang sama, hanya saja tidak terasa sopan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menebak (nada turun)</span>Kamu tidak yakin, tapi merasa kemungkinan besar begitu. Ramalan cuaca paling suka memakainya.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るでしょう。</span>（Besok kemungkinan hujan）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう家に帰ったでしょう。</span>（Pak Tanaka mungkin sudah pulang ke rumah）</div><div class='gd-sec'>Sering muncul bersama「<span class='gd-jp'>たぶん</span>」(mungkin): <span class='gd-jp'>たぶん大丈夫でしょう。</span>（Mungkin tidak apa-apa）</div><div class='gd-sec'><span class='gd-tag'>Konfirmasi (nada naik)</span>Kamu merasa lawan bicara juga tahu dan akan setuju, jadi kamu bertanya supaya dia mengangguk. Dalam percakapan sering dipendekkan menjadi「<span class='gd-jp'>でしょ？</span>」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これ、おいしいでしょう？</span>（Ini enak, kan?）</div><div class='gd-ex-line'>・<span class='gd-jp'>ほら、言ったでしょ？</span>（Tuh kan, bukannya sudah kubilang?）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan pakai <b>bentuk biasa</b> (bentuk tanpa です、ます), lalu tambahkan でしょう atau だろう.<br>Kata kerja: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くでしょう</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないでしょう</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったでしょう</span></span><br>Kata sifat-い: langsung tambahkan. <span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いでしょう</span></span><br>Kata benda dan kata sifat-な: <b>buang だ</b> lalu tambahkan. <span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生でしょう</span></span><span class='gd-pair'><span class='gd-jp'>元気だ</span> → <span class='gd-jp'>元気でしょう</span></span><br>Untuk bentuk lampau,「だった」harus dipertahankan: <span class='gd-pair'><span class='gd-jp'>学生だった</span> → <span class='gd-jp'>学生だったでしょう</span></span></div><div class='gd-h'>Memilih antara でしょう dan だろう</div><div class='gd-sec'><b>でしょう</b>: sopan. Dipakai untuk orang yang belum akrab, situasi formal, berita, dan ramalan cuaca.<br><b>だろう</b>: bentuk biasa. Paling sering muncul saat <b>berpikir dalam hati, bicara sendiri, atau di tulisan</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は晴れるだろう。</span>（Besok mungkin cerah: kamu sedang berpikir sendiri）</div><div class='gd-sec'>Kalau langsung dipakai ke lawan bicara,「<span class='gd-jp'>だろう</span>」「<span class='gd-jp'>だろ？</span>」terdengar lebih maskulin dan agak kasar. Saat mengobrol dengan teman, banyak orang (terutama perempuan) memakai「<span class='gd-jp'>でしょ？</span>」.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata benda dan kata sifat-な jangan sisakan だ: yang benar <span class='gd-jp'>学生でしょう</span>, bukan 「学生だでしょう」.<br>・“Akan” dalam bahasa Indonesia tidak selalu berarti でしょう. “Besok aku akan pergi” adalah keputusanmu sendiri, jadi langsung bilang <span class='gd-jp'>明日行きます</span>. Kalau pakai 「行くでしょう」, kedengarannya seperti kamu menebak apakah dirimu sendiri akan pergi, dan itu aneh.<br>・「<span class='gd-jp'>でしょう？</span>」untuk konfirmasi punya kesan “kamu pasti tahu, kan”, jadi kurang sopan kalau dipakai ke guru atau atasan. Lebih aman diganti 「<span class='gd-jp'>〜ですよね</span>」.<br>・でしょう diucapkan dengan vokal panjang (でしょー), sedangkan 「でしょ」yang pendek adalah versi percakapan yang dipendekkan.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Untuk hal yang sama: apakah Pak Tanaka hari ini datang atau tidak?<br>・<span class='gd-jp'>田中さんは来るでしょう。</span>（Pak Tanaka mungkin datang）→ Menurutku <b>kemungkinan besar datang</b>.<br>・<span class='gd-jp'>田中さんは来るかもしれません。</span>（Pak Tanaka bisa jadi datang）→ <b>Fifty-fifty</b>, kalau tidak datang pun tidak mengejutkan.<br>・<span class='gd-jp'>田中さんは来るはずです。</span>（Pak Tanaka seharusnya datang）→ <b>Ada dasarnya</b>, misalnya kemarin dia sendiri bilang akan datang.</div><div class='gd-warn'>Trik cepat: “bisa jadi” pakai かもしれない, “kemungkinan besar” pakai でしょう, “seharusnya menurut logika” pakai はずだ.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau ditambah 「と思います」di belakang, nadanya lebih lembut dan sering dipakai siapa saja: <span class='gd-jp'>明日は寒くなるだろうと思います。</span>（Menurutku besok kemungkinan jadi dingin）<br>Kalau でしょう diubah jadi pertanyaan 「でしょうか」, hasilnya lebih sopan daripada 「ですか」: <span class='gd-jp'>すみません、駅はどこでしょうか。</span>（Permisi, stasiun ada di mana ya?）</div>","n4-11":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ほうがいい」 artinya <b>“sebaiknya kamu ～” atau “sebaiknya jangan ～”</b>. Kalau temanmu demam, kamu bilang “Sebaiknya kamu ke dokter ya”. Dalam bahasa Jepang jadinya <span class='gd-jp'>病院に行ったほうがいいよ</span>. Pola ini dipakai untuk memberi saran, dengan nuansa “kalau tidak begitu, mungkin kurang baik ya”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Sebaiknya melakukan ～</span>Kata kerja <b>bentuk た</b> + ほうがいい<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休んだほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行ったほうがいい</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べたほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>したほうがいい</span></span><br>Kalau bentuk た belum lancar, kamu bisa mulai dari bentuk て: ganti 「て」 jadi 「た」, dan 「で」 jadi 「だ」. Selesai.<span class='gd-pair'><span class='gd-jp'>休んで</span> → <span class='gd-jp'>休んだ</span></span></div><div class='gd-sec'><span class='gd-tag'>Sebaiknya jangan ～</span>Kata kerja <b>bentuk ない</b> + ほうがいい<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かないほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないほうがいい</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないほうがいい</span>（こない）</span></div><div class='gd-sec'>Akhir kalimat tergantung lawan bicara: ke teman cukup 「〜ほうがいいよ」, dan kalau mau lebih sopan pakai 「〜ほうがいいです」.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていったほうがいいよ。</span>（Sepertinya mau hujan, sebaiknya bawa payung ya）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前にコーヒーを飲まないほうがいいです。</span>（Sebaiknya jangan minum kopi sebelum tidur）</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・Yang dipakai memang bentuk た, tetapi artinya <b>bukan lampau</b>. <span class='gd-jp'>行ったほうがいい</span> berarti kamu disarankan pergi sekarang atau nanti, bukan “sudah pernah pergi”.<br>・Kamu mungkin tergoda memakai bentuk kamus, jadi 「行くほうがいい」. Untuk memberi saran konkret kepada orang lain, orang Jepang biasanya bilang <span class='gd-jp'>行ったほうがいい</span>. Hafalkan ini dulu, itu yang paling aman.<br>・Untuk negatif, cukup pakai bentuk ない, <b>tidak perlu diubah lagi ke bentuk た</b>. Yang benar <span class='gd-jp'>行かないほうがいい</span>, bukan 「行かなかったほうがいい」.<br>・Nuansanya sebenarnya tidak ringan. Kalau kamu langsung bilang 「〜たほうがいいですよ」 kepada atasan atau guru, kedengarannya seperti sedang menggurui. Supaya lebih sopan, tambahkan 「と思います」: <span class='gd-jp'>少し休んだほうがいいと思います。</span>（Menurut saya, sebaiknya istirahat sebentar）<br>・Kalau 「ほう」 ditulis dengan kanji, jadinya 「方」. Di sini dibaca <b>ほう</b>, bukan かた seperti pada 「〜方（cara）」.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama dalam situasi sakit tenggorokan:<br><b>たほうがいい</b>＝saran. Tidak dilakukan pun boleh, hanya kurang baik: <span class='gd-jp'>のどが痛いなら、薬を飲んだほうがいいですよ。</span>（Kalau tenggorokanmu sakit, sebaiknya minum obat ya）<br><b>なければなりません</b>＝aturan, wajib dilakukan: <span class='gd-jp'>この薬は一日三回飲まなければなりません。</span>（Obat ini harus diminum tiga kali sehari）<br><b>たらいい</b>＝menawarkan satu cara, nuansanya lebih santai: <span class='gd-jp'>のどが痛いときは、温かいお茶を飲んだらいいですよ。</span>（Kalau tenggorokan sakit, minum teh hangat saja ya）</div><div class='gd-warn'>Tips menentukan: “sebaiknya ～ (kalau tidak, kurang baik)” pakai ほうがいい, “harus ～” pakai なければなりません, dan “begini saja sudah cukup” pakai たらいい.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Kalau いい diganti jadi よかった, artinya berubah jadi penyesalan “tahu begitu, ～”: <span class='gd-jp'>傘を持ってきたほうがよかった。</span>（Tahu begitu, aku bawa payung）</div>","n4-12":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜すぎる」 artinya <b>“terlalu ～” atau “～ berlebihan”</b>. Makan terlalu banyak, minum terlalu banyak, terlalu mahal, terlalu sulit. Selama sesuatu <b>melewati batas yang pas</b>, tambahkan 「すぎる」 di belakangnya. Versi sopannya 「すぎます」.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、ゲームをやりすぎました。</span>（Kemarin aku kebanyakan main game）</div><div class='gd-ex-line'>・<span class='gd-jp'>このかばんは高すぎます。</span>（Tas ini terlalu mahal）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Kata kerja</span>Ubah dulu ke bentuk ます, buang 「ます」, lalu sambung すぎる. Berlaku sama untuk ketiga golongan kata kerja.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みすぎる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べすぎる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span> → <span class='gd-jp'>しすぎる</span></span>（contoh: <span class='gd-jp'>心配しすぎる</span>＝terlalu khawatir）</div><div class='gd-sec'><span class='gd-tag'>Kata sifat い</span>Buang 「い」 di akhir, lalu sambung すぎる.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高すぎる</span></span><span class='gd-pair'><span class='gd-jp'>難しい</span> → <span class='gd-jp'>難しすぎる</span></span></div><div class='gd-sec'><span class='gd-tag'>Kata sifat な</span>Sambung langsung, <b>tanpa な</b>.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かすぎる</span></span><span class='gd-pair'><span class='gd-jp'>派手</span> → <span class='gd-jp'>派手すぎる</span></span></div><div class='gd-h'>すぎる sendiri juga berubah</div><div class='gd-sec'>すぎる berubah seperti <b>golongan 2 (kata kerja ichidan)</b>. Buang 「る」, lalu sambung yang lain:<br><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎます</span></span><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎた</span></span><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎて</span></span><br>Yang paling sering muncul adalah 「すぎて」, untuk menjelaskan sebab dari hasil di belakangnya:</div><div class='gd-ex-line'>・<span class='gd-jp'>食べすぎて、お腹が痛いです。</span>（Kebanyakan makan, perutku sakit）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は静かすぎて、ちょっとこわいです。</span>（Ruangan ini terlalu sepi, jadi agak menakutkan）</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Jadi kata benda</span>Kata kerja bentuk ます + すぎ, tanpa る di belakangnya, jadi kata benda yang berarti “berlebihan ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>飲みすぎに気をつけてください。</span>（Hati-hati jangan sampai minum berlebihan）</div><div class='gd-sec'><span class='gd-tag'>Minta maaf</span>Sering terdengar setelah bertengkar.</div><div class='gd-ex-line'>・<span class='gd-jp'>さっきは言いすぎました。ごめんなさい。</span>（Tadi aku bicara keterlaluan. Maaf ya）</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・「い」 pada kata sifat い harus dibuang. Yang benar <span class='gd-jp'>高すぎる</span>, bukan 高いすぎる.<br>・Kata sifat な jangan ditambah な. Yang benar <span class='gd-jp'>静かすぎる</span>, bukan 静かなすぎる.<br>・<b>「いい」 harus berubah jadi 「よ」</b>: <span class='gd-jp'>よすぎる</span> (terlalu bagus). Kalau kamu menulis <span class='gd-jp'>いいすぎる</span>, orang Jepang akan mendengarnya sebagai <span class='gd-jp'>言いすぎる</span> (bicara keterlaluan).<br>・「ない (tidak ada)」 harus jadi <span class='gd-jp'>なさすぎる</span>: <span class='gd-jp'>時間がなさすぎる</span> (waktunya terlalu sedikit). Tetapi <span class='gd-jp'>少ない</span> mengikuti aturan biasa, jadi <span class='gd-jp'>少なすぎる</span>.<br>・すぎる biasanya berkesan “kelewatan, kurang baik”. Anak muda memang memakai <span class='gd-jp'>かわいすぎる</span> untuk memuji dalam percakapan santai. Tetapi kalau kamu cuma mau bilang “enak sekali” atau “bagus sekali”, pakai <span class='gd-jp'>とても</span> lebih aman.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Dalam bahasa Indonesia, kata “terlalu” atau “banget” kadang hanya berarti “sangat” (misalnya “bagus banget!”). Karena itu kita gampang menerjemahkan semuanya jadi すぎる. Lihat situasi yang sama:<br><span class='gd-jp'>このかばんはとても高いです。</span>（Tas ini mahal sekali）: hanya menggambarkan bahwa tas itu mahal.<br><span class='gd-jp'>このかばんは高すぎます。</span>（Tas ini kemahalan）: sudah melewati batas yang bisa kamu terima, dan tersirat “aku tidak akan beli”.</div><div class='gd-warn'>Tips menentukan: kalau di belakangnya bisa disambung “jadi tidak bisa” atau “jadi bermasalah”, pakai すぎる. Kalau hanya menyatakan tingkat yang tinggi, pakai とても.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Kalau digabung dengan 「〜ないようにする」, jadilah kalimat favorit dokter: <span class='gd-jp'>飲みすぎないようにしてください。</span>（Usahakan jangan minum berlebihan ya）</div>","n4-6":"<div class='gd-h'>Intinya dalam satu kalimat</div><div class='gd-sec'>「〜方」artinya <b>「cara ～」</b>: cara menulis, cara membaca, cara pakai, cara makan. Sebuah kata kerja diubah jadi “cara melakukan hal itu”. Pola ini sering sekali dipakai saat bertanya “ini cara pakainya bagaimana?” atau “ke sana lewat mana?”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ます, <b>buang ます</b>, lalu tambahkan <b>方（かた）</b>.<br><b>Golongan 1 (kata kerja godan) dan golongan 2 (kata kerja ichidan)</b> caranya sama:<br><span class='gd-pair'><span class='gd-jp'>書きます</span> → buang ます → <span class='gd-jp'>書き方</span></span>（cara menulis）<br><span class='gd-pair'><span class='gd-jp'>読みます</span> → <span class='gd-jp'>読み方</span></span>（cara membaca）<span class='gd-pair'><span class='gd-jp'>使います</span> → <span class='gd-jp'>使い方</span></span>（cara pakai）<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べ方</span></span>（cara makan）<span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見方</span></span>（cara memandang）</div><div class='gd-sec'><b>Golongan 3 (する・来る) harus diingat terpisah</b>：<br>・<span class='gd-jp'>する</span>berubah menjadi <span class='gd-jp'>仕方</span>（しかた）。<br>・Untuk kata kerja berpola 「kata benda＋する」, pakai <b>kata benda＋の＋仕方</b>：<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強の仕方</span></span><span class='gd-pair'><span class='gd-jp'>掃除する</span> → <span class='gd-jp'>掃除の仕方</span></span><br>・<span class='gd-jp'>来る</span>menjadi <span class='gd-jp'>来方</span>（きかた）, tapi yang lebih sering kamu dengar adalah <span class='gd-jp'>行き方</span>。</div><div class='gd-h'>Bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>Menanyakan cara</span>Kamu tidak tahu cara melakukan sesuatu, lalu minta diajari.</div><div class='gd-ex-line'>・<span class='gd-jp'>この漢字の読み方を教えてください。</span>（Tolong beri tahu aku cara membaca kanji ini）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅への行き方がわかりません。</span>（Aku tidak tahu cara ke stasiun）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の勉強の仕方を教えてください。</span>（Tolong ajari aku cara belajar bahasa Jepang）</div><div class='gd-sec'><span class='gd-tag'>Cara seseorang melakukan sesuatu</span>Tidak selalu berarti “metode”. Bisa juga menunjukkan <b>gaya atau kebiasaan</b> seseorang saat melakukan hal itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は話し方がやさしいです。</span>（Cara bicaranya lembut）</div><div class='gd-ex-line'>・<span class='gd-jp'>箸の持ち方がきれいですね。</span>（Cara kamu memegang sumpit rapi sekali ya）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<b>を harus diganti の</b>. 「〜方」sudah menjadi kata benda, jadi di depannya tidak boleh lagi memakai を：<span class='gd-pair'><span class='gd-jp'>本を読む</span> → <span class='gd-jp'>本の読み方</span></span>, bukan 「本を読み方」。<br>・「に／へ」biasanya berubah menjadi 「への」：<span class='gd-pair'><span class='gd-jp'>駅に行く</span> → <span class='gd-jp'>駅への行き方</span></span>。<br>・Karena sudah jadi kata benda, setelahnya bisa diikuti <span class='gd-jp'>が</span>、<span class='gd-jp'>を</span>：<span class='gd-jp'>使い方がわかりません</span>、<span class='gd-jp'>書き方を教えてください</span>。<br>・方 di sini dibaca <b>かた</b>, tidak berubah menjadi がた：<span class='gd-jp'>書き方</span>dibaca かきかた。<br>・Untuk kata kerja seperti 勉強する dan 掃除する, jangan membuat 「勉強し方」 dengan rumus tadi. Katakan <span class='gd-jp'>勉強の仕方</span>。</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Kanji 「方」yang sama dibaca <b>ほう</b> dalam <span class='gd-jp'>〜ほうがいいです</span>, dan artinya benar-benar berbeda.<br><span class='gd-jp'>書き方を教えてください。</span>（Tolong ajari aku cara menulisnya: cara）<br><span class='gd-jp'>名前を書いたほうがいいです。</span>（Sebaiknya tulis namanya: saran）</div><div class='gd-warn'>Trik membedakan: kalau di depannya bentuk ます tanpa ます (書き、読み), dibaca かた = cara ～. Kalau di depannya bentuk た, bentuk ない, atau bentuk kamus (書いた、書かない), dibaca ほう = perbandingan atau saran.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜やすい・〜にくい」juga disambung dengan bentuk ます tanpa ます, jadi sekalian saja diingat: <span class='gd-jp'>このペンは書きやすいです。</span>（Pulpen ini enak dipakai menulis）</div>","n4-9":"<div class='gd-h'>Intinya dalam satu kalimat</div><div class='gd-sec'>「〜ことができます」artinya <b>“bisa ～”, “dapat ～”</b>. Caranya gampang: tambahkan 「こと」pada kata kerja supaya menjadi “hal itu”, lalu katakan “bisa dilakukan (できます)”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kemampuan</span>Kamu sudah belajar dan berlatih, jadi kamu bisa melakukannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は日本語を話すことができます。</span>（Aku bisa berbahasa Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>ピアノを弾くことができます。</span>（Aku bisa main piano）</div><div class='gd-sec'><span class='gd-tag'>Situasi mengizinkan</span>Bukan soal kamu bisa atau tidak, tapi tempat atau aturan itu yang membuatmu boleh melakukannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>この図書館ではWi-Fiを使うことができます。</span>（Di perpustakaan ini kita bisa memakai Wi-Fi）</div><div class='gd-ex-line'>・<span class='gd-jp'>このカードはコンビニでも使うことができます。</span>（Kartu ini bisa dipakai di minimarket juga）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Pakai kata kerja <b>bentuk kamus</b> (bentuk yang kamu temukan di kamus), lalu tambahkan 「ことができます」. Ketiga golongan kata kerja sama saja, tidak perlu perubahan khusus.<br>Kalau kamu hanya ingat bentuk ます, ubah dulu ke bentuk kamus: <span class='gd-pair'><span class='gd-jp'>書きます</span> → <span class='gd-jp'>書く</span> → <span class='gd-jp'>書くことができます</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べることができます</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>することができます</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ることができます</span>（くる）</span></div><div class='gd-sec'>Untuk “tidak bisa”, ganti ます menjadi ません. Untuk “(waktu itu) berhasil”, ganti menjadi ました：<br><span class='gd-jp'>漢字を書くことができません。</span>（Aku tidak bisa menulis kanji）<br><span class='gd-jp'>昨日はゆっくり休むことができました。</span>（Kemarin aku bisa beristirahat dengan tenang）</div><div class='gd-sec'>Kata benda yang menunjukkan <b>keterampilan, olahraga, atau bahasa</b> juga bisa langsung diikuti 「ができます」：<span class='gd-jp'>日本語ができます。</span>（Aku bisa bahasa Jepang）、<span class='gd-jp'>テニスができます。</span>（Aku bisa main tenis）<br>Kata benda biasa tidak bisa begitu. Misalnya, kita tidak bilang 「電車ができます」, tapi <span class='gd-jp'>電車に乗ることができます</span>。</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depannya harus bentuk kamus, tidak boleh langsung bentuk ます: bukan 「行きますことができます」, melainkan <span class='gd-jp'>行くことができます</span>。<br>・「を」yang semula ada tetap dipertahankan: <span class='gd-jp'>ピアノを弾くことができます</span>。Tidak perlu diganti が。<br>・ことができます hanya untuk kemampuan atau izin, bukan untuk ramalan “akan”. “Besok akan hujan” harus dikatakan <span class='gd-jp'>明日は雨が降るでしょう</span>atau <span class='gd-jp'>雨が降るかもしれません</span>。<br>・<span class='gd-jp'>わかる</span>sendiri sudah mengandung arti “mengerti, bisa memahami”, jadi jangan ditambah ことができます: langsung katakan <span class='gd-jp'>日本語がわかります</span>。<br>・Kalau ingin bertanya langsung “Boleh aku ～?” untuk meminta persetujuan lawan bicara, biasanya <span class='gd-jp'>〜てもいいですか</span>terdengar lebih natural.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>Bentuk potensial</b> (話せる、書ける) artinya hampir sama dengan ことができます:<br><span class='gd-jp'>日本語を話すことができます。</span>（Aku bisa berbahasa Jepang: lebih formal dan kaku）<br><span class='gd-jp'>日本語が話せます。</span>（Aku bisa berbahasa Jepang: lebih sering dipakai sehari-hari）<br>ことができます sering terlihat di pengumuman, buku petunjuk, dan perkenalan diri yang formal. Kalau ngobrol dengan teman, biasanya pakai bentuk potensial. Selama kamu belum lancar membentuk bentuk potensial, pakai ことができます pasti aman.</div><div class='gd-sec'><b>〜てもいいです</b>artinya “(aku) mengizinkanmu melakukannya”:<br><span class='gd-jp'>ここで写真を撮ることができます。</span>（Di sini kita bisa foto: menjelaskan aturan atau keadaan）<br><span class='gd-jp'>ここで写真を撮ってもいいですよ。</span>（Kamu boleh foto di sini, lho: pembicara yang memberi izin）</div><div class='gd-warn'>Trik membedakan: untuk “bisa atau tidak bisa” pakai ことができます atau bentuk potensial. Untuk “boleh atau tidak boleh, diizinkan atau tidak” pakai てもいいです。</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Cara yang lebih santai untuk arti yang sama adalah bentuk potensial, misalnya <span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span>。</div>","n4-38":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「AはBほど～ない」artinya <b>「A tidak se～ B」</b> atau <b>「A tidak sebanyak/seperti B」</b>. Urutannya hampir sama dengan bahasa Indonesia: <span class='gd-jp'>京都は東京ほど人が多くない</span>＝Kyoto <b>tidak</b> <b>sepadat</b> Tokyo (orangnya tidak sebanyak Tokyo). <span class='gd-jp'>ほど</span> artinya \"sampai segitu (tingkat itu)\", dan di belakangnya wajib ada bentuk negatif.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>A (yang dibicarakan) は B (pembanding) ほど ＋ bentuk negatif<br>Bentuk negatifnya harus disiapkan dulu:</div><div class='gd-sec'><span class='gd-tag'>Kata sifat-い</span>Ganti 「い」 di akhir dengan 「くない」.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → ganti い jadi くない → <span class='gd-jp'>高くない</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒くない</span></span><br><b>Pengecualian:</b><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくない</span></span> (tidak boleh bilang いくない)</div><div class='gd-ex-line'>・<span class='gd-jp'>この店の料理は前ほどよくない。</span> (Masakan di restoran ini tidak sebagus dulu)</div><div class='gd-sec'><span class='gd-tag'>Kata sifat-な</span>Tambahkan 「じゃない」 di belakangnya; untuk gaya yang lebih formal pakai 「ではない」.<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利じゃない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリは前のほど便利じゃない。</span> (Aplikasi ini tidak sepraktis yang sebelumnya)</div><div class='gd-sec'><span class='gd-tag'>Kata kerja</span>Cukup pakai bentuk ない.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>私は兄ほど食べない。</span> (Aku tidak makan sebanyak kakak laki-lakiku)</div><div class='gd-sec'>Supaya terdengar sopan, tinggal tambahkan です di belakangnya: <span class='gd-pair'><span class='gd-jp'>寒くない</span> → <span class='gd-jp'>寒くないです</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>思ったほど～ない</span>\"Tidak se～ yang dibayangkan\", sangat sering dipakai sehari-hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>テストは思ったほど難しくなかった。</span> (Ujiannya tidak sesulit yang kukira)</div><div class='gd-sec'><span class='gd-tag'>前ほど～ない</span>\"Tidak se～ dulu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>最近は前ほど忙しくないです。</span> (Akhir-akhir ini aku tidak sesibuk dulu)</div><div class='gd-sec'><span class='gd-tag'>それほど～ない</span>B tidak disebutkan, langsung bilang \"tidak begitu～\". Enak dipakai saat menjawab orang lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語、難しい？</span> (Bahasa Jepang itu sulit?)</div><div class='gd-ex-line'>・<span class='gd-jp'>いや、それほど難しくないよ。</span> (Nggak kok, nggak begitu sulit)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Di belakang pola ini <b>selalu negatif</b>. <span class='gd-jp'>京都は東京ほど人が多いです</span> itu salah. Kalau mau bilang \"lebih banyak\", pakai より.<br>・Yang ditaruh sebelum <span class='gd-jp'>ほど</span> adalah <b>pihak yang lebih unggul (lebih tinggi tingkatnya)</b>. <span class='gd-jp'>今日は昨日ほど暑くない</span> artinya kemarin lebih panas, jangan sampai terbalik.<br>・Negatif dari <span class='gd-jp'>いい</span> adalah <span class='gd-jp'>よくない</span>; menulis いくない itu salah.<br>・Nuansanya lebih halus: <span class='gd-jp'>私の部屋は田中さんの部屋ほど広くない</span> (Kamarku tidak seluas kamar Tanaka) terdengar lebih sopan daripada langsung bilang \"lebih sempit\".</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Situasinya sama: kemarin panas sekali, hari ini sedikit lebih sejuk.<br><b>より（～ほうが）</b> = langsung bilang siapa yang \"lebih\" apa, dan bisa dipakai dengan bentuk positif:<br><span class='gd-jp'>昨日より今日のほうが涼しい。</span> (Hari ini lebih sejuk daripada kemarin)<br><span class='gd-jp'>今日は昨日より涼しい。</span> (Hari ini lebih sejuk daripada kemarin)<br><b>ほど～ない</b> = bilang A \"belum sampai tingkat B\", selalu pakai bentuk negatif:<br><span class='gd-jp'>今日は昨日ほど暑くない。</span> (Hari ini tidak sepanas kemarin)</div><div class='gd-warn'>Trik cepat: kalau mau bilang \"lebih ... daripada\", pakai より; kalau mau bilang \"tidak se... itu\", pakai ほど＋negatif.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Setelah membandingkan dua hal, lanjutkan dengan \"yang paling ～ di antara satu kelompok\": <span class='gd-jp'>クラスでいちばん背が高い。</span> (Paling tinggi di kelas)</div>","n4-39":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜でいちばん」artinya <b>「yang paling ～ di antara ～」</b>. Pertama, lingkari dulu cakupannya dengan 「で」 (kelas, Jepang, rumah), lalu bilang \"paling\" dengan 「いちばん」. Seperti bahasa Indonesia \"yang paling tinggi di kelas adalah Tanaka\", dalam bahasa Jepang jadinya <span class='gd-jp'>クラスでいちばん背が高いのは田中さんです</span>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Cakupan＋<b>で</b>＋<b>いちばん</b>＋kata sifat<br><span class='gd-pair'><span class='gd-jp'>高い山</span> → <span class='gd-jp'>日本でいちばん高い山</span></span> (gunung tertinggi di Jepang)</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山は日本でいちばん高い山です。</span> (Gunung Fuji adalah gunung tertinggi di Jepang)</div><div class='gd-ex-line'>・<span class='gd-jp'>クラスで田中さんがいちばん背が高いです。</span> (Di kelas, Tanaka yang paling tinggi)</div><div class='gd-sec'>「いちばん」tidak hanya bisa diikuti kata sifat, tapi juga kata kerja, artinya \"melakukan ～ paling ...\":</div><div class='gd-ex-line'>・<span class='gd-jp'>家族で父がいちばん早く起きます。</span> (Di keluarga, ayahku yang bangun paling pagi)</div><div class='gd-sec'>Kalau cakupannya \"satu kategori benda\" atau kamu sudah menyebutkan beberapa pilihan, biasanya dipakai <b>の中で</b> (di antara ～):</div><div class='gd-ex-line'>・<span class='gd-jp'>スポーツの中で、サッカーがいちばん好きです。</span> (Di antara olahraga, aku paling suka sepak bola)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Bertanya \"mana yang paling ～\"</span>Cakupan＋で＋kata tanya＋が＋いちばん～ですか。Kata tanyanya disesuaikan dengan objeknya: benda pakai <span class='gd-jp'>何</span> (kalau menyebutkan pilihan pakai <span class='gd-jp'>どれ</span>), orang pakai <span class='gd-jp'>だれ</span>, tempat pakai <span class='gd-jp'>どこ</span>, waktu pakai <span class='gd-jp'>いつ</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>一年でいつがいちばん好きですか。</span> (Dalam setahun, kamu paling suka kapan?)</div><div class='gd-ex-line'>・<span class='gd-jp'>夏がいちばん好きです。</span> (Aku paling suka musim panas)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本でどこがいちばんよかったですか。</span> (Di Jepang, menurutmu tempat mana yang paling bagus?)</div><div class='gd-sec'><span class='gd-tag'>「Yang paling ～ adalah X」</span>Taruh jawabannya di bagian akhir, terdengar lebih menekankan:</div><div class='gd-ex-line'>・<span class='gd-jp'>家族でいちばん料理が上手なのは母です。</span> (Yang paling pandai masak di keluarga adalah ibuku)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Cakupan pakai <b>で</b>, bukan に: yang benar <span class='gd-jp'>日本でいちばん</span>, bukan 日本にいちばん.<br>・Dalam kalimat tanya, setelah kata tanya pakai <b>が</b>, bukan は: yang benar <span class='gd-jp'>何がいちばん好きですか</span>, bukan 何はいちばん. Saat menjawab pun biasanya pakai が: <span class='gd-jp'>夏がいちばん好きです</span>.<br>・Objek dari 「好き」「上手」 tetap pakai が: <span class='gd-jp'>料理がいちばん上手です</span>, bukan 料理をいちばん上手.<br>・「いちばん」 sendiri sudah berarti \"paling\", jadi jangan tambahkan とても di depannya.<br>・Kanji <span class='gd-jp'>一番</span> adalah kata yang sama, dan cara bacanya juga sama.</div><div class='gd-h'>Bedakan dengan pola yang mirip</div><div class='gd-sec'>Kuncinya ada pada <b>berapa hal yang dibandingkan</b>. Misalnya sama-sama bertanya minuman favorit:<br><b>Membandingkan dua hal</b> pakai 「どちら」＋「ほうが」 (〜より…ほうが):<br><span class='gd-jp'>コーヒーと紅茶とどちらが好きですか。</span> (Kopi dan teh, kamu lebih suka yang mana?)<br><span class='gd-jp'>コーヒーのほうが好きです。</span> (Aku lebih suka kopi)<br><b>Membandingkan tiga hal atau lebih</b> pakai 「どれ／何」＋「いちばん」:<br><span class='gd-jp'>コーヒーと紅茶とジュースの中で、どれがいちばん好きですか。</span> (Di antara kopi, teh, dan jus, kamu paling suka yang mana?)<br><span class='gd-jp'>コーヒーがいちばん好きです。</span> (Aku paling suka kopi)</div><div class='gd-warn'>Trik cepat: kalau dalam bahasa Indonesia kamu bilang \"lebih ～\", itu perbandingan dua hal, pakai ほうが; kalau bilang \"paling ～\", itu perbandingan tiga hal atau lebih (satu cakupan penuh), pakai いちばん.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「今まで～た中で、いちばん…」＝yang paling ... dari semua yang pernah kulakukan sampai sekarang: <span class='gd-jp'>今まで食べた中で、これがいちばんおいしいです。</span> (Ini yang paling enak dari semua yang pernah kumakan sampai sekarang)</div>","n4-29":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜たばかりです」artinya <b>「baru saja ～」</b>. Kuncinya, si pembicara <b>merasa</b> bahwa「belum lama sejak itu terjadi」. Misalnya kamu bilang ke rekan kerja, 「Saya baru masuk perusahaan」. Padahal mungkin sudah tiga bulan, tapi di hatimu rasanya masih baru, jadi boleh dipakai kalimat ini.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Tambahkan 「ばかりです」setelah <b>bentuk た</b> kata kerja.<br>Bentuk た dibuat sama seperti bentuk て: ganti「て」jadi「た」, dan「で」jadi「だ」.<br><span class='gd-pair'><span class='gd-jp'>入って</span> → <span class='gd-jp'>入った</span> → <span class='gd-jp'>入ったばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span> → <span class='gd-jp'>飲んだばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>来て</span> → <span class='gd-jp'>来た</span>（きた）→ <span class='gd-jp'>来たばかりです</span></span><br>Kalau bicara dengan teman, buang「です」atau ganti dengan「だ」: <span class='gd-jp'>来たばかりだよ。</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Benar-benar baru saja</span>Hal yang terjadi beberapa menit atau beberapa jam lalu.</div><div class='gd-ex-line'>・<span class='gd-jp'>さっきご飯を食べたばかりです。</span>（Aku baru saja selesai makan）</div><div class='gd-sec'><span class='gd-tag'>Di hati rasanya masih baru</span>Sebenarnya sudah berbulan-bulan atau bahkan setahun, tapi kamu merasa belum lama.</div><div class='gd-ex-line'>・<span class='gd-jp'>去年大学を卒業したばかりです。</span>（Aku baru lulus kuliah tahun lalu）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ばかりの＋kata benda</span>「sesuatu yang baru ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>買ったばかりの傘をなくしました。</span>（Aku menghilangkan payung yang baru kubeli）</div><div class='gd-sec'><span class='gd-tag'>ばかりで</span>「Karena baru saja ～, jadi…」, sering dipakai untuk menjelaskan bahwa kamu belum terbiasa.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりで、まだよくわかりません。</span>（Aku baru datang ke Jepang, jadi belum begitu paham）</div><div class='gd-sec'><span class='gd-tag'>ばかりなのに</span>「Padahal baru saja ～」, ada nuansa kesal atau mengeluh.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日洗ったばかりなのに、もう汚れた。</span>（Padahal baru dicuci kemarin, sudah kotor lagi）</div><div class='gd-h'>Hati-hati, bagian ini sering salah</div><div class='gd-warn'>・Kalau diikuti kata benda, tambahkan <b>の</b>: yang benar <span class='gd-jp'>買ったばかりの靴</span>, bukan「買ったばかり靴」.<br>・Harus pakai <b>bentuk た</b>. <span class='gd-jp'>食べたばかり</span> artinya「baru selesai makan」, sedangkan <span class='gd-jp'>食べてばかり</span> artinya「makan terus、cuma makan」. Artinya jauh berbeda.<br>・Hanya untuk hal yang sudah terjadi. Untuk「mau pergi」atau「baru mau dilakukan nanti」tidak bisa dipakai.<br>・Antar teman sering diucapkan jadi <b>ばっか</b>: <span class='gd-jp'>来たばっかだよ。</span>（Aku baru sampai nih）Jangan dipakai ke orang yang lebih tua.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>たところです</b>（n4-28）juga berarti「baru saja ～」, tetapi yang dibicarakan adalah <b>momen yang secara objektif baru saja lewat</b>, biasanya dalam hitungan menit. Sedangkan <b>たばかりです</b> bergantung pada <b>perasaan di hatimu</b>, jadi waktunya bisa pendek bisa panjang.<br>Untuk hal yang sangat baru, keduanya boleh:<br>・<span class='gd-jp'>今、家に着いたところです。</span>（Aku baru sampai di rumah）<br>・<span class='gd-jp'>今、家に着いたばかりです。</span>（Aku baru saja sampai di rumah）<br>Kalau rentang waktunya lebih panjang, hanya ばかり yang bisa dipakai:<br>・<span class='gd-jp'>先月、日本に来たばかりです。</span>（Aku baru datang ke Jepang bulan lalu）○<br>・「先月、日本に来たところです」×</div><div class='gd-warn'>Trik cepat: kalau ada keterangan waktu yang agak lama seperti「先月」「去年」, pakai ばかり. Kalau「baru saja selesai sekarang ini」, ところ juga boleh.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Ada juga「ばかり」yang artinya「cuma ～、terus-terusan ～」, yaitu di n4-49: <span class='gd-jp'>弟はゲームばかりしている。</span>（Adikku main game terus）</div>","n4-37":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「BよりAのほうが～」artinya <b>「Dibandingkan B, A lebih ～」</b>. Kamu menaruh dua hal berdampingan, lalu memilih sisi yang「lebih ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>バスより電車のほうが速いです。</span>（Dibandingkan bus, kereta lebih cepat）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Kata benda</span>Kata benda＋より、kata benda＋<b>の</b>ほうが</div><div class='gd-ex-line'>・<span class='gd-jp'>夏より冬のほうが好きです。</span>（Dibandingkan musim panas, aku lebih suka musim dingin）</div><div class='gd-sec'><span class='gd-tag'>Kata kerja</span>Bentuk kamus＋より、bentuk kamus＋ほうが（di tengah <b>tidak pakai の</b>）</div><div class='gd-ex-line'>・<span class='gd-jp'>外で食べるより、家で作るほうが安いです。</span>（Dibandingkan makan di luar, masak sendiri di rumah lebih murah）</div><div class='gd-sec'>Setelah ほうが bisa dipakai kata sifat, atau ungkapan perasaan seperti <span class='gd-jp'>好きです</span> dan <span class='gd-jp'>落ち着きます</span>.<br>Urutan kedua bagian juga boleh ditukar tanpa mengubah arti, dan intinya tetap ada di sisi ほうが: <span class='gd-jp'>電車のほうがバスより速いです。</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Menjawab「yang mana」</span>Kalau lawan bicara bertanya「AとBと、どちらが～ですか」（Antara A dan B, mana yang lebih ～?）, jawabannya「Aのほうが～です」. Karena kedua hal itu sudah disebut tadi, より biasanya dihilangkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車とバスと、どちらが速いですか。</span>（Antara kereta dan bus, mana yang lebih cepat?）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車のほうが速いです。</span>（Kereta lebih cepat）</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーと紅茶と、どちらがいいですか。</span>（Kopi atau teh, kamu mau yang mana?）</div><div class='gd-ex-line'>・<span class='gd-jp'>紅茶のほうがいいです。</span>（Teh lebih baik）</div><div class='gd-h'>Hati-hati, bagian ini sering salah</div><div class='gd-warn'>・より ditaruh setelah <b>「patokan pembanding」</b>, yaitu sisi yang「kurang ～」; ほうが ditaruh setelah sisi yang「lebih ～」. Jangan berpikir dengan「siapa menang siapa kalah」: <span class='gd-jp'>兄より弟のほうが下手です。</span>（Dibandingkan kakak, adik lebih tidak jago）Di kalimat ini, kakak yang ada setelah より justru orang yang lebih jago.<br>・Dalam bahasa Indonesia kita bilang「lebih cepat daripada bus」, dan「daripada」ada <b>di depan</b> bus. Di bahasa Jepang, より ditaruh <b>setelah</b> バス, jadi ditulis <span class='gd-jp'>バスより</span>.<br>・Kata kerja langsung disambung ke ほうが tanpa の: ×<span class='gd-jp'>歩くのほうが</span>　○<span class='gd-jp'>歩くほうが</span>. の hanya untuk kata benda: <span class='gd-jp'>電車のほうが</span>.<br>・Kanji dari ほう adalah <span class='gd-jp'>方</span>, dan di sini dibaca ほう dengan arti「sisi itu」. Ini berbeda dari <span class='gd-jp'>方</span> pada <span class='gd-jp'>読み方</span> yang dibaca かた dan berarti「cara」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>AはBより～</b>: hanya mendeskripsikan A.<br><span class='gd-jp'>電車はバスより速いです。</span>（Kereta lebih cepat daripada bus）<br><b>BよりAのほうが～</b>: kedua hal disandingkan dan ditekankan「yang ini, sisi A」.<br><span class='gd-jp'>バスより電車のほうが速いです。</span>（Dibandingkan bus, kereta lebih cepat）<br>Artinya hampir sama, tetapi saat menjawab「どちら？」kamu harus pakai <b>ほうが</b>.</div><div class='gd-sec'><b>Kata kerja bentuk た＋ほうがいい</b>: memberi saran,「sebaiknya ～」.<br><span class='gd-jp'>疲れているなら、休んだほうがいいですよ。</span>（Kalau capek, sebaiknya istirahat dulu ya）<br><span class='gd-jp'>タクシーより歩いたほうがいいですよ。</span>（Daripada naik taksi, lebih baik jalan kaki ya）←Ada より, tapi pakai bentuk た, jadi tetap memberi saran<br><b>AよりBのほうがいい</b>: membandingkan, menyatakan preferensi.<br><span class='gd-jp'>コーヒーより紅茶のほうがいいです。</span>（Dibandingkan kopi, teh lebih baik）</div><div class='gd-warn'>Trik cepat: lihat bentuk kata kerjanya.「Kata kerja bentuk た＋ほうがいい」（<span class='gd-jp'>休んだほうがいい</span>）berarti memberi saran. 「Bentuk kamus＋ほうが＋kata sifat」（<span class='gd-jp'>歩くほうが早い</span>）atau「kata benda＋のほうが～」berarti membandingkan. Perhatikan bahwa「AよりBのほうがいいです」juga perbandingan (B lebih baik).</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Untuk sebaliknya,「B tidak sampai se～ A」, pakai「ほど…ない」: <span class='gd-jp'>バスは電車ほど速くないです。</span>（Bus tidak secepat kereta）<br>Untuk membandingkan tiga hal atau lebih dan mengatakan「paling ～」, pakai「でいちばん」: <span class='gd-jp'>クラスで田中さんがいちばん背が高いです。</span>（Di kelas, Tanaka yang paling tinggi）</div>","n4-26":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜てくる」dan「〜ていく」mirip dengan pasangan <b>“~ke sini” dan “~ke sana / terus ~”</b> dalam bahasa Indonesia. “Berlari ke sini” adalah <span class='gd-jp'>走ってくる</span>, “membawa ke sana” adalah <span class='gd-jp'>持っていく</span>. Untuk waktu juga sama: “jadi dingin” (perubahan sampai sekarang) pakai てくる, “terus melakukannya ke depannya” pakai ていく.<br>Ingat satu kalimat ini dulu: <b>くる＝mendekat ke arahku, berlangsung sampai sekarang; いく＝menjauh dariku, dari sekarang ke depan</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk て dulu, lalu sambungkan くる atau いく.<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降って</span> → <span class='gd-jp'>降ってきた</span></span><br><span class='gd-pair'><span class='gd-jp'>持つ</span> → <span class='gd-jp'>持って</span> → <span class='gd-jp'>持っていきます</span></span><br>くる di belakang berubah seperti「来る」biasa: <span class='gd-jp'>てきます</span>、<span class='gd-jp'>てきました</span>、<span class='gd-jp'>てこない</span>. Dalam pola ini biasanya langsung ditulis dengan hiragana.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Ke sini／ke sana</span>Kalau gerakannya mendekati si pembicara, pakai てくる. Kalau menjauhi si pembicara, pakai ていく.</div><div class='gd-ex-line'>・<span class='gd-jp'>弟が走ってきた。</span>（Adikku berlari ke sini）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていきます。</span>（Kelihatannya mau hujan, jadi aku bawa payung）</div><div class='gd-sec'><span class='gd-tag'>Pergi sebentar lalu kembali</span>てくる juga bisa berarti “pergi melakukan sesuatu, lalu kembali ke sini”.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと飲み物を買ってきます。</span>（Aku beli minuman sebentar ya, nanti balik lagi）</div><div class='gd-sec'><span class='gd-tag'>Berubah sampai sekarang</span>Perubahan yang pelan-pelan terjadi dari dulu sampai sekarang, biasanya pakai bentuk lampau <span class='gd-jp'>てきました</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、日本語が面白くなってきました。</span>（Akhir-akhir ini aku merasa bahasa Jepang makin seru）</div><div class='gd-sec'><span class='gd-tag'>Dari sekarang ke depan</span>Berlanjut mulai dari sekarang, atau makin lama makin ~.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語を勉強していきます。</span>（Ke depannya aku juga akan terus belajar bahasa Jepang）</div><div class='gd-sec'><span class='gd-tag'>Tiba-tiba muncul, terasa</span>Suatu perubahan mulai muncul dan kamu menyadarinya, misalnya hujan turun, perut lapar, atau mengantuk.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降ってきた。</span>（Ah, hujan mulai turun）</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がすいてきた。</span>（Perutku mulai lapar）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<span class='gd-jp'>行ってきます</span> yang diucapkan saat keluar rumah artinya “pergi lalu akan kembali”. Jadi maknanya “aku berangkat dulu ya”, bukan sekadar “aku pergi”.<br>・Datang atau pergi tergantung <b>di mana si pembicara berada</b>. Kalau kamu membawa sesuatu ke rumah lawan bicara, dalam bahasa Indonesia kamu mungkin bilang “nanti kubawa ke sana”, dan bahasa Jepang biasanya <span class='gd-jp'>持っていきます</span>, karena barangnya menjauh dari tempatmu. Hati-hati kalau kamu terbiasa bilang “kubawa ke sini” dari sudut pandang lawan bicara.<br>・<span class='gd-jp'>雨が降ってきた</span> artinya “hujan mulai turun”, bukan “hujan melayang ke arahku”.<br>・「きた」di <span class='gd-jp'>てきた</span> dibaca きた, dan bentuk negatif <span class='gd-jp'>てこない</span> dibaca こない.<br>・Saat ngobrol, <span class='gd-jp'>ていく</span> sering dipersingkat jadi <span class='gd-jp'>てく</span>, misalnya <span class='gd-jp'>持ってく</span>. Ini bahasa lisan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama bilang cuaca jadi dingin:<br>・<span class='gd-jp'>寒くなった。</span>（Sudah jadi dingin: hanya menyebut hasilnya）<br>・<span class='gd-jp'>寒くなってきた。</span>（Pelan-pelan jadi dingin: terasa ada perubahan yang berlangsung）<br>・<span class='gd-jp'>これから寒くなっていく。</span>（Mulai sekarang akan makin dingin: melihat ke depan）<br><br>Sama-sama bilang hujan mulai turun:<br>・<span class='gd-jp'>雨が降り始めた。</span>（Hujan mulai turun: sekadar menyebut awal mulanya）<br>・<span class='gd-jp'>雨が降ってきた。</span>（Hujan turun nih: ada rasa “aku baru sadar”, paling sering dipakai saat kamu mendongak dan melihat hujan）</div><div class='gd-warn'>Trik menilai: kalau hanya menyebut hasil, pakai「なった」; kalau terasa “berubah sampai sekarang”, pakai「てきた」; kalau pandangannya ke “setelah ini”, pakai「ていく」.</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Digabung dengan「ようになる」, kamu bisa bilang kemampuan yang terbentuk pelan-pelan: <span class='gd-jp'>日本語が少し話せるようになってきた。</span>（Aku mulai bisa bicara sedikit bahasa Jepang）</div>","n4-27":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Ketiganya seperti <b>“mulai ~”, “terus ~”, “selesai ~”</b> dalam bahasa Indonesia. Satu aksi dipotong jadi tiga tahap: baru mulai, sedang berlangsung, sudah selesai.<br><span class='gd-jp'>読みはじめる</span>＝mulai membaca<br><span class='gd-jp'>読み続ける</span>＝terus membaca<br><span class='gd-jp'>読み終わる</span>＝selesai membaca</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ます dulu, <b>buang ます</b>, lalu tempelkan langsung <span class='gd-jp'>はじめる</span>、<span class='gd-jp'>続ける</span> atau <span class='gd-jp'>終わる</span> pada bagian yang tersisa.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読みます</span></span> → buang ます → <span class='gd-pair'><span class='gd-jp'>読み</span> → <span class='gd-jp'>読みはじめる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span> → buang ます → <span class='gd-pair'><span class='gd-jp'>食べ</span> → <span class='gd-jp'>食べ続ける</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span> → buang ます → <span class='gd-pair'><span class='gd-jp'>勉強し</span> → <span class='gd-jp'>勉強し終わる</span></span></div><div class='gd-sec'>Setelah menempel, kata di belakang berubah sesuai aturannya sendiri:<br><span class='gd-jp'>はじめる</span> dan <span class='gd-jp'>続ける</span> termasuk Kelompok 2 (kata kerja ichidan): <span class='gd-pair'><span class='gd-jp'>読みはじめる</span> → <span class='gd-jp'>読みはじめました</span></span><br><span class='gd-jp'>終わる</span> termasuk Kelompok 1 (kata kerja godan): <span class='gd-pair'><span class='gd-jp'>読み終わる</span> → <span class='gd-jp'>読み終わりました</span></span><br>「はじめる」boleh ditulis dengan kanji <span class='gd-jp'>始める</span>, tapi kalau menempel di belakang kata kerja, biasanya ditulis hiragana.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>はじめる：mulai</span>Sebuah aksi dimulai sejak saat ini. Bisa untuk perbuatan orang maupun perubahan alam seperti cuaca.</div><div class='gd-ex-line'>・<span class='gd-jp'>去年から日本語を勉強しはじめました。</span>（Aku mulai belajar bahasa Jepang sejak tahun lalu）</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降りはじめた。</span>（Ah, hujan mulai turun）</div><div class='gd-sec'><span class='gd-tag'>続ける：terus, melanjutkan</span>Aksinya tidak berhenti, terus dilakukan. Sering muncul bersama「ずっと」atau durasi waktu.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は1時間も話し続けた。</span>（Dia bicara terus sampai satu jam penuh）</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語を勉強し続けたいです。</span>（Ke depannya aku juga ingin terus belajar bahasa Jepang）</div><div class='gd-sec'><span class='gd-tag'>終わる：selesai</span>Sesuatu yang punya titik akhir sudah sampai ke akhirnya, misalnya selesai membaca buku atau selesai makan.</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、やっと読み終わった。</span>（Buku ini akhirnya selesai kubaca）</div><div class='gd-ex-line'>・<span class='gd-jp'>食べ終わったら、お皿を洗ってね。</span>（Kalau sudah selesai makan, cuci piringnya ya）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Harus disambung dengan <b>bentuk ます yang ます-nya dibuang</b>. <span class='gd-jp'>読むはじめる</span> dan <span class='gd-jp'>読んではじめる</span> keduanya salah, yang benar <span class='gd-jp'>読みはじめる</span>.<br>・Meskipun subjeknya fenomena alam seperti hujan atau angin, tetap pakai <span class='gd-jp'>はじめる</span>: <span class='gd-jp'>雨が降りはじめた</span>, bukan「降りはじまった」.<br>・<span class='gd-jp'>終わる</span> dipakai untuk aksi yang punya titik “selesai”, seperti membaca, makan, menulis, atau menonton. Untuk hujan yang berhenti, jangan bilang「降り終わった」, tapi <span class='gd-jp'>雨がやんだ</span>.<br>・<span class='gd-jp'>終わる</span> Kelompok 1, bentuk ます-nya <span class='gd-jp'>終わります</span>; <span class='gd-jp'>はじめる</span> dan <span class='gd-jp'>続ける</span> Kelompok 2, yaitu <span class='gd-jp'>はじめます</span> dan <span class='gd-jp'>続けます</span>. Jangan dicampur aturan perubahannya.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜ている dan 〜続けている</b><br><span class='gd-jp'>子どもが泣いている。</span>（Anak itu sedang menangis）: hanya menggambarkan kondisi sekarang yang sedang menangis.<br><span class='gd-jp'>子どもがずっと泣き続けている。</span>（Anak itu menangis terus tanpa henti）: menekankan sudah lama menangis dan belum berhenti.</div><div class='gd-sec'><b>〜終わる dan 〜てしまう</b><br>Dalam bahasa Indonesia keduanya bisa jadi “sudah habis dimakan”, tapi titik beratnya beda.<br><span class='gd-jp'>ケーキを食べ終わった。</span>（Kuenya sudah selesai dimakan）: hanya bilang aksi makannya sudah selesai, nadanya netral.<br><span class='gd-jp'>弟のケーキを食べてしまった。</span>（Aku telanjur memakan kue adikku）: ada kesan “habis semua” atau “aduh, tidak sengaja”.</div><div class='gd-warn'>Trik menilai: kalau hanya bilang “sedang melakukan”, pakai ている; kalau ingin menekankan “terus tanpa berhenti”, pakai 続ける; kalau sekadar bilang “sudah selesai”, pakai 終わる; kalau ada perasaan “habis semua” atau “aduh”, pakai てしまう.</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Kalau mau bilang titik waktu yang lebih rinci, seperti “baru mau mulai”, “sedang melakukan”, atau “baru saja selesai”, lanjut belajar <span class='gd-jp'>〜ところです</span>: <span class='gd-jp'>今から食べるところです。</span>（Aku baru mau mulai makan）</div>","n4-40":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜と言います」artinya <b>“Si A bilang ~”</b>. <span class='gd-jp'>言う</span> berarti “berkata”, dan <span class='gd-jp'>と</span> di depannya adalah penanda yang memberi tahu lawan bicara bahwa “isi ucapan berhenti di sini”. Fungsinya mirip tanda kutip dalam bahasa Indonesia.</div><div class='gd-h'>Dua cara: kutip langsung dan sampaikan dengan kata-katamu sendiri</div><div class='gd-sec'><span class='gd-tag'>Kutip langsung</span>Masukkan ucapan lawan bicara ke dalam 「」 tanpa mengubah satu huruf pun, lalu tambahkan <span class='gd-jp'>と言いました</span> di belakangnya. Kalau ucapan aslinya pakai ます, biarkan ます-nya.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は「明日テストをします」と言いました。</span>(Guru bilang, “Besok ada ujian.”)</div><div class='gd-sec'><span class='gd-tag'>Sampaikan dengan kata-katamu sendiri</span>Tanpa 「」, ubah isinya ke <b>bentuk biasa</b> (bentuk tanpa ます/です, seperti cara bicara dengan teman), lalu sambung dengan <span class='gd-jp'>と</span>.<br><span class='gd-pair'><span class='gd-jp'>テストをします</span> → <span class='gd-jp'>テストをする</span></span><br><span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>先生は明日テストをすると言いました。</span>(Guru bilang besok ada ujian)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は行かないと言いました。</span>(Dia bilang dia tidak pergi)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Saat menyampaikan ucapan orang lain, kata kerja dan kata sifat-い langsung dipakai dalam bentuk biasa lalu disambung <span class='gd-jp'>と</span>; <b>nomina dan kata sifat-な harus ditambah “だ”</b>.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いと言いました</span></span><br><span class='gd-pair'><span class='gd-jp'>好きです</span> → <span class='gd-jp'>好きだと言いました</span></span><br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だと言いました</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>と言っていました</span>Paling natural untuk menyampaikan pesan orang lain. Artinya “Dia (tadi) bilang ~ lho”.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは今日は来ないと言っていました。</span>(Pak Tanaka bilang hari ini dia tidak datang)</div><div class='gd-sec'><span class='gd-tag'>Perkenalan diri</span>Untuk menyebutkan namamu.</div><div class='gd-ex-line'>・<span class='gd-jp'>はじめまして、林と言います。</span>(Salam kenal, nama saya Hayashi)</div><div class='gd-sec'><span class='gd-tag'>Menanyakan cara mengatakan</span>Pasti kepakai saat belajar bahasa Jepang.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは日本語で何と言いますか。</span>(Ini bahasa Jepangnya apa?)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Untuk mengutip <b>isi</b> ucapan (satu kalimat atau satu bagian pembicaraan), pakai <b>と</b>, bukan を: × <span class='gd-jp'>明日テストをするを言いました</span> → ○ <span class='gd-jp'>明日テストをすると言いました</span>. Tapi kalau yang ada di depannya nomina, seperti <span class='gd-jp'>名前を言う</span> (menyebutkan nama) atau <span class='gd-jp'>お礼を言う</span> (mengucapkan terima kasih), pakai を. Bedakan dua pola ini ya.<br>・<span class='gd-jp'>言う</span> memang ditulis いう, tapi dalam praktiknya dibaca <b>ゆう</b>.<br>・Kesalahan paling umum: lupa menambah だ pada nomina dan kata sifat-な saat menyampaikan ucapan. Yang benar: <span class='gd-jp'>雨だと言っていました</span>.<br>・Saat menyampaikan ucapan orang, “saya” harus diganti orangnya: kalau ucapan aslinya 「<span class='gd-jp'>私は行きません</span>」, dalam versimu jadi “dia bilang <b>dia</b> tidak pergi”. Dalam bahasa Jepang cukup bilang <span class='gd-jp'>彼は行かないと言いました</span>, tidak perlu memasukkan 「私」 lagi.<br>・Untuk ucapan guru atau atasan, dalam situasi formal kata ini diganti menjadi <span class='gd-jp'>おっしゃいました</span> yang lebih hormat. Kamu akan menemuinya nanti saat belajar bahasa hormat (尊敬語).</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama menyampaikan “Pak Tanaka tidak datang”:<br><span class='gd-jp'>田中さんは来ないと言っていました。</span>(Pak Tanaka <b>sendiri yang bilang</b> dia tidak datang)<br><span class='gd-jp'>田中さんは来ないそうです。</span>(<b>Katanya</b> Pak Tanaka tidak datang)<br>「と言う」 dengan jelas menyebut <b>siapa yang berbicara</b>; 「そうです」 hanya “katanya”. Kabarnya bisa saja dari Pak Tanaka sendiri atau dari orang lain, karena yang ditekankan bukan siapa yang bilang.</div><div class='gd-warn'>Trik membedakan: kalau mau bilang “Si A bilang ~” pakai と言う; kalau cuma mau bilang “katanya ~” pakai そうです.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau <span class='gd-jp'>言います</span> diganti <span class='gd-jp'>思います</span>, artinya “menurutku ~”: <span class='gd-jp'>明日は雨だと思います。</span> (Kurasa besok hujan). Cara menyambungnya sama persis, dan juga perlu ditambah だ.<br>Dalam obrolan antarteman, <span class='gd-jp'>と言っていた</span> sering dipersingkat jadi <span class='gd-jp'>って</span>: <span class='gd-jp'>田中さん、来ないって。</span> (Tanaka bilang dia nggak datang, lho)</div>","n4-41":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜と思います」artinya <b>“Menurutku ~” / “Kurasa ~”</b>. Dipakai untuk menyampaikan pendapatmu sendiri atau menebak bagaimana suatu hal akan terjadi. Orang Jepang suka sekali memakainya; bahkan saat sangat yakin pun mereka sering menambahkan と思います supaya ucapannya tidak terdengar terlalu tegas.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyampaikan pendapat</span>Kesan atau penilaian terhadap sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしいと思います。</span>(Menurutku ramen ini enak)</div><div class='gd-sec'><span class='gd-tag'>Menebak</span>Tidak 100% pasti, tapi kamu merasa kemungkinan besar begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>(Kurasa besok akan hujan)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったと思います。</span>(Kurasa Pak Tanaka sudah pulang)</div><div class='gd-sec'><span class='gd-tag'>Menanyakan pendapat lawan bicara</span>Pakai 「どう思いますか」, tidak perlu menghafal pola lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>この服、どう思いますか。</span>(Menurutmu baju ini bagaimana?)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya taruh <b>bentuk biasa</b>, yaitu bentuk tanpa です/ます (bentuk kamus, ない, た, dan sebagainya).<br>Kata kerja dan kata sifat-い langsung disambung:<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くと思います</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないと思います</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いと思います</span></span><br>Nomina dan kata sifat-な <b>tambahkan だ dulu</b>:<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生だと思います</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだと思います</span></span><br>Saat bicara dengan teman, ganti 思います menjadi <b>思う</b>: <span class='gd-jp'>おいしいと思う。</span></div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Lupa menambah だ pada nomina dan kata sifat-な: yang benar <span class='gd-jp'>学生だと思います</span>, bukan 「学生と思います」.<br>・Jangan taruh です/ます sebelum と: yang benar <span class='gd-jp'>おいしいと思います</span>, bukan 「おいしいですと思います」. Tingkat kesopanannya sudah cukup lewat 「思います」 di akhir.<br>・Untuk “Kurasa dia tidak akan datang”, bahasa Jepang meletakkan bentuk negatif di dalam klausa sebelum と, mirip dengan bahasa Indonesia: <span class='gd-jp'>彼は来ないと思います。</span> Kalau bilang <span class='gd-jp'>来るとは思いません</span>, artinya “Aku sama sekali tidak mengira dia akan datang”, nadanya jauh lebih kuat, seperti sedang membantah.<br>・「と思います」 hanya dipakai untuk apa yang <b>kamu</b> pikirkan sendiri. Untuk apa yang dipikirkan orang lain, pakai 「と思っています」: <span class='gd-jp'>母は私がまだ子どもだと思っています。</span> (Ibuku mengira aku masih anak-anak)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>行くと思います vs 行こうと思います</b>: bedanya cuma sedikit, tapi artinya jauh berbeda.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のパーティー、田中さんは行くと思います。</span>(Soal pesta besok, kurasa Pak Tanaka akan datang)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のパーティー、私も行こうと思います。</span>(Soal pesta besok, aku juga berencana datang)</div><div class='gd-sec'>Di depannya bentuk biasa = <b>menebak</b> apa yang akan terjadi; di depannya bentuk ajakan/niat (行こう, 食べよう) = <b>aku berencana</b> melakukannya.</div><div class='gd-sec'><b>と思います vs かもしれません</b>: tingkat keyakinannya berbeda.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>(Kurasa besok akan hujan: cukup yakin)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るかもしれません。</span>(Besok mungkin hujan: fifty-fifty)</div><div class='gd-warn'>Trik membedakan: “menurutku / kurasa” pakai bentuk biasa + と思います; “aku berencana” pakai bentuk niat + と思います; kalau cuma “mungkin saja” pakai かもしれません.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau bagian depannya diganti bentuk niat (意向形), artinya “aku berencana ~”: <span class='gd-jp'>来年、日本へ行こうと思います。</span> (Aku berencana pergi ke Jepang tahun depan)</div>","n4-42":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ようと思います」artinya <b>“Aku berencana～” atau “Aku kepikiran mau～”</b>. Pola ini dipakai untuk memberi tahu orang lain rencana yang sudah ada di kepalamu, misalnya “Akhir pekan ini aku berencana membersihkan kamar”.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は部屋を掃除しようと思います。</span>（Aku berencana membersihkan kamar akhir pekan ini）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke <b>bentuk volisional (意向形)</b>, yaitu bentuk 「〜よう」「〜こう」 yang artinya “ayo～”. Lalu tambahkan <span class='gd-jp'>と思います</span> di belakangnya. Cara membentuknya ada di n4-51, ini ulasan singkatnya:<br><b>Golongan 1 (kata kerja godan)</b>：<span class='gd-pair'><span class='gd-jp'>行く</span> → ganti く menjadi こ, lalu tambah う → <span class='gd-jp'>行こうと思います</span></span><br><b>Golongan 2 (kata kerja ichidan)</b>：<span class='gd-pair'><span class='gd-jp'>寝る</span> → buang る, lalu tambah よう → <span class='gd-jp'>寝ようと思います</span></span><br><b>Golongan 3 (する・来る)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようと思います</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようと思います</span>（こよう）</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ようと思います</span>Dipakai untuk menyatakan rencanamu saat ini, sering kali baru saja terpikir.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝ようと思います。</span>（Hari ini aku berencana tidur lebih awal）</div><div class='gd-sec'><span class='gd-tag'>ようと思っています</span>Rencana ini <b>sudah lama ada di hatimu</b>. Bentuk ini sering dipakai untuk rencana jangka panjang.</div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本へ留学しようと思っています。</span>（Aku berencana kuliah di Jepang tahun depan）</div><div class='gd-sec'><span class='gd-tag'>ようかと思っています</span>Ada tambahan 「か」 di tengah, jadi artinya berubah menjadi <b>“Aku lagi mikir, sebaiknya～ atau tidak ya”</b>. Kamu masih ragu-ragu.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事を辞めようかと思っています。</span>（Aku lagi mikir, sebaiknya berhenti kerja atau tidak ya）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>行くと思います</span> dan <span class='gd-jp'>行こうと思います</span> cuma beda sedikit, tapi artinya jauh berbeda. Yang pertama artinya “Kurasa (dia) akan pergi”, itu tebakan. Yang kedua baru artinya “Aku berencana pergi”.<br>・“Aku <b>tidak</b> berencana pergi” tidak bisa dibilang <span class='gd-jp'>行かないと思います</span>, karena itu artinya “Kurasa dia tidak akan pergi”. Untuk “tidak berencana”, pakai <span class='gd-jp'>行かないつもりです</span>.<br>・<span class='gd-jp'>〜ようと思います</span> hanya bisa dipakai untuk rencana <b>dirimu sendiri</b>. Untuk rencana orang lain, ganti dengan <span class='gd-jp'>〜ようと思っています</span>：<span class='gd-jp'>兄は車を買おうと思っています。</span>（Kakakku berencana membeli mobil）<br>・Saat menanyakan rencana lawan bicara, <span class='gd-jp'>思っています</span> terdengar lebih natural：<span class='gd-jp'>夏休みは何をしようと思っていますか。</span>（Kamu berencana ngapain di liburan musim panas?）</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Untuk “pergi ke Jepang”, ketiga cara bilang ini terasa berbeda:<br><b>たい</b> = sekadar “ingin”, itu keinginan di hati dan belum tentu ada rencananya：<span class='gd-jp'>日本へ行きたいです。</span>（Aku ingin pergi ke Jepang）<br><b>ようと思う</b> = “berencana”. Niatnya sudah ada, tapi nadanya lebih lunak dan masih fleksibel：<span class='gd-jp'>日本へ行こうと思います。</span>（Aku berencana pergi ke Jepang）<br><b>つもり</b> = rencananya lebih pasti, hampir sudah diputuskan：<span class='gd-jp'>日本へ行くつもりです。</span>（Aku bermaksud pergi ke Jepang）</div><div class='gd-warn'>Trik cepat: kalau cuma “pengen banget～”, pakai たい. Kalau “berencana～”, pakai ようと思う. Kalau “sudah merencanakan～”, pakai つもり. Dalam bahasa Indonesia, “aku mau pergi” bisa berarti keinginan atau rencana, jadi pikirkan dulu mana yang kamu maksud.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kalau rencananya sudah benar-benar diputuskan, kamu bisa pakai 「〜ことにします」：<span class='gd-jp'>来年、日本へ行くことにしました。</span>（Aku memutuskan pergi ke Jepang tahun depan）</div>","n4-43":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜か（どうか）」adalah cara <b>menyelipkan satu pertanyaan ke dalam kalimat</b>. Dalam bahasa Indonesia kita bilang “Aku tidak tahu <b>apakah dia akan datang</b>”. Bagian di tengah itu sebenarnya pertanyaan, hanya saja tidak ditanyakan secara terpisah. Dalam bahasa Jepang, kamu menambahkan 「か」 atau 「かどうか」 setelah bagian itu untuk memberi tanda bahwa di sini ada sebuah pertanyaan.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が来るかどうか、分かりません。</span>（Aku tidak tahu apakah dia akan datang）</div><div class='gd-h'>Pisahkan dulu menjadi dua jenis: ada atau tidak kata seperti “siapa, di mana, apa”</div><div class='gd-sec'><span class='gd-tag'>Tanpa kata tanya</span>Kalau jawaban pertanyaannya hanya “ya / tidak”, pakai <b>かどうか</b>. Artinya sama dengan “apakah～ atau tidak”. Cukup 「か」 saja juga boleh, dan dalam percakapan sering begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>鍵をかけたかどうか、覚えていない。</span>（Aku tidak ingat apakah tadi sudah mengunci pintu）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末に時間があるか、確認してください。</span>（Tolong pastikan apakah kamu punya waktu luang akhir pekan）</div><div class='gd-sec'><span class='gd-tag'>Dengan kata tanya</span>Kalau di dalam kalimat sudah ada kata seperti <span class='gd-jp'>誰</span>、<span class='gd-jp'>どこ</span>、<span class='gd-jp'>何</span>、<span class='gd-jp'>いつ</span>, <b>tambahkan 「か」 saja</b>, tanpa どうか.</div><div class='gd-ex-line'>・<span class='gd-jp'>会議が何時に始まるか、知っていますか。</span>（Kamu tahu rapatnya mulai jam berapa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレがどこか、教えてください。</span>（Tolong beri tahu aku di mana toiletnya）</div><div class='gd-sec'>Kata kerja yang paling sering muncul setelahnya: <span class='gd-jp'>分からない</span>、<span class='gd-jp'>知っている</span>、<span class='gd-jp'>決まる</span>、<span class='gd-jp'>確認する</span>、<span class='gd-jp'>聞く</span>、<span class='gd-jp'>考える</span>、<span class='gd-jp'>覚えている</span>. Semuanya bermakna seperti “tahu, memastikan, memutuskan”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bagian depannya selalu memakai <b>bentuk biasa (普通形)</b>, yaitu bentuk tanpa ます atau です.<br>Kata kerja：<span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行くかどうか</span></span><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行ったかどうか</span></span><br>Kata sifat-い：<span class='gd-pair'><span class='gd-jp'>おいしいです</span> → <span class='gd-jp'>おいしいかどうか</span></span><br>Kata benda dan kata sifat-な：<b>tanpa だ</b>, langsung sambung か.<span class='gd-pair'><span class='gd-jp'>本当です</span> → <span class='gd-jp'>本当かどうか</span></span><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かかどうか</span></span><br>Kamu juga bisa bilang 「<span class='gd-jp'>来るか来ないか</span>」, artinya sama dengan <span class='gd-jp'>来るかどうか</span>.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Dalam bahasa Indonesia kita kadang bisa bilang “Aku tidak tahu dia datang” tanpa “apakah”, tapi dalam bahasa Jepang <b>か wajib ada</b>. <span class='gd-jp'>彼が来る分かりません</span> itu salah.<br>・Walaupun seluruh kalimat ingin dibuat sopan, bagian tengahnya tetap bentuk biasa. Kesopanan cukup ditaruh di akhir kalimat: bilang <span class='gd-jp'>行くかどうか分かりません</span>, jangan 「行きますかどうか」.<br>・Setelah kata benda atau kata sifat-な, jangan tambah だ: bilang <span class='gd-jp'>学生かどうか</span>, jangan 「学生だかどうか」.<br>・Kalau sudah ada kata tanya, jangan tambah どうか lagi: bilang <span class='gd-jp'>どこがいいか</span>, jangan 「どこがいいかどうか」.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama memakai 「か」 dan sama-sama mengandung ketidakpastian, jadi pemula sering mencampurnya dengan <b>かもしれない</b>.<br><span class='gd-jp'>彼は来るかどうか分からない。</span>（Tidak tahu apakah dia akan datang: kamu sama sekali tidak tahu, hanya bilang “soal ini aku tidak jelas”）<br><span class='gd-jp'>彼は来るかもしれない。</span>（Dia mungkin datang: kamu sedang menebak dan merasa ada kemungkinan dia datang）</div><div class='gd-warn'>Trik cepat: kalau di belakangnya masih ada kata kerja seperti 「分からない、確認する、教えて」, itu かどうか. Kalau kalimatnya berhenti di situ dan artinya “mungkin～”, itu かもしれない.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Pola ini enak dipakai bersama 「〜てみます」：<span class='gd-jp'>行けるかどうか、先生に聞いてみます。</span>（Aku coba tanya guru apakah aku bisa pergi）</div>","n4-49":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ばかり」artinya <b>「melulu」「terus-terusan」「isinya cuma ～」</b>. Bayangkan ibu yang menegur anaknya, \"Kerjaanmu main game melulu!\" Nah, dalam bahasa Jepang kamu pakai ばかり. Intinya: si pembicara merasa <b>itu terlalu banyak dan kurang baik</b>, jadi nadanya sering terdengar mengeluh atau menegur.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Tindakannya terlalu sering</span>Kata kerja bentuk て＋ばかりいる: menekankan \"dari tadi cuma melakukan ini, yang lain tidak dikerjakan\".<br><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span> → <span class='gd-jp'>遊んでばかりいる</span></span>(main terus)<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝て</span> → <span class='gd-jp'>寝てばかりいる</span></span>(tidur terus)</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの犬は一日中寝てばかりいる。</span>(Anjing di rumahku tidur terus seharian)</div><div class='gd-sec'><span class='gd-tag'>Objeknya itu-itu saja</span>Kata benda＋ばかり＋kata kerja: menekankan \"yang dilakukan hanya hal ini\".</div><div class='gd-ex-line'>・<span class='gd-jp'>弟はゲームばかりしている。</span>(Adikku main game melulu seharian)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はいつも文句ばかり言っている。</span>(Dia selalu mengeluh melulu)</div><div class='gd-sec'>Setelah kata benda, kamu juga bisa langsung menambahkan「です／だ」untuk menggambarkan \"ke mana pun melihat isinya ～ semua\":</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、雨ばかりですね。</span>(Akhir-akhir ini hujan terus ya)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Menegur orang</span>「〜てばかりいないで」＝jangan ～ terus. Di belakangnya sering muncul <span class='gd-jp'>〜なさい</span>, dialog klasik orang tua dan guru.</div><div class='gd-ex-line'>・<span class='gd-jp'>遊んでばかりいないで、勉強しなさい。</span>(Jangan main terus, belajar sana)</div><div class='gd-ex-line'>・<span class='gd-jp'>泣いてばかりいないで、話してよ。</span>(Jangan menangis terus, ceritalah padaku)</div><div class='gd-sec'><span class='gd-tag'>Menyindir diri sendiri</span>Boleh juga dipakai untuk diri sendiri, dengan nuansa \"duh, kok aku begini terus ya\".</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、食べてばかりいる。</span>(Akhir-akhir ini aku makan terus)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Saat kata benda ditambah ばかり, 「を」yang semula ada biasanya dihilangkan: katakan <span class='gd-jp'>漫画ばかり読む</span>, jangan 「漫画をばかり読む」.<br>・Yang dibicarakan adalah keadaan yang <b>terus berulang dalam satu periode</b>, jadi tidak bisa dipakai untuk kejadian yang hanya terjadi sekali.<br>・Nadanya mengkritik, jadi sangat tidak sopan kalau dipakai untuk guru, atasan, atau tamu. Hati-hati ya.<br>・Dalam obrolan dengan teman, sering diucapkan jadi <span class='gd-jp'>ばっかり</span>, misalnya <span class='gd-jp'>遊んでばっかり</span>. Artinya sama, hanya lebih kasual.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'><b>たばかり</b>(n4-29) ＝ <b>baru saja</b> selesai melakukan sesuatu, tidak ada hubungannya dengan frekuensi:<br><span class='gd-jp'>ご飯を食べたばかりです。</span>(Aku baru saja selesai makan)<br><b>てばかりいる</b> ＝ <b>terus-terusan</b> melakukan sesuatu:<br><span class='gd-jp'>お菓子を食べてばかりいる。</span>(Makan camilan terus)</div><div class='gd-sec'><b>だけ</b> ＝ <b>hanya</b> ini, sekadar menyatakan fakta tanpa rasa tidak puas:<br><span class='gd-jp'>朝はコーヒーだけ飲みました。</span>(Pagi tadi aku hanya minum kopi)<br><b>ばかり</b> ＝ <b>terus-terusan, terlalu banyak</b>, dengan nada mengeluh:<br><span class='gd-jp'>コーヒーばかり飲んでいる。</span>(Minum kopi melulu)</div><div class='gd-warn'>Trik cepat: kalau di depannya 「た」, artinya \"baru saja\"; kalau di depannya 「て」, artinya \"terus-terusan\". Kalau cuma bilang \"hanya ini\", pakai だけ; kalau mau menegur \"kok ini terus sih\", pakai ばかり.</div>","n4-50":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜場合」artinya <b>「kalau terjadi situasi ～」</b>. Tulisan seperti \"Jika terjadi kebakaran, harap ～\" atau \"Jika ada masalah, harap ～\" yang kamu lihat di stasiun, kamar hotel, atau buku petunjuk, dalam bahasa Jepang memakai「場合」. Bentuk ini lebih formal daripada「〜たら」dan sering muncul dalam peraturan, pengumuman, atau penjelasan dari pegawai toko dan layanan pelanggan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Peraturan・Pengumuman</span>Kamu mengandaikan suatu situasi yang \"mungkin terjadi, mungkin juga tidak\", lalu memberi tahu lawan bicara apa yang harus dilakukan saat itu. Di belakangnya sering ada「〜てください」atau aturan.</div><div class='gd-ex-line'>・<span class='gd-jp'>地震の場合は、机の下に隠れてください。</span>(Jika terjadi gempa, harap berlindung di bawah meja)</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の場合は、試合は中止です。</span>(Jika hujan, pertandingan dibatalkan)</div><div class='gd-ex-line'>・<span class='gd-jp'>分からない場合は、先生に聞いてください。</span>(Kalau tidak mengerti, silakan tanya guru)</div><div class='gd-sec'>Setelah「場合」hampir selalu ada「は」, jadi bentuknya「〜場合は」. Hafalkan saja sebagai satu paket.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: langsung sambung dengan bentuk kamus, bentuk ない, atau bentuk た.<br><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れる場合</span></span><span class='gd-pair'><span class='gd-jp'>行けない</span> → <span class='gd-jp'>行けない場合</span></span><span class='gd-pair'><span class='gd-jp'>忘れた</span> → <span class='gd-jp'>忘れた場合</span></span><br><b>Kata sifat い</b>: langsung sambung. <span class='gd-pair'><span class='gd-jp'>熱が高い</span> → <span class='gd-jp'>熱が高い場合</span></span><br><b>Kata sifat な</b>: pertahankan「な」. <span class='gd-pair'><span class='gd-jp'>無理</span> → <span class='gd-jp'>無理な場合</span></span><br><b>Kata benda</b>: sisipkan「の」di tengah. <span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨の場合</span></span><span class='gd-pair'><span class='gd-jp'>火事</span> → <span class='gd-jp'>火事の場合</span></span></div><div class='gd-sec'><span class='gd-tag'>Beda bentuk kamus dan bentuk た</span>Kata kerja bentuk kamus atau bentuk た, maknanya sedikit berbeda:<br>・<span class='gd-jp'>遅れる場合は、電話してください。</span>(Kalau kamu akan terlambat, tolong telepon dulu: menghubungi sebelum terlambat)<br>・<span class='gd-jp'>カードをなくした場合は、すぐ連絡してください。</span>(Kalau kartunya sampai hilang, segera hubungi kami: setelah kejadian terjadi)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・「場合」dibaca <b>ばあい</b>, bukan ばしょ.<br>・Kata benda dan kata sifat な tidak bisa langsung diberi「だ」: bukan「雨だ場合」, melainkan <span class='gd-jp'>雨の場合</span>; bukan「無理だ場合」, melainkan <span class='gd-jp'>無理な場合</span>.<br>・Untuk kata sifat な, pakai <b>な</b>; jangan tertukar dengan kata benda lalu menulis「の」.<br>・「場合」hanya untuk hal yang <b>belum tentu terjadi</b>. Untuk hal yang pasti datang, misalnya \"kalau sudah jam 10\", tidak bisa dibilang「10時になった場合」; pakai <span class='gd-jp'>10時になったら</span>.<br>・Hal yang sudah terjadi juga tidak bisa: \"saat kemarin hujan\" tidak bisa dibilang「昨日雨が降った場合」.<br>・Nadanya cukup formal. Saat ngobrol dengan teman dan bilang \"kalau hujan, aku tidak jadi pergi\", <span class='gd-jp'>雨だったら</span> terdengar lebih natural.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'>Sama-sama \"kalau hujan\":<br><b>場合</b>: <span class='gd-jp'>雨の場合は、イベントは中止です。</span>(Jika hujan, acara dibatalkan) → seperti aturan yang tertulis di pengumuman.<br><b>たら</b>: <span class='gd-jp'>雨が降ったら、家で映画を見よう。</span>(Kalau hujan, nonton film di rumah saja yuk) → obrolan santai antar teman.<br>Selain itu,「たら」bisa dipakai untuk hal yang pasti terjadi (<span class='gd-jp'>駅に着いたら、電話して。</span> Kalau sudah sampai stasiun, telepon aku), sedangkan「場合」tidak bisa.</div><div class='gd-warn'>Trik cepat: kalau bisa diterjemahkan \"jika terjadi ～\" atau \"apabila ～\" dan kamu sedang membahas peraturan atau penjelasan, pakai「場合」. Untuk obrolan sehari-hari, atau hal yang pasti terjadi, pakai「たら」.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Ungkapan \"kalau\" lainnya bisa dipelajari sambil dibandingkan: <span class='gd-jp'>〜ば</span> (bentuk pengandaian), <span class='gd-jp'>〜なら</span>, <span class='gd-jp'>〜と</span>. Masing-masing punya nuansa yang berbeda.</div>","n4-44":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Perasaan seperti “ingin”, “takut”, atau “dingin” hanya diketahui oleh orang yang merasakannya. Karena itu, saat membicarakan perasaan <b>orang lain</b>, bahasa Jepang tidak langsung bilang “dia ingin”, tapi “dia <b>menunjukkan</b> sikap ingin”. Inilah 「〜がる」. Mirip dengan bahasa Indonesia, “dia terus minta ~” atau “dia kelihatan takut banget”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Keinginan orang lain</span>Adik, teman, anak kecil, bahkan hewan peliharaan: kelihatan jelas kalau dia sangat ingin sesuatu atau ingin melakukan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>弟が新しいゲーム機を欲しがっています。</span>(Adikku terus-terusan ingin konsol game baru)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はずっと日本へ行きたがっています。</span>(Dia sudah lama sekali ingin pergi ke Jepang)</div><div class='gd-sec'><span class='gd-tag'>Perasaan orang lain</span>Takut, dingin, sakit, tidak suka: semua ini bisa kelihatan dari ekspresi dan gerak-geriknya.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが注射を怖がっています。</span>(Anak itu takut disuntik)</div><div class='gd-ex-line'>・<span class='gd-jp'>娘は野菜を嫌がって、食べません。</span>(Anak perempuanku tidak suka sayur dan menolak memakannya)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Hanya kata sifat yang menyatakan emosi atau perasaan yang bisa diikuti 「がる」 (<span class='gd-jp'>欲しい</span>, <span class='gd-jp'>怖い</span>, <span class='gd-jp'>痛い</span>, <span class='gd-jp'>寒い</span>, <span class='gd-jp'>嫌だ</span>…).<br><b>Kata sifat い</b>: buang 「い」 di akhir, lalu tambahkan 「がる」.<br><span class='gd-pair'><span class='gd-jp'>欲しい</span> → <span class='gd-jp'>欲しがる</span></span><span class='gd-pair'><span class='gd-jp'>怖い</span> → <span class='gd-jp'>怖がる</span></span><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛がる</span></span></div><div class='gd-sec'><b>Ingin melakukan sesuatu</b>: ubah dulu jadi 「〜たい」, lalu buang 「い」 dan tambahkan 「がる」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行きたい</span> → <span class='gd-jp'>行きたがる</span></span><span class='gd-pair'><span class='gd-jp'>働く</span> → <span class='gd-jp'>働きたい</span> → <span class='gd-jp'>働きたがる</span></span></div><div class='gd-sec'><b>Kata sifat な</b>: buang 「だ」 dulu, lalu tambahkan 「がる」, misalnya <span class='gd-pair'><span class='gd-jp'>嫌だ</span> → <span class='gd-jp'>嫌がる</span></span><span class='gd-pair'><span class='gd-jp'>残念だ</span> → <span class='gd-jp'>残念がる</span></span>. Kata sifat な yang bisa dipakai begini tidak banyak. Yang umum hanya <span class='gd-jp'>嫌がる</span>, <span class='gd-jp'>残念がる</span>, <span class='gd-jp'>不思議がる</span>, dan <span class='gd-jp'>面倒がる</span>.<br>Hati-hati: <span class='gd-jp'>大きい</span> bukan perasaan, jadi tidak bisa bilang ×<span class='gd-jp'>大きがる</span>. <span class='gd-jp'>好き</span> memang perasaan, tapi juga tidak dibilang ×<span class='gd-jp'>好きがる</span>.</div><div class='gd-sec'>Setelah menjadi 「がる」, kata ini berubah seperti <span class='gd-jp'>帰る</span>, yaitu kata kerja golongan I (godan): <span class='gd-jp'>がります</span>, <span class='gd-jp'>がりません</span>, <span class='gd-jp'>がっています</span>, <span class='gd-jp'>がった</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>がっています</span>Untuk bilang “sekarang dia sedang ingin / takut”, hampir selalu dipakai bentuk ini. Kalau hanya <span class='gd-jp'>欲しがります</span>, kesannya lebih ke kebiasaan atau kecenderungan: “dia memang biasanya begitu”.</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が散歩に行きたがっている。</span>(Anjingnya mau diajak jalan-jalan)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<b>Untuk diri sendiri, jangan pakai がる</b>: perasaan sendiri cukup bilang <span class='gd-jp'>私は新しいスマホが欲しいです</span>, bukan 「私は欲しがっています」. Sebaliknya, dalam bahasa Indonesia “dia mau” terdengar wajar. Tapi dalam bahasa Jepang, langsung bilang <span class='gd-jp'>弟は欲しいです</span> terdengar janggal, jadi pakai 欲しがっています.<br>・<b>Partikelnya berubah</b>: <span class='gd-jp'>水が欲しい</span> berubah jadi 「を」 setelah memakai がる: <span class='gd-jp'>弟は水を欲しがっている</span>.<br>・<b>Saat bertanya langsung ke lawan bicara, jangan pakai がる</b>: ke teman, cukup tanya <span class='gd-jp'>何が食べたい？</span> (Kamu mau makan apa?).<br>・<b>Jangan dipakai untuk orang yang lebih tua atau atasan</b>: 「〜がる」 adalah cara mengamati dan menggambarkan sikap yang ditunjukkan orang itu. Kalau dipakai untuk guru atau atasan, kesannya seperti menilai perasaan mereka, jadi kurang sopan. Jangan bilang 先生が帰りたがっています. Yang lebih baik: <span class='gd-jp'>先生は帰りたいとおっしゃっていました。</span> (Guru bilang beliau ingin pulang)</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk “adik ingin HP baru”, ada tiga cara bilang. Bedanya ada pada <b>perasaan siapa dan dari mana kamu tahu</b>:<br><b>欲しい</b> = perasaan sendiri: <span class='gd-jp'>私は新しいスマホが欲しいです。</span> (Aku ingin HP baru)<br><b>欲しがっている</b> = dia sudah mengatakannya atau menunjukkannya: <span class='gd-jp'>弟は新しいスマホを欲しがっています。</span> (Adikku terus minta HP baru)<br><b>欲しそう</b> = dia tidak bilang apa-apa, kamu menebak dari tampangnya: <span class='gd-jp'>弟は新しいスマホが欲しそうです。</span> (Adikku kelihatannya ingin HP baru)</div><div class='gd-warn'>Trik menentukan: perasaan sendiri pakai 「たい・欲しい」. Perasaan orang lain yang sudah terlihat jelas pakai 「がっている」. Kalau hanya menebak dari raut wajahnya, pakai 「そう」.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau tidak mau menilai perasaan orang lain, kamu bisa pakai bentuk kutipan: <span class='gd-jp'>姉は留学したいと言っています。</span> (Kakakku bilang dia ingin kuliah di luar negeri)</div>","n4-46":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜なさい」 itu seperti ibu yang bilang <b>“Cepat tidur!” “Cuci tangannya sampai bersih!”</b>. Ada wibawa orang dewasa, tapi bukan sedang memarahi. Ini perintah dari <b>atas ke bawah</b>, paling sering dipakai orang tua ke anak dan guru ke murid.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Orang tua ke anak</span>Menyuruh anak melakukan hal yang memang harus dilakukan. Ibu-ibu di drama dan anime Jepang mengatakannya tiap hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝なさい。</span>(Cepat tidur)</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を先にやりなさい。</span>(Kerjakan PR dulu)</div><div class='gd-sec'><span class='gd-tag'>Guru ke murid</span>Instruksi saat pelajaran.</div><div class='gd-ex-line'>・<span class='gd-jp'>よく聞きなさい。</span>(Dengarkan baik-baik)</div><div class='gd-sec'><span class='gd-tag'>Soal ujian</span>Soal JLPT dan ujian sekolah di Jepang sering ditulis begini. Kalau melihatnya, kamu langsung tahu itu instruksi “tolong ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>正しいものを選びなさい。</span>(Pilihlah jawaban yang benar)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ます, lalu <b>buang ます</b> dan tambahkan なさい. Ketiga golongan kata kerja caranya sama, jadi tidak perlu menghafal aturan lain.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → buang ます → <span class='gd-jp'>行きなさい</span></span><br><span class='gd-pair'><span class='gd-jp'>洗います</span> → <span class='gd-jp'>洗いなさい</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べなさい</span></span><span class='gd-pair'><span class='gd-jp'>寝ます</span> → <span class='gd-jp'>寝なさい</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強します</span> → <span class='gd-jp'>勉強しなさい</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来なさい</span>(きなさい)</span></div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kedengarannya tidak galak, tapi <b>ini bukan bentuk sopan</b>. Kalau kamu bilang 「<span class='gd-jp'>座りなさい</span>」 ke guru, atasan, atau tamu, itu sangat tidak sopan. Untuk meminta orang melakukan sesuatu, pakai 「<span class='gd-jp'>座ってください</span>」.<br>・<span class='gd-jp'>来なさい</span> dibaca <b>きなさい</b>, bukan こなさい.<br>・Untuk menyuruh orang “jangan ~”, なさい tidak punya bentuk negatif, jadi jangan menempelkan ない begitu saja. Pakai 「〜ないで」 atau 「〜てはいけません」, misalnya <span class='gd-jp'>走らないで</span> (jangan lari).<br>・<span class='gd-jp'>おやすみなさい</span>, <span class='gd-jp'>おかえりなさい</span>, dan <span class='gd-jp'>ごめんなさい</span> memang mengandung なさい, tapi sudah jadi ungkapan tetap dan tidak berarti perintah. Hanya saja, <span class='gd-jp'>ごめんなさい</span> lebih santai. Untuk minta maaf ke atasan atau tamu, pakai 「<span class='gd-jp'>すみません</span>」 atau 「<span class='gd-jp'>申し訳ありません</span>」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama menyuruh orang tidur lebih awal, tapi kalau cara bilangnya diganti, nada dan hubungan antara kalian ikut berubah:<br><b>〜なさい</b> = dari atas ke bawah, bernada mendidik (ibu ke anak):</div><div class='gd-ex-line'>・<span class='gd-jp'>もう11時だよ。早く寝なさい。</span>(Sudah jam 11, cepat tidur)</div><div class='gd-sec'><b>Bentuk perintah</b> = langsung dan kasar, kebanyakan dipakai laki-laki, atau saat bertengkar atau darurat:</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝ろ。</span>(Cepat tidur sana!)</div><div class='gd-sec'><b>〜てください</b> = meminta dengan sopan, dipakai dokter ke pasien, pelayan toko ke pelanggan, dan sebagainya:</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝てくださいね。</span>(Hari ini tolong istirahat lebih awal ya)</div><div class='gd-sec'><b>〜てね</b> = pengingat santai antar teman atau keluarga:</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝てね。</span>(Hari ini tidur lebih awal ya)</div><div class='gd-warn'>Trik menentukan: orang dewasa “mendidik” anak pakai なさい. Minta tolong dengan sopan pakai てください. Pengingat santai ke teman pakai てね. ろ paling kasar, jadi pemula jangan sembarangan memakainya.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Lanjutkan ke 「bentuk perintah dan bentuk larangan」 (<span class='gd-jp'>寝ろ</span>, <span class='gd-jp'>寝るな</span>). Dengan begitu kamu bisa memahami perintah yang lebih langsung di drama Jepang, dan lebih paham kenapa なさい dianggap “lembut”.</div>","n4-51":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Bentuk volisional adalah <b>versi akrab</b> dari 「〜ましょう」. Ke rekan kerja kamu bilang <span class='gd-jp'>一緒に行きましょう</span>, ke teman cukup <span class='gd-jp'>一緒に行こう</span>. Artinya sama, yaitu \"ayo ～\", hanya nadanya lebih santai.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengajak</span>Mengajak lawan bicara melakukan sesuatu bersamamu.</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に行こう。</span>（Ayo pergi bareng）</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと休もう。</span>（Istirahat sebentar yuk）</div><div class='gd-sec'><span class='gd-tag'>Menyemangati diri sendiri</span>Memutuskan sesuatu dalam hati atau bicara sendiri. Boleh dipakai walau tidak ada orang di sekitarmu.</div><div class='gd-ex-line'>・<span class='gd-jp'>よし、明日から早く起きよう。</span>（Oke, mulai besok aku bangun lebih pagi）</div><div class='gd-sec'><span class='gd-tag'>Menawarkan bantuan</span>Tambahkan 「か」 di belakangnya, jadi artinya \"Mau kubantu ～?\".</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物、持とうか。</span>（Barangnya, mau kubawakan?）</div><div class='gd-h'>Cara mengubahnya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: ubah bunyi terakhir menjadi bunyi baris 「お」 di baris yang sama, lalu tambahkan 「う」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く diganti こ → <span class='gd-jp'>行こう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲もう</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待とう</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話そう</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ろう</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会おう</span></span><br>Dari bentuk ます juga bisa: ganti 「き」 pada <span class='gd-jp'>行きます</span> dengan 「こ」, lalu tambahkan 「う」.</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang 「る」 di akhir, lalu tambahkan 「よう」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べよう</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きよう</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見よう</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しよう</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来よう</span>（こよう）</span></div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Bagian こう pada 「行こう」 dibaca panjang, terdengar seperti 「いこー」. Kalau dibaca pendek 「いこ」, itu gaya yang manja dan sangat kasual, jadi nuansanya berbeda.<br>・<span class='gd-jp'>会う</span> menjadi <span class='gd-jp'>会おう</span>. Jangan tertukar dengan bentuk ない <span class='gd-jp'>会わない</span> lalu menulis 「会わう」.<br>・<span class='gd-jp'>帰る</span> dan <span class='gd-jp'>入る</span> tampak seperti golongan 2, padahal golongan 1. Yang benar <span class='gd-jp'>帰ろう</span>, bukan 帰よう.<br>・Bentuk volisional 来る dibaca <b>こよう</b>, bukan きよう.<br>・Bentuk ini hanya bisa dipakai untuk hal yang <b>kamu sendiri</b> lakukan, atau untuk <b>mengajak lawan bicara</b> melakukannya bersamamu. Bentuk ini tidak bisa dipakai untuk menyuruh orang lain. Kalau mau bilang \"temanmu ajak juga dong\", ubah jadi <span class='gd-jp'>友達も呼ぼう</span>（Ajak temanmu juga yuk）.<br>・Ini bahasa antarteman. Ke guru atau pelanggan, ganti kembali ke 「〜ましょう」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk mengajak teman nonton film, ada tiga cara bilang:<br><span class='gd-jp'>映画を見に行こう。</span>（Ayo nonton film）: mengajak langsung, terasa seperti \"oke, sudah diputuskan ya\".<br><span class='gd-jp'>映画を見に行かない？</span>（Mau nonton film nggak?）: tanya dulu apakah dia mau, jadi lebih memberi ruang.<br><span class='gd-jp'>映画を見に行きましょう。</span>（Mari kita nonton film）: versi sopan dari 「行こう」, untuk orang yang belum akrab atau yang lebih tua.</div><div class='gd-warn'>Tips memilih: kalau lawan bicaramu temanmu dan kamu yakin dia akan setuju, pakai 「行こう」. Kalau mau tanya dulu, pakai 「行かない？」. Kalau harus bersikap sopan, pakai 「行きましょう」.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Tambahkan 「と思います」 di belakangnya, artinya \"aku berencana ～\": <span class='gd-jp'>来年、日本へ行こうと思います。</span>（Aku berencana pergi ke Jepang tahun depan）</div>","n4-52":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Bentuk potensial artinya <b>\"bisa ～\"</b> atau <b>\"dapat ～\"</b>, yaitu makna itu langsung dimasukkan ke dalam kata kerjanya. <span class='gd-jp'>書く</span> artinya \"menulis\", dan kalau menjadi <span class='gd-jp'>書ける</span> artinya \"bisa menulis\". Saat orang Jepang membicarakan bisa atau tidaknya sesuatu, bentuk inilah yang paling sering dipakai.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bisa (kemampuan hasil belajar)</span>Sudah pernah belajar dan berlatih, jadi bisa melakukannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>韓国語が書けます。</span>（Aku bisa menulis bahasa Korea）</div><div class='gd-ex-line'>・<span class='gd-jp'>ピアノが弾けますか。</span>（Kamu bisa main piano?）</div><div class='gd-sec'><span class='gd-tag'>Bisa / boleh (situasi mengizinkan)</span>Bukan soal mampu atau tidak, tapi soal waktu, tempat, atau aturan yang mengizinkan atau tidak.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真が撮れますか。</span>（Boleh foto di sini?）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は来られますか。</span>（Besok kamu bisa datang?）</div><div class='gd-sec'><span class='gd-tag'>Sanggup makan</span>Untuk makanan, artinya sering \"berani makan\" atau \"sanggup makan\".</div><div class='gd-ex-line'>・<span class='gd-jp'>納豆が食べられますか。</span>（Kamu berani makan natto?）</div><div class='gd-h'>Cara mengubahnya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: ubah bunyi terakhir menjadi bunyi baris 「え」 di baris yang sama, lalu tambahkan 「る」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti け → <span class='gd-jp'>書ける</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲める</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買える</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待てる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰れる</span></span><br>Dari bentuk ます juga bisa: ganti 「き」 pada <span class='gd-jp'>書きます</span> dengan 「け」 → <span class='gd-jp'>書けます</span>.</div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang 「る」 di akhir, lalu tambahkan 「られる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きられる</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span><br>Kata kerja \"kata benda＋する\" juga sama, ganti する menjadi できる: <span class='gd-pair'><span class='gd-jp'>説明する</span> → <span class='gd-jp'>説明できる</span></span></div><div class='gd-h'>Setelah berubah, bisa diubah lagi</div><div class='gd-sec'>Setelah menjadi bentuk potensial, <b>kata itu sendiri sudah menjadi kata kerja golongan 2</b>. Kalau mau bilang \"tidak bisa\" atau \"sudah bisa\", lanjutkan mengubahnya dengan aturan golongan 2:<br><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けます</span></span><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けない</span></span><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けた</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>朝、なかなか起きられない。</span>（Pagi hari selalu susah bangun）</div><div class='gd-h'>Partikel: を sering berganti jadi が</div><div class='gd-sec'>Setelah menjadi bentuk potensial, 「を」 biasanya diganti 「が」:<br><span class='gd-pair'><span class='gd-jp'>日本語を話す</span> → <span class='gd-jp'>日本語が話せる</span></span><br>Dalam percakapan sehari-hari kadang terdengar を juga, tapi buku pelajaran dan ujian mengutamakan が, jadi ingat <b>が</b> saja, itu yang paling aman.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, dan <span class='gd-jp'>走る</span> tampak seperti golongan 2, padahal golongan 1. Yang benar <span class='gd-jp'>帰れる</span>, bukan 帰られる.<br>・Bentuk potensial 来る dibaca <b>こられる</b>, bukan きられる.<br>・Bentuk potensial する harus diganti seluruhnya menjadi <span class='gd-jp'>できる</span>, tidak bisa dipaksa pakai aturan biasa.<br>・Dalam percakapan sering terdengar <span class='gd-jp'>食べれる</span>, <span class='gd-jp'>見れる</span>, <span class='gd-jp'>来れる</span> (tanpa 「ら」). Orang Jepang memang sering bilang begitu, tapi di buku pelajaran, ujian, dan situasi formal tetap pakai <span class='gd-jp'>食べられる</span>, <span class='gd-jp'>見られる</span>, <span class='gd-jp'>来られる</span>.<br>・Untuk \"terlihat\" atau \"terdengar\" yang <b>masuk sendiri ke mata atau telinga</b>, bahasa Jepang memakai <span class='gd-jp'>見える</span> dan <span class='gd-jp'>聞こえる</span>: <span class='gd-jp'>ここから富士山が見える。</span>（Dari sini Gunung Fuji terlihat）. Sedangkan <span class='gd-jp'>見られる</span> dan <span class='gd-jp'>聞ける</span> berarti <b>ada kesempatan atau cara untuk melihat dan mendengar</b>: <span class='gd-jp'>このアプリで映画が見られる。</span>（Dengan aplikasi ini kamu bisa nonton film）</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><span class='gd-jp'>〜ことができる</span> yang pernah kamu pelajari artinya sama dengan bentuk potensial:<br>・<span class='gd-jp'>日本語が話せます。</span>（Aku bisa bicara bahasa Jepang）<br>・<span class='gd-jp'>日本語を話すことができます。</span>（Aku mampu berbicara bahasa Jepang）<br>Bedanya ada di panjang dan nuansanya. Bentuk potensial lebih pendek dan paling sering dipakai dalam obrolan sehari-hari. <span class='gd-jp'>ことができる</span> lebih panjang dan lebih formal, sering muncul di buku panduan, pengumuman, dan pidato. Satu hal lagi: kata kerja sebelum <span class='gd-jp'>ことができる</span> tidak berubah bentuk, dan partikelnya tetap 「を」.</div><div class='gd-warn'>Tips memilih: dalam percakapan biasa pakai bentuk potensial. Kalau mau terdengar lebih formal dan jelas, pakai ことができる. Artinya sama, jadi memilih yang mana pun tidak salah.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Tambahkan 「ようになる」 di belakangnya, artinya \"jadi bisa ～\": <span class='gd-jp'>日本語が少し話せるようになりました。</span>（Aku jadi bisa bicara bahasa Jepang sedikit）</div>","n4-65":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, kita bisa mengubah \"Siapa namamu?\" menjadi \"Boleh tahu <b>nama Bapak/Ibu</b>?\" supaya terdengar lebih sopan. Bahasa Jepang punya cara serupa: tambahkan <b>お</b> atau <b>ご</b> di depan kata benda, dan kalimatnya jadi terdengar lebih sopan dan halus.<br>「<span class='gd-jp'>ございます</span>」adalah <b>versi pelayan toko/hotel</b> dari <span class='gd-jp'>あります</span>. Artinya tetap sama, yaitu \"ada\", hanya saja lebih sopan.</div><div class='gd-h'>Kapan pakai お・ご</div><div class='gd-sec'><span class='gd-tag'>Milik lawan bicara</span>Saat menyebut nama, keluarga, atau alamat lawan bicara, tambahkan お・ご untuk menunjukkan rasa hormat.</div><div class='gd-ex-line'>・<span class='gd-jp'>お名前をお願いします。</span>（Tolong sebutkan nama Anda）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご家族はお元気ですか。</span>（Apa kabar keluarga Anda?）</div><div class='gd-sec'><span class='gd-tag'>Supaya terdengar halus</span>Pada beberapa kata, お・ご hanya membuat ucapan lebih elegan. Kata-kata ini boleh dipakai untuk urusan sendiri dan sangat sering muncul sehari-hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>お茶を飲みませんか。</span>（Mau minum teh?）</div><div class='gd-ex-line'>・<span class='gd-jp'>もうご飯を食べました。</span>（Aku sudah makan）</div><div class='gd-h'>Cara menyambung: お atau ご?</div><div class='gd-sec'><b>Kata asli Jepang</b> (kanji dengan bacaan Jepang, atau kata yang memang ditulis hiragana) umumnya memakai <b>お</b>:<br><span class='gd-jp'>お名前</span>、<span class='gd-jp'>お店</span>、<span class='gd-jp'>お水</span>、<span class='gd-jp'>お手紙</span></div><div class='gd-sec'><b>Kata kanji serapan dari Tiongkok</b> (bacaannya terdengar agak Tionghoa, biasanya terdiri dari dua kanji) umumnya memakai <b>ご</b>:<br><span class='gd-jp'>ご住所</span>、<span class='gd-jp'>ご家族</span>、<span class='gd-jp'>ご予約</span>、<span class='gd-jp'>ご連絡</span></div><div class='gd-sec'>Tapi <b>pengecualiannya cukup banyak</b>. Misalnya <span class='gd-jp'>お電話</span>、<span class='gd-jp'>お時間</span>、<span class='gd-jp'>お食事</span> adalah kata kanji serapan, tetapi tetap memakai お. Hafalkan satu per satu saat bertemu, tidak perlu memaksakan aturan.<br>Kata serapan berhuruf katakana biasanya tidak diberi awalan: cukup bilang <span class='gd-jp'>コーヒー</span>.</div><div class='gd-h'>ございます: versi sopan dari あります</div><div class='gd-sec'><span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>ございます</span></span><span class='gd-pair'><span class='gd-jp'>ありません</span> → <span class='gd-jp'>ございません</span></span><span class='gd-pair'><span class='gd-jp'>ありました</span> → <span class='gd-jp'>ございました</span></span><br>Sebenarnya kamu sudah lama memakainya: itulah yang ada di dalam <span class='gd-jp'>ありがとうございます</span> dan <span class='gd-jp'>おはようございます</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>お手洗いはあちらにございます。</span>（Toilet ada di sebelah sana）</div><div class='gd-ex-line'>・<span class='gd-jp'>赤いのもございますよ。</span>（Yang merah juga ada, lho）</div><div class='gd-ex-line'>・<span class='gd-jp'>申し訳ございません。</span>（Mohon maaf sebesar-besarnya）</div><div class='gd-sec'>Selain itu, <b>でございます</b> adalah versi sopan dari <span class='gd-jp'>です</span>, sering dipakai pelayan toko saat memperkenalkan barang:</div><div class='gd-ex-line'>・<span class='gd-jp'>こちらがメニューでございます。</span>（Ini menunya）</div><div class='gd-h'>Bagian yang mudah salah</div><div class='gd-warn'>・お・ご untuk menghormati <b>tidak boleh dipakai untuk diri sendiri</b>: saat memperkenalkan diri, ucapkan <span class='gd-jp'>私の名前は</span>, jangan 「私のお名前は」. Hanya kata yang masuk kategori \"supaya terdengar halus\" seperti <span class='gd-jp'>お茶</span> dan <span class='gd-jp'>ご飯</span> yang boleh dipakai untuk diri sendiri.<br>・<span class='gd-jp'>ございます</span> hanya dipakai untuk <b>benda dan hal</b>, tidak untuk orang. Untuk \"ada/tidaknya orang\", pakai <span class='gd-jp'>おります</span> atau <span class='gd-jp'>いらっしゃいます</span> di bawah ini.<br>・「でございます」tidak boleh dipakai untuk lawan bicara: untuk bertanya \"Apakah Anda Pak Tanaka?\", katakan <span class='gd-jp'>田中様でいらっしゃいますか</span>, bukan 「田中様でございますか」.<br>・Menambah お・ご bukan berarti makin banyak makin baik. Kalau dipasang pada kata yang tidak biasa diberi awalan, malah terdengar aneh. Pelajari saja yang sering ada di buku pelajaran dan diucapkan pelayan toko, itu sudah cukup.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Di sebuah toko, ada beberapa cara untuk mengatakan \"ada\":<br><b>あります</b> (sopan biasa): <span class='gd-jp'>トイレはあちらにあります。</span>（Toilet ada di sebelah sana）<br><b>ございます</b> (lebih sopan, untuk benda): <span class='gd-jp'>お手洗いはあちらにございます。</span>（Toilet ada di sebelah sana）<br><b>おります</b> (untuk orang di pihak sendiri, merendahkan diri): <span class='gd-jp'>店長は事務所におります。</span>（Manajer toko ada di kantor）<br><b>いらっしゃいます</b> (untuk lawan bicara atau tamu, meninggikan mereka): <span class='gd-jp'>田中様はいらっしゃいますか。</span>（Apakah Pak Tanaka ada?）</div><div class='gd-warn'>Trik menentukan: untuk <b>benda</b> pakai ございます; untuk <b>orang</b>, pihak sendiri pakai おります, lawan bicara pakai いらっしゃいます.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>お・ご juga bisa ditambahkan pada kata kerja untuk membentuk ungkapan hormat atau merendah, misalnya <span class='gd-jp'>少々お待ちください。</span>（Mohon tunggu sebentar）. Lanjutkan ke materi 「尊敬語」 dan 「謙譲語」.</div>","n4-66":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Ungkapan singkatan (縮約) adalah cara bahasa Jepang <b>menyatukan bunyi karena bicara cepat</b>. Mirip dengan bahasa Indonesia, \"tidak usah\" jadi \"gausah\" dan \"sudah\" jadi \"udah\". Orang Jepang saat ngobrol juga mengubah <span class='gd-jp'>見ている</span> menjadi <span class='gd-jp'>見てる</span>. Artinya sama persis, hanya lebih santai dan kasual.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Obrolan sehari-hari</span>Saat bicara dengan teman dan keluarga. Dalam drama, anime, dan manga Jepang, hampir semuanya memakai bentuk ini.</div><div class='gd-sec'><span class='gd-tag'>Jangan dipakai</span>Untuk situasi formal seperti menulis laporan, mengirim email ke atasan, atau wawancara. Pakai bentuk lengkapnya.</div><div class='gd-h'>Empat yang paling sering terdengar</div><div class='gd-sec'><b>1. ている → てる</b>: huruf 「い」 di tengah dihilangkan.<br><span class='gd-pair'><span class='gd-jp'>見ている</span> → い dihilangkan → <span class='gd-jp'>見てる</span></span><br>Kalau aslinya 「でいる」, jadi 「でる」: <span class='gd-pair'><span class='gd-jp'>読んでいる</span> → <span class='gd-jp'>読んでる</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>何してるの？</span>（Lagi ngapain?）</div><div class='gd-sec'><b>2. ておく → とく</b>: 「て」 dan 「お」 menyatu menjadi satu 「と」.<br><span class='gd-pair'><span class='gd-jp'>買っておく</span> → <span class='gd-jp'>買っとく</span></span><br>Kalau aslinya 「でおく」, jadi 「どく」: <span class='gd-pair'><span class='gd-jp'>読んでおく</span> → <span class='gd-jp'>読んどく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>飲み物、買っとくね。</span>（Minumannya aku beliin dulu ya）</div><div class='gd-sec'><b>3. てしまう → ちゃう</b>: 「てしま」 menyusut menjadi 「ちゃ」.<br><span class='gd-pair'><span class='gd-jp'>食べてしまう</span> → <span class='gd-jp'>食べちゃう</span></span><br>Kalau aslinya 「でしまう」, jadi 「じゃう」: <span class='gd-pair'><span class='gd-jp'>飲んでしまう</span> → <span class='gd-jp'>飲んじゃう</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ケーキ、全部食べちゃった。</span>（Kuenya sudah kumakan semua）</div><div class='gd-sec'><b>4. では → じゃ</b>: <span class='gd-pair'><span class='gd-jp'>学生ではない</span> → <span class='gd-jp'>学生じゃない</span></span></div><div class='gd-h'>Setelah disingkat, masih bisa berubah bentuk</div><div class='gd-sec'>Bentuk singkatan bisa diubah ke lampau, negatif, dan bentuk て seperti biasa:<br><span class='gd-pair'><span class='gd-jp'>見てる</span> → <span class='gd-jp'>見てた</span>／<span class='gd-jp'>見てない</span></span><br><span class='gd-pair'><span class='gd-jp'>買っとく</span> → <span class='gd-jp'>買っといた</span>／<span class='gd-jp'>買っといて</span></span><br><span class='gd-pair'><span class='gd-jp'>食べちゃう</span> → <span class='gd-jp'>食べちゃった</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>宿題、まだ終わってない。</span>（PR-nya belum selesai）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までに読んどいて。</span>（Tolong dibaca dulu sebelum besok ya）</div><div class='gd-h'>Bagian yang mudah salah</div><div class='gd-warn'>・Kalau aslinya 「で」, setelah disingkat juga harus tetap bersuara (dakuten): yang benar <span class='gd-jp'>飲んじゃう</span>, bukan 飲んちゃう; yang benar <span class='gd-jp'>読んどく</span>, bukan 読んとく.<br>・<span class='gd-jp'>見てる</span> (sedang melihat) dan <span class='gd-jp'>見とく</span> (melihat dulu) terdengar mirip, tapi artinya sangat berbeda, jadi perhatikan saat mendengarkan.<br>・Bentuk 「singkatan + ます」 seperti <span class='gd-jp'>見てます</span> sering terdengar di toko dan antar rekan kerja, tetapi untuk dokumen dan surat tetap tulis <span class='gd-jp'>見ています</span>.<br>・Singkatan hanya membuat cara bicara lebih santai, artinya tidak berubah: <span class='gd-jp'>ちゃう</span> tetap bisa berarti \"selesai melakukan\", dan bisa juga berarti \"tidak sengaja, aduh\".</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><span class='gd-jp'>ては</span> juga bisa menyusut menjadi <span class='gd-jp'>ちゃ</span>. Bedanya tipis dengan <span class='gd-jp'>ちゃう</span>, tetapi artinya jauh berbeda:<br><span class='gd-jp'>食べちゃった。</span>（Sudah kumakan）＝<span class='gd-jp'>食べてしまった</span><br><span class='gd-jp'>食べちゃだめ。</span>（Tidak boleh dimakan）＝<span class='gd-jp'>食べてはだめ</span></div><div class='gd-warn'>Trik menentukan: kalau di belakangnya 「う」 atau 「った」, itu てしまう; kalau diikuti 「だめ」 atau 「いけない」, itu ては.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「なければ」 dalam percakapan menyusut menjadi 「なきゃ」: <span class='gd-jp'>もう帰らなきゃ。</span>（Aku harus pulang sekarang）</div>","n4-53":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Bentuk perintah itu seperti membentak langsung: 「<b>Lakukan ～!</b>」. Bentuk larangan seperti 「<b>Dilarang ～!</b>」. Nadanya sama seperti \"Lari!\" atau \"Jangan masuk!\" dalam bahasa Indonesia, tanpa basa-basi sedikit pun. Kalau dipakai ke orang dalam percakapan sehari-hari, kesannya sangat kasar. Kamu paling sering mendengarnya di anime, pertandingan olahraga, dan situasi darurat.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Darurat, bahaya</span>Saat tidak ada waktu untuk sopan-sopan.</div><div class='gd-ex-line'>・<span class='gd-jp'>危ない！逃げろ！</span>（Awas! Lari!）</div><div class='gd-sec'><span class='gd-tag'>Memberi semangat</span>Diteriakkan dari pinggir lapangan. Di sini tidak dianggap kasar, dan laki-laki maupun perempuan sama-sama memakainya.</div><div class='gd-ex-line'>・<span class='gd-jp'>頑張れ！負けるな！</span>（Semangat! Jangan kalah!）</div><div class='gd-sec'><span class='gd-tag'>Mengutip kata orang lain</span>Tambahkan 「と言われた」 untuk bilang \"seseorang menyuruhku ～\". Ini situasi yang paling sering akan kamu pakai sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にお酒を飲むなと言われた。</span>（Dokter menyuruhku tidak minum alkohol）</div><div class='gd-ex-line'>・<span class='gd-jp'>父に早く寝ろと言われた。</span>（Ayah menyuruhku tidur lebih awal）</div><div class='gd-sec'><span class='gd-tag'>Rambu, dari atas ke bawah</span>Tulisan 「<span class='gd-jp'>止まれ</span>」 (Berhenti) di jalan itu bentuk perintah. Selain itu, bentuk ini muncul saat bertengkar atau saat pelatih memarahi atlet.</div><div class='gd-h'>Cara membentuknya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Bentuk perintah</b><br><b>Golongan 1 (kata kerja godan)</b>: ganti bunyi terakhir dengan bunyi baris 「え」 pada baris yang sama.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く diganti け → <span class='gd-jp'>行け</span></span><br><span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走れ</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲め</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待て</span></span><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急げ</span></span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang 「る」 di akhir, lalu tambahkan 「ろ」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べろ</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きろ</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ろ</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しろ</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来い</span>（こい）</span></div><div class='gd-sec'><b>Bentuk larangan</b> jauh lebih gampang. Tidak perlu membedakan golongan, cukup <b>tambahkan 「な」 ke bentuk kamus</b>.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くな</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるな</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>するな</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るな</span>（くるな）</span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Memakai bentuk perintah kepada guru, atasan, atau tamu itu sangat tidak sopan. 「<span class='gd-jp'>待て！</span>」 dan 「<span class='gd-jp'>見ろ！</span>」 yang kamu pelajari dari anime jangan dipakai ke orang sungguhan.<br>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span> termasuk golongan 1, jadi bentuknya <span class='gd-jp'>帰れ</span>, <span class='gd-jp'>入れ</span>, bukan 帰ろ atau 入ろ.<br>・<span class='gd-jp'>来い</span> dibaca <b>こい</b>, tapi <span class='gd-jp'>来るな</span> dibaca <b>くるな</b>. Cara bacanya berbeda.<br>・Bentuk perintah mirip dengan bentuk potensial: <span class='gd-jp'>読め</span> artinya \"baca!\", sedangkan <span class='gd-jp'>読める</span> artinya \"bisa membaca\". Bedanya hanya ada atau tidaknya 「る」 di akhir.<br>・「な」 harus selalu menempel pada bentuk kamus: <span class='gd-jp'>行くな</span> artinya \"dilarang pergi\". Kalau kamu membuang ます lalu menambah な, seperti <span class='gd-jp'>行きな</span>, itu justru ungkapan lisan yang artinya \"pergilah\", jadi maknanya berbalik total.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama menyuruh anak tidur:<br><span class='gd-jp'>早く寝ろ！</span>（Cepat tidur!）: paling kasar, langsung dibentak.<br><span class='gd-jp'>早く寝なさい。</span>（Ayo cepat tidur.）: nada orang tua atau guru kepada anak. Ada kesan atasan ke bawahan, tapi tidak kasar.<br><span class='gd-jp'>早く寝てね。</span>（Tidur lebih awal ya.）: permintaan biasa, lembut.</div><div class='gd-sec'>Sama-sama melarang masuk ke ruangan:<br><span class='gd-jp'>入るな！</span>（Jangan masuk!）: paling kasar.<br><span class='gd-jp'>入ってはいけません。</span>（Tidak boleh masuk.）: menyampaikan aturan atau penjelasan larangan, nadanya lebih formal.<br><span class='gd-jp'>入らないでください。</span>（Tolong jangan masuk.）: permintaan yang sopan.</div><div class='gd-warn'>Trik membedakan: yang dibentak itu bentuk perintah dan bentuk larangan; orang dewasa ke anak pakai なさい; menyebut aturan pakai てはいけません; meminta tolong pada orang lain pakai てください atau ないでください.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Bentuk perintah dari <span class='gd-jp'>くれる</span> adalah <span class='gd-jp'>くれ</span>, bukan くれろ. Laki-laki sering bilang <span class='gd-jp'>ちょっと待ってくれ。</span>（Tunggu sebentar ya）, yang terdengar sedikit lebih lembut daripada 「待て」 saja.</div>","n4-57":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「と」 ini artinya kira-kira <b>\"begitu ～, langsung ～\"</b> atau <b>\"kalau ～, pasti ～\"</b>. Setiap kali A terjadi, B <b>selalu</b> ikut terjadi tanpa pengecualian, seperti \"begitu saklar ditekan, lampu menyala\". Karena itu pola ini paling sering dipakai untuk hukum alam, cara mengoperasikan mesin, menunjukkan jalan, dan kebiasaan yang selalu dilakukan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Hukum alam</span>Memang sudah begitu adanya, tidak ada yang bisa mengubahnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>春になると、桜が咲きます。</span>（Begitu musim semi tiba, sakura mekar）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜になると、街の灯りがつきます。</span>（Begitu malam tiba, lampu jalan menyala）</div><div class='gd-sec'><span class='gd-tag'>Mengoperasikan mesin</span>Kalau kamu melakukan tindakan ini, mesin akan bereaksi.</div><div class='gd-ex-line'>・<span class='gd-jp'>このボタンを押すと、ドアが開きます。</span>（Begitu tombol ini ditekan, pintunya terbuka）</div><div class='gd-ex-line'>・<span class='gd-jp'>この鍵を回すと、金庫が開きます。</span>（Kalau kunci ini diputar, brankasnya terbuka）</div><div class='gd-sec'><span class='gd-tag'>Menunjukkan jalan</span>Di Jepang, kalau kamu bertanya arah, kamu akan sering mendengar pola seperti ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>まっすぐ行くと、右に駅があります。</span>（Kalau jalan lurus, stasiunnya ada di sebelah kanan）</div><div class='gd-sec'><span class='gd-tag'>Kebiasaan tetap</span>Setiap kali melakukan A, pasti langsung diikuti B.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は家に帰ると、すぐテレビをつけます。</span>（Begitu ayahku pulang ke rumah, dia langsung menyalakan TV）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan 「と」 pakai <b>bentuk biasa tanpa ます dan tanpa bentuk lampau</b>. Kata kerja paling sering memakai bentuk kamus, dan untuk \"tidak ～\" pakai bentuk ない.<br>Bentuk kamus kata kerja：<span class='gd-pair'><span class='gd-jp'>押す</span> → <span class='gd-jp'>押すと</span></span><br>Bentuk ない kata kerja：<span class='gd-pair'><span class='gd-jp'>急がない</span> → <span class='gd-jp'>急がないと</span></span><br>Kata sifat い langsung disambung：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いと</span></span><br>Kata sifat な dan kata benda harus ditambah だ dulu：<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だと</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>急がないと、遅れるよ。</span>（Kalau tidak cepat, nanti terlambat lho）</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いと、手が冷たくなります。</span>（Kalau cuaca dingin, tangan jadi dingin）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Di belakang 「と」 <b>tidak boleh</b> ada permintaan, perintah, ajakan, atau niat pribadi seperti \"aku akan ～\". Alasannya, 「と」 menyatakan hasil yang terjadi dengan sendirinya, bukan hal yang ingin kamu lakukan.<br>　×<span class='gd-jp'>駅に着くと、電話してください。</span><br>　○<span class='gd-jp'>駅に着いたら、電話してください。</span>（Kalau sudah sampai di stasiun, tolong telepon aku）<br>・Di depan 「と」 selalu pakai <b>bentuk non-lampau (bentuk kamus atau bentuk ない)</b>, bahkan saat membicarakan hal yang sudah lewat. Bentuk lampau hanya diletakkan di akhir kalimat: <span class='gd-jp'>子どものころ、冬になると、よく雪が降りました。</span>（Waktu kecil, begitu musim dingin tiba, salju sering turun）. Kamu tidak boleh bilang 「押したと」.<br>・「と」 juga bisa berarti \"dengan, bersama\" (<span class='gd-jp'>友達と</span>) dan \"bahwa\" (<span class='gd-jp'>と言います</span>). Arti \"begitu ～, langsung ～\" hanya muncul kalau di depannya ada satu tindakan atau kalimat, lalu di belakangnya menyusul hal lain.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>と</b>＝begitu A, langsung B, selalu begitu, dan di belakangnya hanya \"hal yang pasti terjadi\"：<span class='gd-jp'>春になると、桜が咲きます。</span>（Begitu musim semi tiba, sakura mekar）<br><b>たら</b>＝setelah A, baru B. Di belakangnya boleh ada permintaan, ajakan, atau niat pribadi：<span class='gd-jp'>春になったら、花見に行こう。</span>（Kalau musim semi sudah tiba, ayo pergi melihat bunga）<br><b>ば</b>＝menekankan \"asalkan ada syarat A\"：<span class='gd-jp'>このボタンを押せば、ドアが開きます。</span>（Asalkan tombol ini ditekan, pintunya terbuka）<br><b>なら</b>＝menyambung ucapan lawan bicara untuk memberi saran：<span class='gd-jp'>京都へ行くなら、春がいいですよ。</span>（Kalau kamu mau ke Kyoto, musim semi bagus lho）</div><div class='gd-warn'>Trik membedakan: kalau di belakang kamu ingin bilang \"tolong ～\", \"ayo ～\", atau \"aku akan ～\", pakai たら. Kalau di belakang adalah hasil yang \"pasti begitu\", pakai と.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>「と」 juga bisa dipasang di depan 「いい」 untuk menyatakan harapan: <span class='gd-jp'>明日、晴れるといいですね。</span>（Semoga besok cerah ya）. Pemakaian ini akan dibahas di n4-58.</div>","n4-58":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Pola ini setara dengan <b>\"tinggal ～ saja\" atau \"kalau ～ kan beres\"</b>. Pola ini dipakai dalam dua situasi: <b>memberi saran</b> (\"Tanya guru saja kan\") dan <b>berharap</b> (\"Semoga besok cerah\", maksudnya \"aku berharap besok cerah\"). Bagian depannya bisa memakai tiga bentuk pengandaian, yaitu たら、ば、と, lalu diikuti いい.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Memberi saran</span>Kamu bilang ke lawan bicara \"kalau begini, masalahnya beres\". Nadanya santai dan sering dipasangkan dengan 「よ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>医者に相談したらいいですよ。</span>(Konsultasi saja ke dokter)</div><div class='gd-ex-line'>・<span class='gd-jp'>分からなかったら、先生に聞けばいいよ。</span>(Kalau tidak paham, tanya saja ke guru)</div><div class='gd-ex-line'>・<span class='gd-jp'>疲れたときは、少し休むといいですよ。</span>(Kalau lagi capek, sebaiknya istirahat sebentar ya)</div><div class='gd-sec'><span class='gd-tag'>Bertanya harus bagaimana</span>Kalau dijadikan kalimat tanya, artinya \"sebaiknya bagaimana?\". Di sini hampir selalu dipakai たら atau ば, dan ini sangat sering muncul.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅までどう行けばいいですか。</span>(Ke stasiun sebaiknya lewat mana?)</div><div class='gd-ex-line'>・<span class='gd-jp'>何を持っていったらいいですか。</span>(Sebaiknya bawa apa?)</div><div class='gd-sec'><span class='gd-tag'>Berharap</span>Kamu berharap sesuatu terjadi, biasanya hal yang di luar kendalimu. Sering dipasangkan dengan 「ね」 (diucapkan ke lawan bicara) atau 「なあ」 (bicara sendiri). Untuk pemakaian ini, 「といい」 paling sering muncul.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、晴れるといいですね。</span>(Semoga besok cerah ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降らないといいね。</span>(Semoga tidak hujan ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格できたらいいなあ。</span>(Andai saja bisa lulus ujian)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>たら</b>: ubah dulu ke bentuk た, lalu tambahkan ら.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったら</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたら</span></span></div><div class='gd-sec'><b>ば</b>: ubah ke bentuk ば.<br>Kelompok 1 (verba godan): ubah bunyi terakhir menjadi bunyi baris 「え」 di baris yang sama, lalu tambahkan ば.<span class='gd-pair'><span class='gd-jp'>行く</span> → く diganti け → <span class='gd-jp'>行けば</span></span><br>Kelompok 2 (verba ichidan): buang る, lalu tambahkan れば.<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば</span></span><br>Kelompok 3 (する・来る): <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すれば</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば</span>（くれば）</span></div><div class='gd-sec'><b>と</b>: di depannya dipakai <b>bentuk biasa non-lampau</b>, yaitu bentuk kamus atau bentuk ない. Untuk kata sifat-na dan kata benda, tambahkan だ.<br><span class='gd-pair'><span class='gd-jp'>晴れる</span> → <span class='gd-jp'>晴れるといい</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないといい</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気だといい</span></span></div><div class='gd-h'>Ditambah のに: menyayangkan kenyataannya tidak begitu</div><div class='gd-sec'>Kalau akhir kalimat menjadi 「ばいいのに」 atau 「たらいいのに」, artinya \"andai saja ～, tapi kenyataannya tidak\". Nuansanya menyayangkan atau tidak puas.</div><div class='gd-ex-line'>・<span class='gd-jp'>早く春が来ればいいのに。</span>(Andai saja musim semi cepat datang, tapi nyatanya belum)</div><div class='gd-ex-line'>・<span class='gd-jp'>早く言えばいいのに。</span>(Kenapa tidak bilang dari tadi saja)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Sebelum 「と」 tidak boleh memakai bentuk た: <span class='gd-jp'>飲むといい</span> dan <span class='gd-jp'>降らないといい</span> benar, sedangkan <span class='gd-jp'>飲んだといい</span> salah.<br>・「～たらいいですよ」 terasa seperti \"aku kasih tahu caranya\", jadi kalau dipakai ke guru atau atasan agak kurang sopan. Lebih sopan pakai <span class='gd-jp'>〜たらいかがですか</span>.<br>・「～ばいいのに」 kalau ditujukan ke orang lain sering terdengar menggerutu. <span class='gd-jp'>早く言えばいいのに</span> misalnya, seperti sedang menegur lawan bicara, jadi jangan dipakai ke orang yang lebih tua atau atasan.<br>・Untuk \"semoga besok cerah\", jangan diterjemahkan mentah-mentah menjadi 「希望します」. Orang Jepang sehari-hari bilang <span class='gd-jp'>明日晴れるといいですね</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Ketiganya berakhiran 「いい」, tapi artinya berbeda:<br><span class='gd-jp'>薬を飲んだほうがいいですよ。</span>(Sebaiknya kamu minum obat) → <b>ほうがいい</b> adalah nasihat, menyiratkan \"kalau tidak minum, tidak baik\", nadanya lebih kuat.<br><span class='gd-jp'>薬を飲んだらいいですよ。</span>(Minum obat saja) → <b>たらいい</b> memberi satu solusi dengan santai.<br><span class='gd-jp'>薬を飲んでもいいですよ。</span>(Kamu boleh minum obat) → <b>てもいい</b> adalah izin, bukan saran.</div><div class='gd-warn'>Trik cepat: \"sebaiknya ～\" pakai ほうがいい, \"～ saja\" pakai たらいい, \"boleh ～\" pakai てもいい.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Bentuk lampau <span class='gd-jp'>〜ばよかった</span> artinya \"tahu begitu dulu ～\", dipakai untuk menyatakan penyesalan: <span class='gd-jp'>もっと勉強すればよかった。</span>(Tahu begitu dulu aku belajar lebih giat)</div>","n4-64":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜させていただきます」 setara dengan <b>\"izinkan saya ～\" atau \"kalau begitu saya ～ ya\"</b>. Pola ini dipakai untuk hal yang akan dilakukan oleh <b>dirimu sendiri</b>, tapi nadanya sangat merendah, seolah-olah \"saya melakukannya karena Anda mengizinkan\". Sering terdengar saat rapat, presentasi, atau bicara dengan atasan dan pelanggan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Presentasi, acara formal</span>Diucapkan lebih dulu sebelum mulai menjelaskan, memperkenalkan diri, atau mempresentasikan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>では、説明させていただきます。</span>(Kalau begitu, izinkan saya menjelaskan)</div><div class='gd-ex-line'>・<span class='gd-jp'>自己紹介させていただきます。</span>(Izinkan saya memperkenalkan diri)</div><div class='gd-sec'><span class='gd-tag'>Hal yang berdampak pada orang lain</span>Untuk hal yang memengaruhi pihak lain, seperti izin tidak masuk, pulang lebih awal, atau memakai barang orang lain, pola ini membuat ucapanmu lebih sopan.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休ませていただきます。</span>(Besok izinkan saya libur)</div><div class='gd-sec'><span class='gd-tag'>Pengumuman toko</span>Sering juga terlihat di pengumuman yang ditempel di depan toko.</div><div class='gd-ex-line'>・<span class='gd-jp'>本日は休ませていただきます。</span>(Hari ini kami tutup)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah dulu verbanya ke bentuk kausatif (\"membuat/membiarkan melakukan ～\"), lalu ke bentuk て: 「〜させて／〜せて」, dan tambahkan <span class='gd-jp'>いただきます</span> di belakangnya.</div><div class='gd-h'>Cara mengubah: lihat dulu kelompok verbanya</div><div class='gd-sec'><b>Kelompok 1 (verba godan)</b>: ubah bunyi terakhir menjadi bunyi baris 「あ」 di baris yang sama, tambahkan 「せて」, lalu いただきます.<br><span class='gd-pair'><span class='gd-jp'>休む</span> → む diganti ま → <span class='gd-jp'>休ませていただきます</span></span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせていただきます</span></span><br>Hati-hati dengan akhiran 「う」, yang diganti menjadi 「わ」: <span class='gd-pair'><span class='gd-jp'>使う</span> → <span class='gd-jp'>使わせていただきます</span></span></div><div class='gd-sec'><b>Kelompok 2 (verba ichidan)</b>: buang 「る」 di akhir, tambahkan 「させて」, lalu いただきます.<br><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えさせていただきます</span></span></div><div class='gd-sec'><b>Kelompok 3 (hanya dua, hafalkan saja)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させていただきます</span></span>（<span class='gd-jp'>説明する</span> menjadi <span class='gd-jp'>説明させていただきます</span>）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させていただきます</span>（こさせて）</span>, tapi bentuk ini jarang dipakai.</div><div class='gd-sec'>Ringkasnya: <b>hanya kelompok 2 dan 3 (する → させて、来る → 来させて) yang punya 「さ」</b>. Kelompok 1 langsung \"bunyi baris あ + せて\".</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Jangan menambahkan 「さ」 pada kelompok 1: yang benar <span class='gd-jp'>休ませていただきます</span>, bukan 休まさせていただきます; yang benar <span class='gd-jp'>読ませていただきます</span>, bukan 読まさせて. Kesalahan ini sering dilakukan bahkan oleh orang Jepang sendiri, tapi di ujian tetap dihitung salah.<br>・<span class='gd-jp'>使う</span> menjadi <span class='gd-jp'>使わせて</span>, bukan 使あせて.<br>・Pola ini selalu untuk hal yang dilakukan oleh <b>dirimu sendiri</b>, tidak bisa dipakai untuk orang lain.<br>・Sebenarnya pola ini bukan untuk \"bertanya\", melainkan lebih seperti <b>memberi tahu</b> dengan sopan bahwa \"saya akan melakukan ini\". Kalau memang ingin meminta persetujuan, pakai 「〜させていただけませんか」 di bawah.<br>・Jangan dipakai untuk segala hal: kalau urusannya tidak menyangkut lawan bicara dan tidak perlu persetujuan siapa pun, terus-terusan bilang 「させていただきます」 terdengar bertele-tele. Cukup pakai 「〜ます」 biasa.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk \"hari ini mau pulang lebih awal\", ada tiga cara bicara ke atasan:<br><b>させていただきます</b> = memberi tahu dengan sopan, hampir seperti sudah diputuskan:<br><span class='gd-jp'>今日は早く帰らせていただきます。</span>(Hari ini izinkan saya pulang lebih awal)<br><b>させてください</b> = meminta lawan bicara mengizinkanmu, lebih langsung:<br><span class='gd-jp'>今日は早く帰らせてください。</span>(Hari ini tolong biarkan saya pulang lebih awal)<br><b>させていただけませんか</b> = benar-benar bertanya, lawan bicara boleh menolak, paling sopan:<br><span class='gd-jp'>今日は早く帰らせていただけませんか。</span>(Bolehkah saya pulang lebih awal hari ini?)</div><div class='gd-warn'>Trik cepat: akhiran 「ます」 berarti <b>memberi tahu</b>, 「ください」 berarti <b>memohon</b>, dan hanya 「ませんか」 yang benar-benar <b>bertanya</b>. Selama izin belum kamu dapatkan, 「〜させていただけませんか」 adalah pilihan paling aman.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Lanjutkan ke \"bahasa merendah (謙譲語)\", yaitu ungkapan khusus yang merendahkan diri sendiri seperti <span class='gd-jp'>参ります</span> dan <span class='gd-jp'>申します</span>. Ungkapan-ungkapan ini sering muncul bersama 「させていただきます」.</div>","n4-71":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>Dalam bahasa Indonesia kita bilang \"tercium aroma harum\" atau \"terdengar suara aneh\". Bahasa Jepang tidak pakai「ある」, tapi <b>「Nomina＋がする」</b>. Artinya ada suara, rasa, atau bau yang muncul sendiri dan kamu menangkapnya. Bentuk sopannya「がします」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Hal yang dirasakan (nomina) ＋ が ＋ します (dengan teman pakai する).<br>Biasanya ada kata sifat di depannya untuk menjelaskan suara atau baunya seperti apa:<br><span class='gd-pair'><span class='gd-jp'>匂い</span> → <span class='gd-jp'>いい匂いがします</span></span>(tercium bau harum)<br><span class='gd-pair'><span class='gd-jp'>音</span> → <span class='gd-jp'>変な音がします</span></span>(terdengar suara aneh)</div><div class='gd-h'>Yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>Suara</span><span class='gd-jp'>音</span> (suara benda), <span class='gd-jp'>声</span> (suara orang atau hewan)</div><div class='gd-ex-line'>・<span class='gd-jp'>外で変な音がします。</span>(Ada suara aneh di luar)</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋から子どもの声がする。</span>(Terdengar suara anak kecil dari kamar sebelah)</div><div class='gd-sec'><span class='gd-tag'>Bau</span><span class='gd-jp'>匂い</span>, <span class='gd-jp'>香り</span> (aroma harum, kesannya lebih halus)</div><div class='gd-ex-line'>・<span class='gd-jp'>台所からいい匂いがする。</span>(Tercium bau harum dari dapur)</div><div class='gd-sec'><span class='gd-tag'>Rasa</span><span class='gd-jp'>味</span> yang kamu rasakan saat makan atau minum</div><div class='gd-ex-line'>・<span class='gd-jp'>このお茶、レモンの味がする。</span>(Teh ini rasanya seperti lemon)</div><div class='gd-sec'><span class='gd-tag'>Kesan</span><span class='gd-jp'>感じがする</span> artinya \"memberi kesan ～\", sedangkan <span class='gd-jp'>気がする</span> artinya \"aku merasa ～\". Di depan <span class='gd-jp'>気がする</span> kamu bisa langsung memasang satu kalimat utuh (kata kerjanya bentuk biasa, yaitu tanpa ます).</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人は優しい感じがします。</span>(Orang itu kelihatannya baik hati)</div><div class='gd-ex-line'>・<span class='gd-jp'>前に会った気がします。</span>(Rasanya kita pernah bertemu sebelumnya)</div><div class='gd-h'>Hati-hati di sini</div><div class='gd-warn'>・Partikelnya <b>が</b>, bukan を: yang benar <span class='gd-jp'>音がする</span>, tidak boleh「音をする」.<br>・Untuk bau atau suara yang sedang kamu tangkap sekarang, pakai がする. Biasanya tidak bilang「いい匂いがあります」.<br>・Dalam bahasa Indonesia kita sering bilang \"<b>aku</b> mencium bau harum\", tapi dalam bahasa Jepang pelakunya adalah <b>bau itu sendiri</b>, jadi tidak bilang「私はいい匂いがします」. Kalau mau bilang di mana ada baunya, katakan <span class='gd-jp'>この部屋は変な匂いがします</span> (kamar ini bau aneh).<br>・<b>Yang ditangkap mata tidak pakai がする</b>: warna dan bentuk tidak bisa begini, jadi tidak boleh bilang「きれいな色がします」.<br>・Di depannya harus nomina: tidak boleh「甘いがします」, yang benar <span class='gd-jp'>甘い匂いがします</span> atau <span class='gd-jp'>甘い味がします</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>音がする vs 聞こえる</b><br><span class='gd-jp'>外で音がする。</span>(Ada suara di luar): fokusnya <b>ada suara yang muncul</b>.<br><span class='gd-jp'>外の音が聞こえる。</span>(Suara di luar terdengar): fokusnya <b>bisa terdengar atau tidak</b>, jadi sering dipakai dalam situasi seperti <span class='gd-jp'>よく聞こえない</span> (kurang jelas terdengar).</div><div class='gd-sec'><b>気がする vs と思う</b><br><span class='gd-jp'>彼は来ないと思います。</span>(Menurutku dia tidak akan datang): pikiran atau penilaian yang lebih jelas.<br><span class='gd-jp'>彼は来ない気がします。</span>(Entah kenapa aku merasa dia tidak akan datang): susah dijelaskan, hanya firasat, nadanya kurang yakin.</div><div class='gd-warn'>Tips memilih: \"ada suara atau bau\" pakai がする, \"terdengar atau tidak\" pakai 聞こえる. Pikiran yang kamu yakini pakai と思う, kalau hanya firasat pakai 気がする.</div>","n4-72":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜さ」mengubah kata sifat menjadi <b>nomina</b>, mirip imbuhan ke-an dalam bahasa Indonesia: \"tinggi\" jadi \"ketinggian\", \"dalam\" jadi \"kedalaman\". <span class='gd-jp'>高い</span> artinya \"tinggi\", sedangkan <span class='gd-jp'>高さ</span> artinya \"ketinggian\". Dipakai untuk bilang sesuatu itu <b>seberapa ～</b>, atau <b>kesan ～ yang ditimbulkannya</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata sifat-い</b>: buang 「い」 di akhir, lalu tambah 「さ」.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → buang い → <span class='gd-jp'>高さ</span></span>(ketinggian)<br><span class='gd-pair'><span class='gd-jp'>深い</span> → <span class='gd-jp'>深さ</span></span>(kedalaman)<span class='gd-pair'><span class='gd-jp'>重い</span> → <span class='gd-jp'>重さ</span></span>(berat)<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒さ</span></span>(dinginnya cuaca)<span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きさ</span></span>(ukuran)</div><div class='gd-sec'><b>Kata sifat-な</b>: langsung tambah 「さ」, tanpa な di tengah.<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利さ</span></span>(kepraktisan)<span class='gd-pair'><span class='gd-jp'>親切</span> → <span class='gd-jp'>親切さ</span></span>(keramahan)<span class='gd-pair'><span class='gd-jp'>大切</span> → <span class='gd-jp'>大切さ</span></span>(pentingnya sesuatu)</div><div class='gd-sec'><b>Yang perlu dihafal khusus</b>:<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさ</span></span>(kelebihan, sisi baik. Karena <span class='gd-jp'>いい</span> aslinya berasal dari <span class='gd-jp'>よい</span>, tidak bilang いいさ)<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静けさ</span></span>(ketenangan. Biasanya tidak bilang 静かさ)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Angka dan ukuran</span>Untuk hal yang bisa diukur seperti tinggi, panjang, dan berat. Setelahnya sering ada angka atau「どのくらい」.</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山の高さは3776メートルです。</span>(Ketinggian Gunung Fuji adalah 3776 meter)</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋の広さはどのくらいですか。</span>(Kira-kira seluas apa kamar ini?)</div><div class='gd-sec'><span class='gd-tag'>Kesan dan sifat</span>Untuk menyatakan seberapa kuat kesan sesuatu, atau kelebihan dan ciri khasnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>北海道の冬の寒さにびっくりしました。</span>(Aku kaget dengan dinginnya musim dingin di Hokkaido)</div><div class='gd-ex-line'>・<span class='gd-jp'>病気になって、健康の大切さが分かりました。</span>(Setelah sakit, aku baru sadar betapa pentingnya kesehatan)</div><div class='gd-ex-line'>・<span class='gd-jp'>この店のよさは安いところです。</span>(Kelebihan toko ini adalah harganya murah)</div><div class='gd-ex-line'>・<span class='gd-jp'>夜の静けさが好きです。</span>(Aku suka ketenangan malam hari)</div><div class='gd-h'>Hati-hati di sini</div><div class='gd-warn'>・い harus dibuang: yang benar <span class='gd-jp'>高さ</span>, bukan 高いさ.<br>・Kata sifat-な tidak perlu な: yang benar <span class='gd-jp'>便利さ</span>, bukan 便利なさ.<br>・Setelah ditambah さ, kata itu sudah jadi nomina. Di depannya disambung dengan「の」, di belakangnya bisa「は・が・を・に」: <span class='gd-jp'>冬の寒さ</span>, bukan 冬は寒さ.<br>・「高さ」「重さ」「大きさ」adalah <b>ukuran yang netral</b>, sama seperti \"ketinggian\" dalam bahasa Indonesia. Meski gunungnya rendah, kamu tetap bertanya dengan <span class='gd-jp'>高さ</span>, tidak berubah jadi 低さ.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Kamu pasti sudah pernah belajar <span class='gd-jp'>楽しみ</span>. Kata itu dan <span class='gd-jp'>楽しさ</span> sama-sama berasal dari <span class='gd-jp'>楽しい</span>, tapi artinya berbeda.<br><b>楽しさ</b> = seberapa menyenangkan, kesenangan itu sendiri: <span class='gd-jp'>日本語の楽しさが分かりました。</span>(Aku jadi tahu serunya belajar bahasa Jepang)<br><b>楽しみ</b> = penantian, hal yang dinanti-nantikan: <span class='gd-jp'>旅行を楽しみにしています。</span>(Aku sangat menantikan perjalanan ini)</div><div class='gd-warn'>Tips memilih: untuk tingkat seperti \"seasyik apa, sedingin apa, sepenting apa\" pakai さ. Untuk \"menantikan\" pakai <span class='gd-jp'>楽しみ</span>.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Pola yang berguna untuk menanyakan ukuran: <span class='gd-jp'>〜の長さはどのくらいですか。</span>(Kira-kira berapa panjang ～?) Ganti 長さ dengan <span class='gd-jp'>重さ</span>, <span class='gd-jp'>大きさ</span>, atau <span class='gd-jp'>深さ</span>, dan kamu bisa menanyakan berbagai hal.</div>","n4-69":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ずに」adalah <b>versi formal</b> dari 「〜ないで」, artinya \"tanpa ～, langsung ～\" atau \"tidak ～ melainkan ～\". Mirip dengan bahasa Indonesia: dalam percakapan kita bilang \"pergi tanpa bilang apa-apa\", sedangkan dalam tulisan jadi \"pergi tanpa pamit\". Artinya sama, hanya saja lebih baku dan terkesan lebih elegan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tidak melakukan A, langsung B</span>Hal yang seharusnya dilakukan tidak dilakukan, dan langsung lanjut ke hal berikutnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ご飯を食べずに出かけた。</span>(Berangkat tanpa sarapan)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にも言わずに会社を辞めた。</span>(Keluar dari perusahaan tanpa memberi tahu siapa pun)</div><div class='gd-sec'><span class='gd-tag'>Bukan A, tapi B</span>Meninggalkan satu cara dan menggantinya dengan cara lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>バスに乗らずに、歩いて帰った。</span>(Tidak naik bus, pulang jalan kaki)</div><div class='gd-h'>Cara membentuknya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ない dulu, lalu buang 「ない」 dan ganti dengan 「ず」 atau 「ずに」.</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>:<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かず</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わず</span></span><br><span class='gd-pair'><span class='gd-jp'>持つ</span> → <span class='gd-jp'>持たず</span></span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>:<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べず</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ず</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せず</span></span> (bukan しず)<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ず</span>（こず）</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Secara umum ini terkesan tulisan, tapi ada beberapa ungkapan yang juga sering dipakai orang Jepang dalam percakapan sehari-hari. Hafalkan saja satu kalimat utuhnya:</div><div class='gd-ex-line'>・<span class='gd-jp'>遠慮せずに食べてください。</span>(Jangan sungkan, silakan dimakan)</div><div class='gd-ex-line'>・<span class='gd-jp'>気にせずに休んでね。</span>(Jangan dipikirkan, istirahat yang cukup ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>思わず笑ってしまった。</span>(Tanpa sadar aku jadi tertawa)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<b>する menjadi せず</b>, bukan しず: <span class='gd-jp'>勉強せずに</span>.<br>・Kata kerja golongan 1 yang berakhiran 「う」 berubah jadi 「わ」 di bentuk ない: <span class='gd-jp'>言わず</span>, <span class='gd-jp'>買わず</span>, bukan 言あず.<br>・<span class='gd-jp'>来ず</span> dibaca <b>こず</b>, bukan きず.<br>・Tidak bisa dipakai untuk meminta orang lain: untuk \"tolong jangan ～\" hanya bisa pakai <span class='gd-jp'>食べないでください</span>. Tidak ada bentuk 「食べずにください」.<br>・Saat mengobrol dengan teman, kata kerja biasa kebanyakan memakai 「ないで」. Kalau semuanya pakai 「ずに」, bunyinya seperti sedang membaca naskah. Ungkapan tetap di atas adalah pengecualian.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ないで</b> = versi percakapan: <span class='gd-jp'>傘を持たないで出かけた。</span>(Pergi tanpa membawa payung)<br><b>ずに</b> = versi formal/tulisan, artinya persis sama: <span class='gd-jp'>傘を持たずに出かけた。</span>(Pergi tanpa membawa payung)<br>Dalam tulisan, kamu juga sering menemukan 「ず」 yang langsung diikuti tanda koma. Biasanya artinya \"karena tidak ～\", mirip dengan 「なくて」: <span class='gd-jp'>バスが来ず、遅刻してしまった。</span>(Bus tidak datang, akhirnya terlambat)</div><div class='gd-warn'>Tips cepat: kalau bertemu 「ずに」, ganti saja dalam kepala dengan 「ないで」, maka kamu langsung paham. Kalau ragu saat bicara, pakai 「ないで」 saja, itu yang paling aman.</div>","n4-70":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「こと」kira-kira berarti <b>\"hal/kegiatan ～\"</b>. Dalam bahasa Indonesia kita bisa langsung bilang \"membaca itu seru\" dengan kata kerja sebagai subjek. Dalam bahasa Jepang tidak bisa begitu: kata kerja tidak bisa langsung jadi subjek. Kamu perlu menambahkan 「こと」 di belakangnya untuk \"membungkus\" \"membaca\" menjadi \"hal membaca\", baru bisa dipakai sebagai subjek atau jawaban dalam kalimat.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sebagai subjek kalimat</span>Letakkan sebelum 「は」「が」, lalu lanjutkan dengan penjelasannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日運動することは大切です。</span>(Berolahraga setiap hari itu penting)</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻しないことが大切です。</span>(Tidak terlambat itu penting)</div><div class='gd-sec'><span class='gd-tag'>Sebagai jawaban</span>Untuk \"hobiku adalah ～\" atau \"impianku adalah ～\", kalau yang mengisi \"～\" adalah suatu tindakan, pakai 「～ことです」.</div><div class='gd-ex-line'>・<span class='gd-jp'>私の趣味は写真を撮ることです。</span>(Hobiku adalah memotret)</div><div class='gd-ex-line'>・<span class='gd-jp'>夢は日本で働くことです。</span>(Impianku adalah bekerja di Jepang)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja disambung langsung, tanpa perubahan bentuk: <span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むこと</span></span><br>\"Tidak melakukan\" pakai bentuk ない: <span class='gd-pair'><span class='gd-jp'>読まない</span> → <span class='gd-jp'>読まないこと</span></span><br>\"Pernah melakukan\" pakai bentuk た: <span class='gd-pair'><span class='gd-jp'>読んだ</span> → <span class='gd-jp'>読んだこと</span></span><br>Kata sifat juga bisa disambung. Di sini artinya lebih mirip \"hal yang ～\": <span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しいこと</span></span> (hal yang menyenangkan). Untuk kata sifat-な, jangan lupa menambahkan な: <span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きなこと</span></span> (hal yang disukai)</div><div class='gd-sec'>Sebenarnya kamu sudah sering bertemu dengannya: 「こと」 di dalam <span class='gd-jp'>ことができます</span>, <span class='gd-jp'>たことがあります</span>, dan <span class='gd-jp'>ことにします</span> semuanya adalah 「こと」 yang berarti \"hal ～\" ini.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Mengikuti intuisi bahasa Indonesia dan langsung memakai kata kerja sebagai subjek: <span class='gd-jp'>本を読むが好きです</span> itu salah. Di tengah harus ada <span class='gd-jp'>こと</span> atau <span class='gd-jp'>の</span>: <span class='gd-jp'>本を読むことが好きです</span>.<br>・Lupa menambahkan な pada kata sifat-な: yang benar <span class='gd-jp'>好きなこと</span>, bukan 好きこと, dan bukan juga 好きだこと.<br>・「名詞＋のこと」 artinya lain, yaitu \"tentang ～\": <span class='gd-jp'>彼のことが好きです</span> berarti \"Aku suka dia (orangnya)\". Ini berbeda dengan fungsi mengubah tindakan menjadi kata benda di sini, jadi jangan dicampur.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>「の」 juga bisa mengubah tindakan menjadi \"hal ～\". Sering kali keduanya bisa dipakai, tetapi <b>ada posisi yang hanya cocok untuk salah satunya</b>. Bukan sekadar \"こと lebih formal\".</div><div class='gd-sec'><span class='gd-tag'>Keduanya boleh</span>Saat sebelumnya ada penilaian seperti 「好き」「大切」「難しい」.</div><div class='gd-ex-line'>・<span class='gd-jp'>本を読むのが好きです。</span>(Aku suka membaca buku: lebih sering dipakai dalam percakapan)</div><div class='gd-ex-line'>・<span class='gd-jp'>本を読むことが好きです。</span>(Aku suka membaca buku: sedikit lebih formal)</div><div class='gd-sec'><span class='gd-tag'>Hanya こと</span>Di akhir kalimat dengan pola 「～は～ことです」, dan pola tetap seperti ことができます.</div><div class='gd-ex-line'>・<span class='gd-jp'>趣味は本を読むことです。</span>(Hobiku adalah membaca buku)</div><div class='gd-sec'>Kalau diganti 「のです」, jadi tidak tepat. 「の」 di sini akan terdengar sebagai 「のです」 yang bernuansa menjelaskan, sehingga kalimatnya sangat janggal. Karena itu akhir kalimat harus pakai 「ことです」. Begitu juga <span class='gd-jp'>日本語を話すことができます</span>, tidak bisa diganti dengan の.</div><div class='gd-sec'><span class='gd-tag'>Hanya の</span>Saat kamu melihat atau mendengar langsung suatu tindakan sedang terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が走るのを見ました。</span>(Aku melihat anjing berlari)</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋で誰かが歌っているのが聞こえます。</span>(Terdengar ada orang menyanyi di kamar sebelah)</div><div class='gd-sec'>Di sini, <span class='gd-jp'>走ることを見ました</span> dan <span class='gd-jp'>歌っていることが聞こえます</span> sama-sama tidak bisa dipakai.</div><div class='gd-warn'>Tips cepat: sebelum 「～です」 di akhir kalimat dan dalam pola tetap seperti ことができる, pakai <b>こと</b>. Untuk tindakan yang kamu lihat atau dengar langsung, pakai <b>の</b>. Untuk 「好き」「大切」 yang keduanya boleh, の terdengar lebih luwes saat mengobrol.</div>","n4-73":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ことがあります」artinya <b>“kadang-kadang ~”</b>. Maksudnya, hal itu <b>tidak terjadi setiap kali, tapi sesekali bisa terjadi</b>. Mirip tulisan “mungkin terjadi keterlambatan” di pengumuman stasiun atau halaman belanja online, yang mengingatkanmu bahwa “situasi seperti ini memang bisa terjadi”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kadang <b>melakukan</b>: bentuk kamus＋ことがあります<br><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れることがあります</span></span>（kadang terlambat）<br>Kadang <b>tidak</b> melakukan: bentuk ない＋ことがあります<br><span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べないことがあります</span></span>（kadang tidak makan）<br>Kalau bicara dengan teman, pakai bentuk biasa <span class='gd-jp'>ことがある</span>, artinya sama.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menceritakan kebiasaan sendiri</span>Tidak setiap hari, tapi sesekali terjadi. Sering muncul bersama <span class='gd-jp'>ときどき</span>（kadang-kadang）dan <span class='gd-jp'>たまに</span>（sesekali）.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいとき、朝ご飯を食べないことがあります。</span>（Kalau sedang sibuk, kadang aku tidak sarapan）</div><div class='gd-ex-line'>・<span class='gd-jp'>たまに電車で寝てしまうことがある。</span>（Sesekali aku ketiduran di kereta）</div><div class='gd-sec'><span class='gd-tag'>Pengingat dan pengumuman</span>Sering dipakai di toko, stasiun, dan deskripsi produk untuk memberi tahu dulu: “hal seperti ini bisa terjadi, ya”.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の日は、バスが遅れることがあります。</span>（Kalau hujan, bus kadang terlambat）</div><div class='gd-ex-line'>・<span class='gd-jp'>商品の色が写真と違うことがあります。</span>（Warna produk kadang berbeda dari fotonya）</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Hal yang terjadi <b>setiap hari, pasti, atau selalu</b> tidak bisa memakai pola ini. <span class='gd-jp'>毎日コーヒーを飲むことがあります</span> itu salah. Kalau minum setiap hari, cukup bilang <span class='gd-jp'>毎日コーヒーを飲みます</span>.<br>・Kata “bisa” atau “akan” dalam bahasa Indonesia punya banyak arti, dan tidak semuanya bisa diganti dengan ことがあります. “Saya bisa bicara bahasa Jepang” adalah <span class='gd-jp'>日本語が話せます</span>; “Besok akan hujan” adalah <span class='gd-jp'>明日は雨が降るでしょう</span>. Hanya untuk arti “<b>kadang bisa terjadi</b>” kamu pakai ことがあります.<br>・Bagian depannya harus bentuk kamus atau bentuk ない. Kalau ditulis dengan bentuk た, artinya berubah total. Ini dijelaskan di bawah.<br>・Kamu juga akan sering mendengar <span class='gd-jp'>遅れることもあります</span>. Kalau が diganti も, nuansanya jadi “<b>bisa juga</b> ~” yang lebih halus, dan sering dipakai di pengumuman.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>Bentuk kamus＋ことがある</b>＝kadang ~ (kecenderungan saat ini)<br><span class='gd-jp'>この電車は遅れることがあります。</span>（Kereta ini kadang terlambat）<br><b>Bentuk た＋ことがある</b>＝pernah ~ (pengalaman masa lalu)<br><span class='gd-jp'>この電車は遅れたことがあります。</span>（Kereta ini pernah terlambat）<br>Bedanya hanya satu bentuk kata: yang pertama berarti “biasanya sesekali begitu”, yang kedua berarti “dulu pernah terjadi (sekali atau lebih)”.</div><div class='gd-sec'><b>かもしれません</b>＝menebak apakah hal itu terjadi pada <b>satu kali tertentu</b><br><span class='gd-jp'>明日は電車が遅れるかもしれません。</span>（Besok kereta mungkin terlambat）<br><b>ことがあります</b>＝menjelaskan keadaan <b>biasa</b>, yang sesekali bisa kamu temui<br><span class='gd-jp'>雪の日は電車が遅れることがあります。</span>（Kalau turun salju, kereta kadang terlambat）</div><div class='gd-warn'>Trik cepat: “pernah ~” pakai bentuk た＋ことがある; “biasanya kadang ~” pakai bentuk kamus＋ことがある; “kali ini mungkin ~” pakai かもしれません.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kata benda juga bisa dipakai. Tambahkan <span class='gd-jp'>の</span> setelah kata benda: <span class='gd-jp'>この時間は満席のことがあります。</span>（Jam segini kadang penuh）</div>","n4-74":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, kalau mau sopan kepada orang yang lebih tua, kita mengganti “kamu” dengan “Bapak/Ibu” atau “Anda”. Bahasa Jepang punya trik yang mirip: <b>ubah tindakan orang yang lebih tua, atasan, atau tamu ke bentuk “れる・られる”</b>, maka terdengar hormat.<br>Misalnya “Direktur sudah pulang”: biasanya <span class='gd-jp'>帰りました</span>, dan versi hormatnya <span class='gd-jp'>帰られました</span>. Ini bentuk keigo yang paling mudah untuk pemula, tingkat kesopanannya tergolong ringan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menceritakan tindakan orang yang dihormati</span>Saat membicarakan apa yang dilakukan guru atau atasan kepada orang lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長はもう帰られました。</span>（Kepala bagian sudah pulang）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長は来週、大阪に出張されます。</span>（Direktur minggu depan dinas ke Osaka）</div><div class='gd-sec'><span class='gd-tag'>Bertanya langsung kepada lawan bicara</span>Langsung menanyakan kepada guru atau tamu apa yang akan mereka lakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生はいつ日本へ行かれますか。</span>（Kapan Bapak/Ibu guru akan pergi ke Jepang?）</div><div class='gd-ex-line'>・<span class='gd-jp'>何を飲まれますか。</span>（Anda mau minum apa?）</div><div class='gd-h'>Cara mengubahnya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'>Kabar baik: bentuknya <b>sama persis dengan bentuk pasif (受身形)</b>, jadi kalau kamu sudah bisa bentuk pasif, kamu sudah bisa ini.</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: ganti bunyi terakhir dengan bunyi baris あ yang sama, lalu tambahkan「れる」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く jadi か → <span class='gd-jp'>行かれる</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読まれる</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話される</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰られる</span></span><br>Yang berakhiran「う」diganti jadi <b>わ</b>, bukan あ: <span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会われる</span></span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang「る」di akhir, lalu tambahkan「られる」.<br><span class='gd-pair'><span class='gd-jp'>出かける</span> → <span class='gd-jp'>出かけられる</span></span><span class='gd-pair'><span class='gd-jp'>始める</span> → <span class='gd-jp'>始められる</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span>（<span class='gd-pair'><span class='gd-jp'>出発する</span> → <span class='gd-jp'>出発される</span></span>）、<span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>Saat berbicara, biasanya disambung lagi ke bentuk ます: <span class='gd-pair'><span class='gd-jp'>行かれる</span> → <span class='gd-jp'>行かれます</span></span>, dan bentuk lampaunya <span class='gd-jp'>行かれました</span>.</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Hanya dipakai untuk <b>orang lain</b>. Memakai bentuk hormat untuk tindakan sendiri itu aneh. <span class='gd-jp'>私は明日行かれます</span> itu salah, yang benar <span class='gd-jp'>私は明日行きます</span>.<br>・Saat bicara dengan orang luar tentang <b>keluarga sendiri</b>, juga tidak dipakai. Jangan bilang <span class='gd-jp'>父は帰られました</span>, cukup <span class='gd-jp'>父は帰りました</span>.<br>・<span class='gd-jp'>会う</span> jadi <span class='gd-jp'>会われる</span>, bukan「あれる」.<br>・Bentuk hormat golongan 2 dan <span class='gd-jp'>来る</span> kebetulan sama dengan bentuk potensial (bisa ~): <span class='gd-jp'>来られます</span> bisa berarti “Anda akan datang” atau “bisa datang”. Agar tidak salah paham, orang Jepang sering memakai ungkapan hormat khusus, misalnya <span class='gd-jp'>来る</span> jadi <span class='gd-jp'>いらっしゃる</span>, <span class='gd-jp'>食べる</span> jadi <span class='gd-jp'>召し上がる</span>, <span class='gd-jp'>見る</span> jadi <span class='gd-jp'>ご覧になる</span>.<br>・Jangan menumpuk dua jenis keigo sekaligus. <span class='gd-jp'>お帰りになられる</span> memang sering terdengar, tapi dianggap berlebihan dan keliru. Pilih salah satu saja.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>Bentuk hormat</b>＝orang yang dihormati melakukan hal itu <b>sendiri</b>, dan tidak ada yang “di-” apa-apa dalam kalimat:<br><span class='gd-jp'>部長が帰られました。</span>（Kepala bagian sudah pulang）<br><b>Bentuk pasif</b>＝ada yang <b>“di-”</b> dikenai tindakan, dan pelakunya sering diberi「に」:<br><span class='gd-jp'>部長に怒られました。</span>（Aku dimarahi kepala bagian）<br><b>Bentuk potensial</b>＝menanyakan <b>“bisa atau tidak”</b>:<br><span class='gd-jp'>先生は刺身が食べられますか。</span>（Apakah Bapak/Ibu guru bisa makan sashimi?）<br>Sama-sama「られます」, artinya ditentukan oleh konteks.</div><div class='gd-warn'>Trik cepat: kalau subjeknya orang yang dihormati, dia sendiri yang melakukan, dan tidak ada arti “di-” maupun “bisa atau tidak”, berarti itu bentuk hormat.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Ungkapan yang lebih sopan adalah “お＋bentuk ます tanpa ます＋になる”: <span class='gd-jp'>社長はお帰りになりました。</span>（Direktur sudah pulang）. Ini lebih santun daripada <span class='gd-jp'>帰られました</span>, jadi lanjutkan ke pelajaran “尊敬語”.</div>","n4-75":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, kita bilang “minum, tidak minum, bisa minum, diminum, menyuruh minum” dengan menambah kata di sekitar “minum”. Bahasa Jepang berbeda: ia <b>mengubah ekor kata kerjanya</b>, dan cara mengubahnya tergantung kata kerja itu termasuk golongan yang mana. Jadi bentuk apa pun yang kamu pelajari, <b>langkah pertamanya selalu menggolongkan dulu</b>. Kalau golongannya benar, sisanya tinggal pakai aturan.</div><div class='gd-h'>Langkah 1: Tentukan golongan kata kerjanya</div><div class='gd-sec'>Lihat bentuk kamus kata kerjanya (bentuk dasar yang belum berubah dan bisa kamu cari di kamus, misalnya <span class='gd-jp'>飲む</span>、<span class='gd-jp'>食べる</span>), lalu tanyakan tiga pertanyaan ini secara berurutan:<br><b>1. Apakah itu する atau 来る?</b> Kalau ya, berarti <b>Golongan 3 (する・来る)</b>. Bentuk “kata benda＋する” seperti <span class='gd-jp'>勉強する</span> dan <span class='gd-jp'>掃除する</span> juga termasuk golongan ini.<br><b>2. Apakah huruf terakhirnya bukan る?</b> Kalau begitu, seperti <span class='gd-jp'>飲む</span>、<span class='gd-jp'>書く</span>、<span class='gd-jp'>買う</span>、<span class='gd-jp'>話す</span>, semuanya <b>Golongan 1 (kata kerja godan)</b>.<br><b>3. Kalau berakhir る, dengarkan bunyi sebelum る:</b><br>Kalau bunyi sebelumnya “i” atau “e”, biasanya <b>Golongan 2 (kata kerja ichidan)</b>: <span class='gd-jp'>食べる</span> (べ = be), <span class='gd-jp'>起きる</span> (き = ki), <span class='gd-jp'>見る</span> (み = mi).<br>Kalau bunyi sebelumnya “a, u, o”, berarti <b>Golongan 1</b>: <span class='gd-jp'>わかる</span>、<span class='gd-jp'>作る</span>、<span class='gd-jp'>乗る</span>.<br>Di langkah 3 ada beberapa pengecualian: <span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span>、<span class='gd-jp'>要る</span> kelihatannya Golongan 2, padahal <b>Golongan 1</b>. Hafalkan saja langsung.</div><div class='gd-h'>Satu kata kerja, enam wajah yang paling sering dipakai</div><div class='gd-sec'><b>Golongan 1: contoh <span class='gd-jp'>飲む</span></b>. Caranya, ganti “む” di akhir dengan bunyi lain dari baris yang sama:<br>む diganti み, tambah ます: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span></span> (minum, bentuk sopan)<br>む diganti ま, tambah ない: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span></span> (tidak minum)<br>む diganti め, tambah る: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲める</span></span> (bisa minum, bentuk potensial)<br>む diganti ま, tambah れる: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まれる</span></span> (diminum, bentuk pasif)<br>む diganti ま, tambah せる: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span> (menyuruh minum, bentuk kausatif)</div><div class='gd-sec'><b>Bentuk て Golongan 1</b> punya aturan sendiri, tergantung huruf terakhirnya:<br>う・つ・る → って: <span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰って</span></span><br>む・ぶ・ぬ → んで: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span></span><br>く → いて: <span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span>　ぐ → いで: <span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br>す → して: <span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span></div><div class='gd-sec'><b>Golongan 2: contoh <span class='gd-jp'>食べる</span></b>. Golongan ini paling gampang: selalu buang る, lalu tambahkan bagian berikutnya:<br><span class='gd-jp'>食べます</span>、<span class='gd-jp'>食べない</span>、<span class='gd-jp'>食べて</span>、<span class='gd-jp'>食べられる</span> (bisa makan)、<span class='gd-jp'>食べられる</span> (dimakan)、<span class='gd-jp'>食べさせる</span> (menyuruh makan)<br>Bentuk potensial dan pasif Golongan 2 <b>sama persis</b>, jadi kamu hanya bisa membedakannya dari konteks.</div><div class='gd-sec'><b>Golongan 3: cuma dua, hafalkan saja</b><br><span class='gd-jp'>する</span>: <span class='gd-jp'>します</span>、<span class='gd-jp'>しない</span>、<span class='gd-jp'>して</span>、<span class='gd-jp'>できる</span> (bisa melakukan)、<span class='gd-jp'>される</span> (dilakukan)、<span class='gd-jp'>させる</span> (menyuruh melakukan)<br><span class='gd-jp'>来る</span>: <span class='gd-jp'>来ます</span>、<span class='gd-jp'>来ない</span>、<span class='gd-jp'>来て</span>、<span class='gd-jp'>来られる</span> (bisa datang; bentuk pasifnya juga sama)、<span class='gd-jp'>来させる</span> (menyuruh datang)<br>Kanji 来る tidak berubah, tapi cara bacanya ikut berubah:<br>Bentuk kamus dan bentuk ば dibaca く (くる、くれば);<br>bentuk ます, bentuk て, dan bentuk た dibaca き (きます、きて、きた);<br>bentuk ない, potensial, pasif, dan kausatif dibaca こ (こない、こられる、こさせる).</div><div class='gd-h'>Bentuk-bentuknya tidak berubah “satu per satu berantai”</div><div class='gd-sec'>Semua bentuk di atas <b>langsung dibuat dari bentuk kamus</b>. Kamu tidak perlu mengubah ke bentuk ます dulu untuk membuat bentuk て, dan tidak perlu ke bentuk potensial dulu untuk membuat bentuk pasif.<br>Ada satu pola yang berguna: bentuk potensial, pasif, dan kausatif semuanya berakhir “〜る”, jadi <b>setelah jadi, ia adalah kata kerja Golongan 2 yang baru</b> dan bisa diubah lagi dengan aturan Golongan 2:<br><span class='gd-pair'><span class='gd-jp'>飲める</span> → <span class='gd-jp'>飲めます</span></span><span class='gd-pair'><span class='gd-jp'>飲める</span> → <span class='gd-jp'>飲めない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞が読めます。</span> (Aku bisa membaca koran bahasa Jepang)</div><div class='gd-ex-line'>・<span class='gd-jp'>漢字はまだあまり書けない。</span> (Aku belum terlalu bisa menulis kanji)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata kerja pengecualian seperti <span class='gd-jp'>帰る</span> itu Golongan 1, jadi bilangnya <span class='gd-jp'>帰ります</span>、<span class='gd-jp'>帰らない</span>、<span class='gd-jp'>帰って</span>, bukan 帰ます、帰ない、帰て.<br>・Untuk kata kerja berakhiran う, saat membuat bentuk ない, pasif, dan kausatif, う diganti <b>わ</b>, bukan あ: <span class='gd-jp'>買わない</span>、<span class='gd-jp'>買われる</span>、<span class='gd-jp'>買わせる</span>.<br>・Bentuk て dari <span class='gd-jp'>行く</span> adalah <span class='gd-jp'>行って</span>, tidak mengikuti aturan “く → いて”, jadi tidak boleh 行いて.<br>・Bentuk potensial dari “kata benda＋する” dibuat dengan mengganti する menjadi <span class='gd-jp'>できる</span>: <span class='gd-jp'>勉強できる</span> (bisa belajar). <span class='gd-jp'>勉強される</span> adalah bentuk pasif, artinya beda.<br>・Dalam percakapan sehari-hari kamu sering dengar <span class='gd-jp'>食べれる</span>、<span class='gd-jp'>見れる</span> (tanpa ら). Ini sangat umum saat ngobrol, tapi untuk ujian dan tulisan formal pakai <span class='gd-jp'>食べられる</span>、<span class='gd-jp'>見られる</span>.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'>Sama-sama <span class='gd-jp'>飲む</span>, bentuk potensial, pasif, dan kausatif hanya beda satu-dua bunyi, tapi artinya sama sekali berbeda:<br><b>Bisa</b>: bentuk potensial</div><div class='gd-ex-line'>・<span class='gd-jp'>少しならお酒が飲める。</span> (Kalau sedikit, aku masih bisa minum alkohol)</div><div class='gd-sec'><b>Di- (pasif)</b>: bentuk pasif</div><div class='gd-ex-line'>・<span class='gd-jp'>弟に私のジュースを飲まれた。</span> (Jusku diminum adikku)</div><div class='gd-sec'><b>Menyuruh</b>: bentuk kausatif</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもに薬を飲ませる。</span> (Membuat anak minum obat)</div><div class='gd-warn'>Trik cepat: untuk Golongan 1, lihat ekornya. 「え段音＋る」 artinya “bisa”, 「あ段音＋れる」 artinya “di-”, 「あ段音＋せる」 artinya “menyuruh”. Untuk Golongan 2, 「られる」 bisa berarti “bisa” atau “di-”, lihat konteksnya; 「させる」 pasti “menyuruh”.</div><div class='gd-h'>Yang bisa dipelajari berikutnya</div><div class='gd-sec'>Kalau penggolongan sudah lancar, pelajari bentuk-bentuknya satu per satu lebih dalam: bentuk ajakan (<span class='gd-jp'>飲もう</span>), bentuk potensial, bentuk ば (<span class='gd-jp'>飲めば</span>), bentuk pasif, dan bentuk kausatif. Terakhir, pelajari bentuk kausatif-pasif yang menggabungkan kausatif dan pasif (<span class='gd-jp'>飲ませられる</span>／<span class='gd-jp'>飲まされる</span>, dipaksa minum).</div>"});
